(window.GIM_TS=window.GIM_TS||{})["Horayot.0"]={"from":0,"a":[["\u0003הורו בית דין\u0004 בשגגה להתיר \u0003לעבור על אחת מכל מצו‍ת האמורות בתורה, והלך היחיד ועשה\u0004 כן ב\u0003שוגג על פיהם\u0004 על פי הוראתם, \u0003בין שעשו\u0004 דייני בית הדין עצמם מעשה כהוראתם \u0003ועשה\u0004 אותו יחיד \u0003עמהן\u0004 ביחד, \u0003בין שעשו ו\u0004הוא \u0003עשה אחריהן, בין שלא עשו ו\u0004הוא עצמו \u0003עשה\u0004 בלבד, בכל אלו המקרים — הרי הוא \u0003פטור\u0004 מלהביא קרבן, \u0003מפני שתלה בבית דין.\u0004","אם \u0003הורו בית דין, וידע אחד מהן\u0004 מן הדיינים \u0003שטעו,\u0004 אף שהרוב היה כנגדו, \u0003או\u0004 שהיה \u0003תלמיד והוא ראוי\u0004 בעצמו \u0003להוראה, והלך ועשה על פיהן\u0004 לפי הוראת בית הדין, \u0003בין ש\u0004הם \u0003עשו ו\u0004הוא \u0003עשה עמהן, בין ש\u0004הם \u0003עשו ו\u0004הוא \u0003עשה אחריהן, בין ש\u0004הם \u0003לא עשו ו\u0004הוא \u0003עשה\u0004 — \u0003הרי זה חייב\u0004 על אותה עבירה, \u0003מפני שלא תלה בבית דין\u0004 אלא בדעת עצמו. \u0003זה הכלל: התולה בעצמו\u0004 — \u0003חייב, והתולה בבית דין\u0004 — \u0003פטור.\u0004","\u0003אמר שמואל: לעולם אין\u0004 הדיינים שב\u0003בית דין חייבין\u0004 להביא קרבן על הוראתם השגויה \u0003עד שיאמרו להם\u0004 לשואלים אותם: \u0003\"מותרין אתם\". רב דימי מנהרדעא אמר: עד שיאמרו להם \"מותרין אתם לעשות\"; מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שצריכים הם גם להגיד \"לעשות\"? \u0003לפי שלא נגמרה הוראה\u0004 אם אומרים רק \"מותרים אתם\", שמא היתה זו רק הבעת דעה ולא הוראה למעשה.","\u0003אמר אביי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 ראיה לשיטת רב דימי: אחד החכמים שחלק ולא קיבל דעת בית הדין (\"זקן ממרא\") ובא לירושלים מקום בית הדין הגדול, והם החליטו כנגד דעתו, ואחר כך \u0003חזר לעירו\u0004 ועדיין \u0003שנה ולימד כדרך שלימד\u0004 קודם, ולא שינה את דעתו מפני הוראת בית דין — \u0003פטור,\u0004 שאינו אלא מביע את דעתו, ואולם אם \u0003הורה לעשות\u0004 — הרי הוא \u0003חייב\u0004 מיתה. הרי שלא די באמירת \"מותרים אתם\" כדי שתיחשב זו הוראה.","\u0003אמר ר' אבא, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 ראיה לשיטת רב דימי: אשה שנעלם בעלה והעידו עדים (או היתה ראיה אחרת) שמת בעלה ו\u0003הורו לה בית דין להנשא, והלכה וקלקלה\u0004 (וזנתה) ולבסוף נמצא שבעלה חי — \u0003חייבת בקרבן\u0004 חטאת, משום שעשתה עבירה בשגגה, ואינה יכולה לטעון שעשתה על פי בית דין, \u0003ש\u0004כן \u0003לא התירו לה\u0004 בית דין \u0003אלא להנשא,\u0004 משמע שלא די שבית הדין אומרים באופן כללי שהיא מותרת אלא הם צריכים לומר שמותר לה להינשא.","\u0003אמר רבינא, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דבר זה, מדיוק לשון משנתנו \u0003\"הורו בית דין לעבור על אחת מכל מצו‍ת האמורות בתורה\", תו לא מידי\u0004 \u0005[ואין\u0006 צורך \u0005עוד בדבר]\u0006 שהרי הלשון \"הורו לעבור\" משמעה כאשר הורו לעשות מעשה. עד כאן לשון אחת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך את שיטותיהם של החכמים הללו ש\u0003אמר שמואל: אין בית דין חייבין עד שיאמרו להם \"מותרים אתם לעשות\".\u0004 ואילו \u0003רב דימי מנהרדעא אמר: אפילו\u0004 אמרו \u0003\"מותרים אתם\"\u0004 — \u0003נגמרה הוראה\u0004 בכך. \u0003אמר אביי, והא לא תנן הכי\u0004 \u0005[והרי לא שנינו כך],\u0006 כדברי רב דימי, ששנינו בזקן ממרא: \u0003חזר לעירו, ושנה או לימד כדרך שלימד\u0004 — \u0003פטור,\u0004 אם \u0003הורה לעשות\u0004 — \u0003חייב,\u0004 משמע שאין גמר הוראה אלא כשמורה לעשות.","\u0003אמר ר' אבא, והא לא תנן הכי\u0004 \u0005[והרי לא שנינו כך]:\u0006 \u0003הורו לה בית דין להנשא, והלכה וקלקלה\u0004 (וזנתה) — \u0003חייבת בקרבן, שלא התירו לה אלא להנשא.\u0004","\u0003אמר רבינא, והא לא תנן הכי\u0004 \u0005[והרי לא שנינו כך],\u0006 ששנינו: \u0003הורו בית דין לעבור על אחת מכל מצו‍ת האמורות בתורה, תו לא מידי\u0004 \u0005[אין\u0006 צורך \u0005עוד בדבר]\u0006 בראיה נוספת.","שנינו במשנה: \u0003והלך היחיד ועשה שוגג על פיהם.\u0004 ושואלים: \u0003וניתני\u0004 \u0005[ושישנה]:\u0006 רק \u0003\"ועשה על פיהם\", \"שוגג\" למה לי?\u0004 והרי ברור שהיה שוגג! \u0003אמר רבא: \"שוגג\"\u0004 בא \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 מקרה נוסף, \u0003הורו בית דין שחלב מותר, ו\u0004אותו אדם \u0003נתחלף לו\u0004 בשגגה \u0003חלב בשומן\u0004 המותר בודאי, והוא סבר שהוא אוכל שומן, \u0003ואכלו\u0004 — הרי זה \u0003פטור,\u0004 ויהיה הפירוש במשנה \u0003\"על פיהם\"\u0004 כוונתו \u0003על פיהם ממש,\u0004 ו\"שוגג\" — כאשר שגג במעשהו שהתחלף לו חלב בשומן.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003אמר רבא\u0004 אחרת, וכך הוא פירוש המשנה: \u0003\"שוגג\"\u0004 — ששגגתו היתה דווקא מפני שעשה \u0003על פיהם הוא\u0004 ש\u0003פטור, אבל\u0004 אם \u0003נתחלף לו חלב בשומן ואכלו\u0004 — הרי זה \u0003חייב\u0004 להביא קרבן, משום ששגגתו אינה תלויה בבית דין אלא בטעותו שלו.","ומעירים: \u0003מילתא דפשיטא ליה\u0004 \u0005[דבר ש\u0006היה \u0005פשוט לו]\u0006 \u0003לרבא\u0004 או לצד זה או לצד זה \u0003קמיבעיא ליה\u0004 \u0005[היה מסופק לו]\u0006 \u0003לרמי בר חמא, דבעי\u0004 \u0005[ששאל]\u0006 \u0003רמי בר חמא: הורו בית דין שחלב מותר, ונתחלף לו\u0004 חלב \u0003בשומן ואכלו, מהו?\u0004","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003הלך יחיד ועשה שוגג על פיהם כו', שוגג על פיהם\u0004 הכפילות הזו \u0003למה לי? לאו לאתויי\u0004 \u0005[האם לא להביא]\u0006 ש\u0003הורו בית דין שחלב מותר, ונתחלף לו חלב בשומן ואכלו\u0004 — \u0003פטור.\u0004 ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003שוגג על פיהם הוא\u0004 ש\u0003פטור,\u0004 רק כאשר עשה על פיהם ממש, \u0003אבל נתחלף לו חלב בשומן ואכלו\u0004 — הרי זה \u0003חייב.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך היה: \u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממשנתנו: \u0003הלך יחיד ועשה שוגג על פיהם; מאי לאו\u0004 \u0005[האם לא]\u0006 כוונת הדברים היא \u0003שוגג על פיהם\u0004 דווקא \u0003הוא\u0004 ש\u0003פטור, אבל נתחלף לו חלב בשומן ואכלו\u0004 — \u0003חייב.\u0004 ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 כוונת המשנה \u0003או שוגג, או על פיהם.\u0004","ומעירים: בעיה זו כבר היא שנויה \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של אמוראים קודמים: \u0003הורו בית דין שחלב מותר, ונתחלף לו חלב בשומן ואכלו\u0004 — \u0003רב אמר: פטור\u0004 שהרי בית דין הורו שמותר, \u0003ור' יוחנן אמר: חייב,\u0004 שלא עשה ממש על פיהם. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' יוחנן: נאמר \"אם נפש אחת תחטא בשגגה \u0003מעם הארץ בעשותה\u0004 אחת ממצוות ה' אשר לא תעשינה ואשם\" (ויקרא ד, כז), \"מעם הארץ\" — בא למעט, \u0003פרט למשומד\u0004 המביא קרבן חטאת על שגגתו, שאין מקבלים את קרבנו מפני שמה שעשה בשעתו, נחשב כזדון.","\u0003ר' שמעון בן יוסי אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 לענין משומד \u0003אינו צריך\u0004 לראיה זו, שכן \u0003הרי הוא אומר\u0004 בכתוב: \u0003\"אשר לא תעשינה בשגגה ואשם או הודע\u0004 אליו חטאתו\" (ויקרא כז —כח), לומר: דווקא \u0003השב\u0004 ומתחרט על מעשהו כתוצאה \u0003מידיעתו,\u0004 כאשר נודע לו שחטא בשגגה — הוא זה ש\u0003מביא קרבן על שגגתו,\u0004 ואולם מי ש\u0003לא שב מידיעתו,\u0004 שגם כשנודע לו שחטא אינו חוזר בתשובה על מעשהו — הוא \u0003אינו מביא קרבן\u0004 גם \u0003על שגגתו.\u0004","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום להלכה זו, \u0003הא\u0004 \u0005[הרי]\u0006 אף במקרה זה שהתחלף לו חלב בשומן \u0003לא שב מידיעתו הוא,\u0004 שהרי גם אם יוודע לו שאכל חלב, גם כן לא יתחרט, שהרי הוא סומך על פסק בית הדין שהתירו את הדבר.","\u0003אמר רב פפא, קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוחנן: כיון דכי מתידע להו לבי דינא הדרי בהו\u0004 \u0005[שכאשר יוודע להם\u0006 הדבר \u0005לבית הדין\u0006 הטעות, הם \u0005יחזרו בהם]\u0006 מהוראתם, \u0003והוא נמי הדר ביה\u0004 \u0005[גם כן יחזור בו],\u0006 כאשר נודע לו שאכל חלב שהותר בגלל שגגת בית הדין, לכן \u0003שב מידיעתו קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003וחייב\u0004 להביא קרבן.","\u0003אמר רבא:\u0004 אף על פי שרב אומר שהוא פטור, וחטאו תלוי בבית הדין, \u0003מודה רב שאינו משלים לרוב צבור,\u0004 כי בית הדין מביא קרבן רק כשרוב ציבור חטאו על פיהם, ואדם זה שסבור שהוא שומן אינו מצטרף לרוב הציבור, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בשגגה\"\u0004 — לומר: \u0003עד שיהו כולן בשגגה אחת\u0004 והוא שגגה אחרת היתה בידו.","שנינו במשנה: \u0003בין שעשו ועשה עמהן\u0004 בין שעשו ועשה אחריהן, בין שלא עשו ועשה — פטור. ושואלים: \u0003למה ליה למיתנא כל הני\u0004 \u0005[לו\u0006 לתנא שבמשנתנו \u0005לשנות\u0006 את \u0005כל\u0006 שלושת המקרים \u0005האלה]?\u0006 \u0003בשלמא רישא\u0004 \u0005[נניח בראשה]\u0006 של ההלכה אפשר לומר ש\u0003לא זו אף זו קתני\u0004 \u0005[שנה],\u0006 כלומר שכל מקרה מוסיף חידוש על קודמו, שלא זו בלבד אם עשו ועשה עמהם, הריהו פטור כיון שתלה בבית דין, אלא אפילו עשה אחריהם הריהו פטור. ולא עוד אלא אפילו שעשה הוא בפני עצמו והם לא עשו, בכל זאת נחשב כתולה בהם, ופטור. \u0003אלא סיפא דלחיובא\u0004 \u0005[בסוף\u0006 המשנה שבא הדבר \u0005לחייב אותו],\u0006 \u0003איפכא מיבעי ליה\u0004 \u0005[ההיפך היה צריך לו לשנות]\u0006 ולהתחיל במקרה הפשוט ביותר לחייב — כאשר הם לא עשו והוא עשה, אם התנא משתמש באופן זה של לשון \"לא זו אף זו\"!"],["ומשיבים: בסוף המשנה בסגנון של \u0003\"זו ואין צריך לומר זו\" קתני\u0004 \u0005[שנה]\u0006 התנא, כלומר שנויים הם המקרים בסדר שבו כל מקרה פשוט יותר מהמקרה הקודם לו.","שנינו במשנה: \u0003וידע אחד מהן שטעו או תלמיד וראוי להוראה.\u0004 ושואלים: \u0003תרתי\u0004 \u0005[שנים]\u0006 שני מקרים אלו, \u0003למה לי\u0004 לשנותם? ומדוע לא די באחד בלבד, ואין צורך לשנות גם תלמיד וראוי להוראה? \u0003אמר רבא: איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שחייב, אמורים דווקא במי שהוא \u0003גמיר\u0004 \u0005[למד]\u0006 \u0003ו\u0004גם \u0003סביר\u0004 \u0005[סובר]\u0006 ומבין דברים בעצמו, \u0003אבל\u0004 מי ש\u0003גמיר\u0004 \u0005[למד]\u0006 \u0003ולא סביר\u0004 \u0005[סובר]\u0006 — \u0003לא\u0004 חייב בקרבן, לכן השמיענו התנא את המקרה של תלמיד וראוי להוראה — שאף זה חייב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 והרי תלמיד הראוי \u0003להוראה\u0004 — \u0003גמיר וסביר משמע\u0004 \u0005[למד וסובר משמעו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא, \u0003אנא הכי קאמינא\u0004 \u0005[אני כך אומר]:\u0006 \u0003אי מההיא\u0004 \u0005[אם מאותה]\u0006 הלכה ראשונה במשנה (\"אחד מהם\") בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא אם הוא \u0003גמיר וסביר\u0004 \u0005[למד וסובר],\u0006 \u0003אבל גמיר\u0004 \u0005[למד]\u0006 \u0003ולא סביר\u0004 \u0005[סובר]\u0006 — \u0003לא,\u0004 לכן \u0003תנא\u0004 \u0005[שנה]\u0006 תלמיד \u0003ראוי להוראה, ממשנה יתירה\u0004 ששנה אנו מבינים ש\u0003אפילו גמיר\u0004 \u0005[למד]\u0006 \u0003ולא סביר\u0004 \u0005[סובר],\u0006 או \u0003סביר\u0004 \u0005[סובר]\u0006 \u0003ולא גמיר\u0004 \u0005[למד]\u0006 עדיין, בכל זאת כיון שהוא תולה בדעת עצמו הרי הוא חייב.","\u0003\"ראוי להוראה וכו' \".\u0004 ושואלים: \u0003כגון מאן\u0004 \u0005[מי]\u0006 נקרא \"תלמיד הראוי להוראה\"? \u0003אמר רבא: כגון שמעון בן עזאי ושמעון בן זומא,\u0004 שלא נסמכו והיו גדולי הדור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: כי האי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003מזיד הוא,\u0004 שהרי אדם גדול כזה בוודאי אינו טועה, ואם פסק להיתר מזיד הוא ופטור מקרבן!","והשיב לו רבא: \u0003ולטעמיך\u0004 \u0005[ולשיטתך],\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]:\u0006 על הכתוב: \u0003\"בעשתה אחת\"\u0004 (ויקרא ד, כז), לומר ש\u0003יחיד העושה מפי עצמו\u0004 — \u0003חייב,\u0004 אם עושה \u0003בהוראת בית דין\u0004 — \u0003פטור, כיצד? הורו בית דין שחלב מותר, ונודע לאחד מהן שטעו, או\u0004 שהיה \u0003תלמיד יושב לפניהן וראוי להוראה כגון שמעון בן עזאי,\u0004 וטעה ועשה על פי בית הדין, \u0003יכול יהא פטור? תלמוד לומר: \"בעשתה אחת\", יחיד העושה על פי עצמו\u0004 — \u0003חייב,\u0004 ומי שעשה \u0003בהוראת בית דין\u0004 — \u0003פטור!\u0004","ושואלים: ומכל מקום אם מדובר באדם גדול \u0003אלא היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 שיהיה אדם כזה עשוי להיחשב כשוגג? ומשיבים: \u0003כגון\u0004 ש\u0003ידע\u0004 שהדבר הזה שהתירוהו בית הדין הוא \u0003אסור, וקא טעי\u0004 \u0005[והוא טועה]\u0006 \u0003במצוה לשמוע דברי חכמים,\u0004 שהוא סבור שמצוה לשמוע דברי חכמים, אפילו כשהוא בטוח שאינם צודקים. אם כן \u0003לדידי נמי\u0004 \u0005[לדעתי גם כן]\u0006 מה שאמרתי כגון שמעון בן זומא או שמעון בן עזאי הכוונה ש\u0003טעי\u0004 \u0005[טועה]\u0006 \u0003במצוה לשמוע דברי חכמים,\u0004 ומפני שטעו בדבר זה — חייבים בקרבן.","שנינו במשנה: \u0003זה הכלל: התולה בעצמו\u0004 — \u0003חייב.\u0004 ושואלים: לשון כללית זו (\"זה הכלל\") \u0003לאיתויי מאי\u0004 \u0005[להביא\u0006 לרבות \u0005מה]\u0006 היא באה, ואיזה מקרה שלא נזכר היא באה להוסיף? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003מבעט בהוראה,\u0004 כלומר מי שרגיל לבוז תמיד להוראות בית הדין, ועושה רק מדעת עצמו.","וכמו כן, לשון כללית זו שנאמרה במשנה \u0003תולה בבית דין\u0004 פטור מה באה לרבות? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003הורו בית דין וידעו שטעו וחזרו בהן.\u0004 והוא לא ידע שחזרו בהם, ונהג על פי הוראתם הראשונה, שנמצא שתלה בדעת בית דין. ושואלים על כך: \u0003הא בהדיא קתני לה\u0004 \u0005[\u0006הרי מקרה \u0005זה בפירוש שונה אותה]\u0006 במשנה הבאה, ואין צורך לרבות אותו במשנתנו! ומשיבים: \u0003תני\u0004 \u0005[שונה]\u0006 קודם באופן סתום \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מפרש.\u0004","\u0003אמר רב יהודה אמר שמואל: זו\u0004 כל שיטת משנתנו שכל יחיד שעשה כהוראת בין דין פטור מקרבן היא \u0003דברי ר' יהודה, אבל חכמים אומרים: יחיד שעשה\u0004 \u0003בהוראת בית דין\u0004 — \u0003חייב.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 שיטת \u0003ר' יהודה\u0004 זו שרמזנו לה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \"אם נפש אחת תחטא בשגגה בעשתה\" (ויקרא ד, כז) — \u0003הרי אלו שלשה מעוטין\u0004 (\"אחת\", \"בשגגה\", \"בעשותה\"), ואחד המיעוטים הללו בא ללמדנו הלכה זו: \u0003העושה מפי עצמו\u0004 — \u0003חייב,\u0004 עשה \u0003בהוראת בית דין\u0004 — \u0003פטור.\u0004","ושואלים: \u0003מאי רבנן\u0004 \u0005[מהי\u0006 שיטת \u0005חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003עדיין אני אומר: מיעוט קהל שחטאו\u0004 על פי הוראת בית דין — הם \u0003חייבין\u0004 להביא קרבן על שגגתם, לפי \u0003שאין בית דין מביאין על ידיהן\u0004 (בגללם) קרבן \u0003פר\u0004 העלם דבר של ציבור (אלא אם כן חטאו רוב הקהל), ואולם יש מקום לומר ש\u0003רוב קהל שחטאו יהו פטורין\u0004 מלהביא קרבן, \u0003שהרי בית דין מביאין על ידיהם פר\u0004 העלם דבר של ציבור? \u0003תלמוד לומר: \"מעם הארץ\"\u0004 (ויקרא ד, כז) — \u0003אפילו רובה\u0004 של קהל, \u0003ואפילו כולה\u0004 אינם נפטרים משום שבית הדין הורו כן.","ונברר: \u0003במאי\u0004 \u0005[במה\u0006 מדובר\u0005]?\u0006 כיצד היה חטאם של רוב הקהל? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בשגגת מעשה,\u0004 מפני טעות מסויימת ולא בגלל הוראת בית דין, אם כן מה שנאמר בטעם הדבר \"שהרי בית דין מביאין על ידיהם\" אינו מובן, שהרי זה \u0003בית דין שלא בהוראה,\u0004 \u0003בית דין מאי עבידתייהו\u0004 \u0005[מה מעשיהם]?\u0006 הרי אין להם קשר לדבר! כי \u0003שלא בהוראת בית דין, בית דין מי מייתו\u0004 \u0005[האם\u0006 הם \u0005מביאים]\u0006 קרבן \u0003שלא בהוראה? אלא\u0004 צריך לומר שעשו רוב הקהל \u0003בהוראה,\u0004 ואולם אף על כך יש לשאול: \u0003והא כי כתיב\u0004 \u0005[והרי כאשר נאמר]\u0006 \u0003\"מעם הארץ\"\u0004 — \u0003בשגגת מעשה הוא דכתיב\u0004 \u0005[שנאמר]\u0006 ולא בשגגת הוראה כלל!","\u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר]:\u0006 שצריך להוסיף דברים בברייתא ולשנותה כך: \u0003מיעוט קהל שחטאו בשגגת מעשה\u0004 הם \u0003חייבין, שאין בית דין מביאין על ידיהן פר בהוראה, הא\u0004 \u0005[הרי]\u0006 \u0003הן\u0004 עצמם שעשו בהוראה \u0003חייבין\u0004 בקרבן, וכמו כן חייבים בקרבן גם כשעשו בשגגת מעשה שלא בהוראה,","\u0003יכול רוב צבור שעשו בשגגת מעשה\u0004 שלא בהוראה \u0003יהו פטורין, שהרי בית דין מביאין עליהם פר בהוראה? תלמוד לומר: \"מעם הארץ\", אפילו רובו.\u0004 שאם לא היתה זו שגגה מתוך הוראת בית הדין, אין הבדל כמה היו השוגגים מעטים או רוב הקהל. מכאן ראיה שלדעת חכמים יחיד או מיעוט הקהל שעשה בהוראת בית הדין חייב.","\u0003אמר רב פפא: ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה כך? \u0003דלמא\u0004 \u0005[שמא]\u0006 במקרה כזה שחטאו מיעוט קהל בהוראת בית דין, \u0003לא הן ולא בית דין\u0004 מביאים משום שהם תלו בבית דין, ובית דין פטור משום שהיו רק מיעוט!","ודוחים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי איריא דקמהדר על רובא לחיובא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא \u0005שמחזר על רוב לחיוב]?\u0006 כלומר, מדוע רוצה התנא לחדש שגם אם רוב הקהל חטא יהיו חייבים בקרבן? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 הדברים אתה למד ש\u0003מיעוט\u0004 שעושים \u0003בהוראה קיימא ליה דמיחייבו\u0004 \u0005[מוחזק להם\u0006 כדבר פשוט \u0005שמחוייבים]\u0006 אפילו \u0003בהוראה,\u0004 ולפי שיטת רב פפא: \u0003ונהדר ברישא על מיעוטא דמיחייב\u0004 \u0005[ושיחזור בראש\u0006 להוכיח \u0005על מיעוט שמתחייב]\u0006 \u0003בשגגת מעשה, ולבסוף ניהדר\u0004 \u0005[יחזור]\u0006 ויביא ראיה \u0003על רובא לחיובא\u0004 \u0005[הרוב לחייב]\u0006 \u0003בשגגת מעשה\u0004 שהרי אין אנו יודעים עכשיו על מיעוט שעשו בשגגת מעשה שחייבים!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003מדלא מהדר\u0004 \u0005[משלא מחזר]\u0006 ולא מביא בברייתא בתחילה הוכחה \u0003על מיעוט דמיחייבין\u0004 \u0005[שחייבים]\u0006 \u0003בשגגת מעשה, ובסוף מהדר\u0004 \u0005[מחזר]\u0006 למצוא הוכחה \u0003על רובא לחיובא\u0004 \u0005[רוב שיהיה חייב]\u0006 \u0003בשגגת מעשה, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהיה פשוט לברייתא שאם עשו \u0003מיעוט בהוראה חייבין הן\u0004 על מה שעשו \u0003כשבה ושעירה\u0004 כדין כל חוטא שחטא בשגגה, \u0003ו\u0004כמו כן \u0003שלא בהוראה בשגגת מעשה חייבין\u0004 המיעוט שחטאו.","עד כאן שתי השיטות בענין זה, אבל שואלים: \u0003מכדי תרוייהו סתמי תנן\u0004 \u0005[הרי שתי\u0006 הברייתות \u0005הללו בסתם שנה],\u0006 \u0003ממאי דקמייתא\u0004 \u0005[ממה\u0006 יודע אתה \u0005שהראשונה]\u0006 היא שיטת \u0003ר' יהודה ובתרייתא רבנן\u0004 \u0005[והאחרונה\u0006 היא שיטת \u0005חכמים]?\u0006 \u0003אימא איפכא\u0004 \u0005[אמור להיפך]!\u0006 ומשיבים: \u0003מאן שמעת ליה דדריש מיעוטי כי האי גוונא\u0004 \u0005[\u0006את \u0005מי שמעת אותו ש\u0006הוא \u0005דורש\u0006 לשונות \u0005מיעוט\u0006 בדרך \u0005כגון זו]?\u0006 שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004"],["\u0003\"זאת תורת העולה היא\u0004 העולה על מוקדה על המזבח...\" (ויקרא ו, ב) — \u0003הרי אלו שלשה מיעוטין\u0004 (\"זאת\", \"העולה\", \"היא\") שבאים למעט שלושה מיני קרבנות, שלמרות שעלו על המזבח — מורידים אותם ממנו, והם: עולה שנשחטה בלילה, עולה שנשפך דמה לפני זריקה, וכן עולה שיצא דמה מחוץ לעזרה.","הרי שר' יהודה הוא הלומד בדרך זו כמה לשונות מיעוט. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 הוכחה אחרת שהברייתא השניה זו הפותחת ב\"ו \u0003עדיין אני אומר\" לא מצית מוקמת לה\u0004 \u0005[אינך יכול להעמיד אותה]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה, דקתני\u0004 \u0005[ש\u0006הרי \u0005שנה]\u0006 בה: \u0003רוב קהל שחטאו\u0004 — \u0003בית דין מביאין על ידיהן פר, ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' יהודה\u0004 היא, \u0003האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003צבור הוא דמייתי\u0004 \u0005[שמביאים]\u0006 את הפר, \u0003בית דין\u0004 — \u0003לא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: שבעה שבטים שחטאו\u0004 — \u0003מביאין שבעה פרים,\u0004 מכאן שהציבור מביאים פר, ולא בית הדין.","עד כאן ביארנו את משנתנו כדעת ר' יהודה, וחכמים חולקים עליו, \u0003ו\u0004אילו \u0003רב נחמן אמר שמואל\u0004 מעמיד את המשנה באופן אחר: \u0003זו\u0004 משנתנו היא \u0003דברי ר' מאיר, אבל חכמים אומרים: יחיד שעשה בהוראת בית דין\u0004 — \u0003חייב.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 אותה שיטת \u0003ר' מאיר ומאי רבנן\u0004 \u0005[ומהי\u0006 שיטת \u0005חכמים]\u0006 אליהן רומז שמואל? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הורו\u0004 בית דין \u0003ועשו\u0004 — \u0003ר' מאיר פוטר, וחכמים מחייבין.\u0004","ונברר: \u0003מאן\u0004 \u0005[מי\u0006 הם אלה\u0005]\u0006 ש\u0003עשו? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בית דין, מאי טעמא דרבנן דמחייבי\u0004 \u0005[מה הטעם של חכמים שמחייבים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול הורו בית דין ועשו בית דין\u0004 בעצמם, \u0003יכול יהו חייבין\u0004 פר העלם דבר של ציבור? \u0003תלמוד לומר:\u0004 \"ונעלם דבר מעיני \u0003הקהל ועשו\"\u0004 (ויקרא ד, יג), לומר ש\u0003מעשה תלוי בקהל והוראה תלויה בבית דין!\u0004","\u0003אלא\u0004 תפרש שהכוונה היא \u0003הורו בית דין ועשו רוב קהל,\u0004 אם כן, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר\u0004 ש\u0003פוטר? אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן במקרה ש\u0003הורו בית דין ועשו מיעוט קהל, ובהא קמיפלגי\u0004 \u0005[וב\u0006נושא \u0005זה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003יחיד\u0004 (וכמוהו גם מיעוט הקהל) \u0003שעשה בהוראת בית דין\u0004 — \u0003פטור, ומר סבר\u0004 \u0005[וחכם זה\u0006 חכמים \u0005סבור]:\u0006 \u0003יחיד שעשה בהוראת בית דין\u0004 — \u0003חייב.\u0004 ומכאן שמשנתנו בה שנינו שיחיד שעשה בהוראת בית דין פטור, הריהי כשיטת ר' מאיר.","\u0003אמר רב פפא:\u0004 מכאן אין להוכיח לענייננו. כי אפשר לפרש את מחלוקת ר' מאיר וחכמים בברייתא באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יחיד שעשה בהוראת בית דין\u0004 — \u0003פטור, אלא\u0004 ר' מאיר וחכמים בשאלה האם \u0003בית דין\u0004 עצמו \u0003משלים לרוב צבור קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 במקרה שאלה שעשו בהוראת בית דין לא היו רוב ציבור, אבל אם יצרפו אליהם את בית הדין עצמו (שהורו ועשו) יהא זה רוב.","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003בית דין משלים לרוב צבור\u0004 ולכן הציבור חייב, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003אין בית דין משלים לרוב צבור,\u0004 והרי זה נחשב כיחיד שעשה בהוראת בית דין ופטור. ואם כן, משנתנו אינה כר' מאיר דווקא.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 והסבר את מחלוקת ר' מאיר וחכמים באופן זה: הברייתא מדברת במקרה ש\u0003הורו בית דין ועשו רובו של קהל,\u0004 ובית דין הם החייבים להביא פר, ולכן פוטר ר' מאיר את הציבור מלהביא קרבן, \u0003ומאן\u0004 \u0005[ומיהם]\u0006 \u0003חכמים\u0004 המחייבים — זה שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר:\u0004 גם \u0003צבור מייתי\u0004 \u0005[מביאים]\u0006 \u0003ו\u0004גם \u0003בית דין מייתי\u0004 \u0005[מביאים]\u0006 את הקרבן.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 בהסבר מחלוקת ר' מאיר וחכמים כך: מדובר בדינו של \u0003שבט\u0004 אחד \u0003שעשה בהוראת בית דינו,\u0004 שלדעת ר' מאיר אין דין העלם דבר על ציבור חל על בית דין של שבט, ולכן פטור בית הדין מקרבן, \u0003ומאן\u0004 \u0005[ומיהם]\u0006 \u0003חכמים\u0004 המחייבים? שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שבט שעשה בהוראת בית דינו, אותו השבט חייב.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 את מחלוקת ר' מאיר וחכמים באופן זה: בברייתא מדובר \u0003כגון שחטאו ששה\u0004 שבטים \u0003והן\u0004 במספרם \u0003רובו של קהל, או שבעה\u0004 שבטים \u0003אף על פי שאינן רובו של קהל, ומתניתין מני\u0004 \u0005[ומשנתנו\u0006 דעת חכמים בה כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' שמעון בן אלעזר היא.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר משמו\u0004 של ר' מאיר: \u0003חטאו ששה והן רובו של קהל, או שבעה אף על פי שאינן רובו של קהל\u0004 — \u0003חייבין.\u0004 ומכל הדחיות הללו עולה שאין הוכחה לדברי רב נחמן בשם שמואל שמשנתנו היא כדעת ר' מאיר.","\u0003אמר רב אסי: ובהוראה\u0004 לקבוע מהו רובו של קהל \u0003הלך אחר רוב\u0004 בני ישראל, \u0003יושבי ארץ ישראל\u0004 בלבד הם הקובעים, \u0003שנאמר: \"ויעש שלמה בעת ההיא את החג וכל ישראל עמו קהל גדול מלבוא חמת עד נחל מצרים לפני ה' אלהינו שבעת ימים ושבעת ימים ארבעה עשר יום\"\u0004 (מלכים א ח, סה). ונברר את האמור בכתוב זה: \u0003מכדי כתיב\u0004 \u0005[הלוא נאמר]\u0006 \u0003\"וכל ישראל עמו\",\u0004 אם כן \u0003\"קהל גדול מלבוא חמת עד נחל מצרים\" למה לי,\u0004 ומה בא זה להוסיף? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הכתוב הנוסף ללמדנו: \u0003הני הוא דאיקרי\u0004 \u0005[אלה\u0006 היושבים בארץ ישראל \u0005הם שנקראים]\u0006 \u0003קהל, אבל הנך לא איקרי\u0004 \u0005[אחרים\u0006 שנמצאים בחוץ לארץ \u0005אינם נקראים]\u0006 \u0003קהל.\u0004","ועוד בענין רוב הקהל: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005],\u0006 שאם היו העושים בהוראת בית דין \u0003מרובין ו\u0004אחר כך \u0003נתמעטו,\u0004 כגון שמתו מקצתם ונעשו עכשיו מיעוט הקהל — \u0003היינו פלוגתא\u0004 \u0005[זוהי המחלוקת]\u0006 של \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006 שחלקו במשנה להלן (הוריות י,ב) בענין כהן משיח או מלך שחטאו בשגגה לפני מינויים, ואחר כך נתמנו לכהונות אלה, שלדברי חכמים כיון שבזמן חטאם היו הדיוטות הריהם מביאים קרבן כהדיוטות, ואילו ר' שמעון סבור שאם נודע להם החטא בהיותם הדיוטות מביאים כהדיוטות, ואם נודע להם לאחר שנתמנו הריהם פטורים. ולפי שיטות אלה אף במקרה זה של מרובים ונתמעטו חכמים יאמרו שכיון שחטאו בהיותם רוב — מביאים קרבן, ולדעת ר' שמעון יהא הדבר תלוי בזמן שנודעה להם השגגה אם היו באותה עת רוב או מיעוט.","ואולם יש לשאול להיפך, אם בזמן שחטאו הם היו \u0003מועטין ו\u0004אחר כך \u0003נתרבו,\u0004 כגון שמתו מקצת מרוב הקהל שלא חטאו, רק שעכשיו המיעוט שחטא הוא הרוב, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003מי פליגי\u0004 \u0005[האם חלוקים]\u0006 בכך \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים]?\u0006 ובאופן זה: \u0003ר' שמעון דאזיל בתר\u0004 \u0005[שהולך אחר]\u0006 זמן ה\u0003ידיעה מחייב, ורבנן דאזלי בתר\u0004 \u0005[וחכמים שהולכים אחר]\u0006 זמן ה\u0003חטאת\u0004 — \u0003פטרי\u0004 \u0005[פוטרים],\u0006 \u0003או לא,\u0004 אם כן \u0003מאי\u0004 \u0005[מהי]\u0006 המסקנה?","ודוחים: \u0003ותיסברא\u0004 \u0005[\u0006ויכול אתה \u0005לסבור כן]\u0006 לתלות הדין במקרה זה במחלוקת ר' שמעון וחכמים? \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' שמעון דאזיל\u0004 \u0005[שהולך]\u0006 \u0003אף בתר\u0004 \u0005[אחר]\u0006 \u0003ידיעה,\u0004 ומתי? \u0003היכי דהוי\u0004 \u0005[במקום שהיו]\u0006 גם ה\u0003ידיעה ו\u0004גם ה\u0003חטאה בחיוב,\u0004 שבין כהדיוט ובין כנשיא או כהן משיח יש חובת קרבן כלשהו על החוטא. אבל \u0003ידיעה\u0004 כזו ש\u0003לא\u0004 באה על ידה \u0003חטאה מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]?\u0006","ש\u0003אם כן,\u0004 שהיה הולך ר' שמעון גם אז רק אחר זמן הידיעה והיה מחייב במועטים ונתרבו. \u0003לייתי כי השתא\u0004 \u0005[שיביאו כמו\u0006 המצב \u0005עכשיו]\u0006 קרבן כהן גדול או מלך כשנודע להם לאחר שנתמנו, ולמה אמר ר' שמעון שבמקרה כזה פטור! \u0003אלא\u0004 ודאי שלשיטת \u0003ר' שמעון חטאה וידיעה בעי\u0004 \u0005[צריך].\u0006 ואין איפוא פתרון לשאלה שנשאלה.","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הורו בית דין\u0004 ש\u0003חלב מותר, ועשו מיעוט הקהל\u0004 על פי הוראתם, ואכלו חלב \u0003וחזרו בית דין בהן\u0004 מהוראתם, אבל אחר כך חזרו בהם שוב \u0003והורו\u0004 להתיר, \u0003ו\u0004אז \u0003עשו\u0004 על פיהם \u0003מיעוט אחר, מהו\u0004 הדין? וצדדי השאלה: \u0003כיון\u0004 ש\u0003שתי ידיעות נינהו\u0004 \u0005[הם]\u0006 \u0003לא מצטרף\u0004 המיעוט הראשון למיעוט השני, אף ששני מיעוטים אלה הם ביחד רוב קהל, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאידי ואידי\u0004 \u0005[שזה וזה]\u0006 איסור \u0003חלב הוא,\u0004 הרי הוא \u0003מצטרף?\u0004","\u0003ואם תמצא לומר: כיון דאידי ואידי\u0004 \u0005[שזה וזה]\u0006 \u0003חלב הוא מצטרף,\u0004 יש מקום לבעיה הבאה: אם היו \u0003מיעוט\u0004 ששגגו על פי הוראה אחת של בית דין \u0003בחלב שעל גבי הקבה, ומיעוט\u0004 שגגו על פי הוראה אחרת \u0003בחלב שעל גבי דקין, מהו\u0004 הדין? וצדדי שאלה זו: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי כיון דבתרי קראי קאתי\u0004 \u0005[שמשני מקראות הם באים]\u0006 שלכל סוג של חלב יש מקור אחר בכתוב, \u0003לא מצטרף, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאידי ואידי\u0004 \u0005[שזה וזה]\u0006 \u0003חלב הוא\u0004 והם נכללים באיסור אחד הריהו \u0003מצטרף?\u0004","\u0003ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר: שם חלב הוא ומצטרף,\u0004 יש מקום לבעיה הבאה: אם שגגו \u0003מיעוט\u0004 קהל בהוראת בית דין \u0003בחלב, ומיעוט\u0004 שגגו בהוראה שהורו \u0003בדם, מהו\u0004 הדין? וצדדי שאלה זו: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי כיון דתרי איסורי נינהו\u0004 \u0005[ששני איסורים\u0006 שונים \u0005הם]\u0006 \u0003וכיון\u0004 ש\u0003אין איסורן שוה\u0004 — \u0003לא מצטרף, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003קרבנן שוה\u0004 שעל שניהם מביאים חטאת — \u0003מצטרף? \u0004","\u0003ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר: כיון\u0004 ש\u0003קרבנן שוה מצטרף,\u0004 תתעורר עוד בעיה: אם היו \u0003מיעוט\u0004 ששגגו בהוראה \u0003בחלב, ומיעוט\u0004 אחר שגגו \u0003בעבודה זרה, מהו? הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי אין איסורן שוה ואין קרבנן שוה,\u0004 לפי שאף ביחיד השוגג בעבודה זרה מביא שעירה דוקא לכפרתו, אין המיעוטים מצטרפים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאידי ואידי\u0004 \u0005[שזה וזה]\u0006 עבירה שיש בה במזיד עונש \u0003כרת הוא,\u0004 יש בהם בכל זאת צד שיתוף ו\u0003מצטרף?\u0004 שאלות אלה לא נפתרו ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הורו בית דין שחלב מותר, ועשו\u0004 על פיהם \u0003מיעוט הקהל, ומת אותו בית דין ועמד בית דין אחר\u0004 במקומם, \u0003וחזרו והורו\u0004 אותה הוראה להיתר, \u0003ועשו מיעוט אחר,\u0004 מה יהא הדין?","ומפרטים: \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטת מי שאומר]\u0006 \u0003בית דין\u0004 בלבד \u0003מייתי\u0004 \u0005[מביא]\u0006 את הקרבן \u0003לא תיבעי\u0004 \u0005[תישאל\u0006 תסתפק\u0005]\u0006 \u0003לך\u0004 — \u0003דהא ליתנהו\u0004 \u0005[שהרי אין\u0006 כאן \u0005אותם]\u0006 דיינים שהורו ועל פיהם עשה רוב הקהל, שהרי בית הדין הראשון כבר מת, \u0003אלא כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — \u0003אליבא דמאן דאמר\u0004 \u0005[לפי שיטת מי שאומר]\u0006 שה\u0003צבור\u0004 הוא ש\u0003מייתי\u0004 \u0005[מביא],\u0006 אם כן \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 וצדדי השאלה: \u0003צבור הא קאי\u0004 \u0005[הרי עומד]\u0006 שהרי ביחד נמצא שחטאו רוב ציבור,"],["\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003ידיעה דההוא\u0004 \u0005[של אותו]\u0006 \u0003בית דין\u0004 ש\u0003הורו בעינן\u0004 \u0005[צריכים אנו];\u0006 ואותו בית דין הרי אינו קיים עוד! שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר ר' יונתן:\u0004 אפילו \u0003מאה\u0004 דיינים \u0003שישבו\u0004 בדין \u0003להורות,\u0004 והם דנו בדבר ושגגו — \u0003אין חייבין\u0004 בקרבן \u0003עד שיורו כולן, שנאמר\u0004 בחיוב הקרבן: \u0003\"ואם כל עדת ישראל ישגו\"\u0004 (ויקרא ד, יג), ולשון \"כל\" באה להדגיש: \u0003עד שישגו כולן\u0004 כלומר, \u0003עד שתפשוט\u0004 (תתקבל) \u0003הוראה בכל עדת ישראל,\u0004 שהוראה שגויה זו תהיה על דעת \"כל העדה\" — הסנהדרין. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הושעיא: הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 שהרי \u0003בכל התורה כולה קיימא לן\u0004 \u0005[מוחזק בידינו]\u0006 הכלל של \u0003רובו ככולו, ו\u0004אילו \u0003הכא\u0004 \u0005[כאן]\u0006 לא נאמר \"עדה\" בלבד, אלא \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כל העדה\",\u0004 והרי זו הדגשה יתירה, \u0003הואיל וכך, אפילו הן מאה\u0004 כולם צריכים להורות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הורו בית דין, וידע אחד מהן שטעו, או תלמיד וראוי להוראה, והלך ועשה על פיהם, בין שעשו ועשה עמהן, ובין שעשו ועשה אחריהן, ובין שלא עשו ועשה\u0004 — \u0003הרי זה חייב, מפני שלא תלה בבית דין.\u0004","ויש לדייק בלשון המשנה: \u0003האי\u0004 \u0005[זה]\u0006 אותו חכם \u0003הוא\u0004 ש\u0003חייב, הא\u0004 \u0005[הרי]\u0006 אם היה \u0003אחר\u0004 שעושה בהוראת בית דין — הריהו \u0003פטור, ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא נגמרה הוראה\u0004 על פי כל הדיינים, שהרי אמרנו שאם לא הורו כל בית הדין כולם אין זו קרויה הוראה! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שהרכין ההוא אחד מהן\u0004 שחלק עליהם \u0003בראשו\u0004 ונראה היה כמסכים להם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו ראיה הנוגעת לענין זה של ר' יונתן: \u0003הורו בית דין, וידע אחד מהן שטעו ואמר להן \"טועין אתם\"\u0004 — \u0003הרי אלו פטורים.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר להן \"טועין אתם\"\u0004 — ש\u0003פטורים, הא שתיק מישתק\u0004 \u0005[הרי\u0006 אם \u0005שתק]\u0006 — \u0003חייבין, וגמר לה\u0004 \u0005[ונגמרה\u0006 על ידי כך\u0005]\u0006 ה\u0003הוראה, ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא הורו כולן,\u0004 ואם כן, הרי זה שלא כדברי ר' יונתן! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003כגון שהרכין\u0004 אותו אחד \u0003בראשו.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב משרשיא\u0004 על דברי ר' יונתן ממה ששנינו: \u0003סמכו רבותינו על דברי רבן שמעון בן גמליאל ועל דברי ר' אלעזר בר' צדוק, שהיו אומרים:\u0004 \u0003אין גוזרין גזירה על הצבור אלא אם כן רוב הצבור יכולין לעמוד בה,\u0004","\u0003ואמר\u0004 על כך \u0003רב אדא בר אבא: מאי קרא\u0004 \u0005[מהו המקרא]\u0006 המלמד על כך? שנאמר: \u0003\"במארה\u0004 \u0003אתם נארים ואתי אתם קבעים הגוי כלו\"\u0004 (מלאכי ג,ט), שכל העם כולו קיבל עליו בשבועה (\"במארה\") את דיני המעשרות, ובכל זאת עברו עליהם. \u0003והא הכא\u0004 \u0003דכתיב\u0004 \u0005[והרי כאן שנאמר]\u0006 \u0003\"הגוי כלו\", ו\u0004בכל זאת \u0003רובא ככולא דמי\u0004 \u0005[הרוב כמו הכל נחשב],\u0006 שהרי מפסוק זה סמכו רבותינו שאין גוזרים גזירה אלא אם כן עם רוב הציבור יכולים לעמוד בה, מכאן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003ר' יונתן.\u0004 ומסכימים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005],\u0006 ונדחו דבריו.","ושואלים: אם כן, \u0003ואלא\u0004 מעתה שנדחו דבריו של ר' יונתן שנסמכו על ייתור הכתוב, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כל עדת\" דקאמר רחמנא\u0004 \u0005[שאמרה התורה]?\u0006 מה ההדגשה הזו באה ללמדנו? \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אי איכא\u0004 \u0005[אם נמצאים]\u0006 כל הדיינים \u0003כולם\u0004 ומחליטים כך (לפי דעת הרוב) — \u0003הויא\u0004 \u0005[הרי זו]\u0006 \u0003הוראה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 נמצאים כולם — \u0003לא הויא\u0004 \u0005[אין זו]\u0006 \u0003הוראה.\u0004","ובענין זה של מושב הדיינים \u0003אמר ר' יהושע: עשרה שיושבין בדין\u0004 — \u0003קולר\u0004 (השלשלת של ההולכים להיענש) \u0003תלוי בצואר כולן.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003אפילו תלמיד בפני רבו\u0004 אם ראה שנעשתה שגגה ולא תיקן — הרי החוב תלוי בו, ואינו רשאי לשתוק מפני כבוד הרב.","מסופר ש\u0003רב הונא כי הוה נפיק לבי דינא\u0004 \u0005[כאשר היה יוצא לבית הדין],\u0006 \u0003מייתי\u0004 \u0005[היה מביא]\u0006 \u0003עשרה תנאי דבי\u0004 \u0005[שוני משניות מבית]\u0006 \u0003רב לקמיה\u0004 \u0005[לפניו]\u0006 שיהיו כאילו שותפים עמו בדין, שהיה אומר \u0003כי היכי דנימטיין שיבא מכשורא\u0004 \u0005[כדי שיגיע לנו\u0006 רק \u0005שבב מן הקורה]\u0006 כלומר, שיחלקו אלה עמי באחריות לפסק הדין. וכיוצא בזה מסופר ש\u0003רב אשי כי הוו מייתי טרפתא לקמיה\u0004 \u0005[כאשר היו מביאים טריפה לפניו]\u0006 לשאול אם הבהמה היא טריפה או לא, \u0003מייתי\u0004 \u0005[היה מביא]\u0006 \u0003עשרה טבחי\u0004 \u0005[שוחטים]\u0006 \u0003ממתא מחסיא ומותיב קמיה\u0004 \u0005[ומושיבם לפניו],\u0006 \u0003אמר: כי היכא דנימטיין שיבא מכשורא\u0004 \u0005[כדי שיגיע לנו שבב מן הקורה].\u0006","\u0003הורו בית דין\u0004 הוראה בטעות, \u0003וידעו שטעו וחזרו בהן, בין שהביאו כפרתן\u0004 (קרבנם) על מה שהורו \u0003ובין שלא הביאו כפרתן, והלך\u0004 אדם שלא ידע שחזרו בהם \u0003ועשה על פיהן\u0004 — \u0003ר' שמעון פוטר\u0004 אותו מקרבן, \u0003ור' אלעזר אומר: ספק\u0004 הוא, ומביא אשם תלוי. \u0003איזהו ספק?\u0004 מתי נחשב דבר לספק להתחייב עליו באשם תלוי? אם \u0003ישב לו\u0004 אדם \u0003בתוך ביתו\u0004 ועשה כן — \u0003חייב\u0004 באשם, שהיה יכול לדעת שבית הדין חזר בו. \u0003הלך לו למדינת הים\u0004 והוא סומך עדיין על ההוראה הישנה — \u0003פטור.\u0004","\u0003אמר ר' עקיבא: מודה אני בזה\u0004 שהלך למדינת הים \u0003שהוא קרוב לפטור מן החובה. אמר לו בן עזאי: מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003זה מן היושב בביתו?\u0004 אמר לו: \u0003שהיושב בביתו אפשר היה לו שישמע, וזה\u0004 שבמדינת הים \u0003לא היה לו אפשר שישמע.\u0004 ומכאן באה המשנה להסביר באיזה ענין נחשב הדבר לשגגת הוראה שהציבור מביא עליה קרבן.","\u0003הורו בית דין לעקור את כל הגוף\u0004 של המצוה ולא פרט אחד ממנה, כגון ש\u0003אמרו: אין\u0004 איסור \u0003נדה בתורה, אין\u0004 איסור \u0003שבת בתורה, אין\u0004 איסור \u0003עבודה זרה בתורה\u0004 — \u0003הרי אלו פטורין.\u0004 שאין זו שגגת הוראה אלא טעות פשוטה. אם \u0003הורו לבטל מקצת\u0004 מהמצוה \u0003ולקיים מקצת\u0004 — \u0003הרי אלו חייבין.\u0004","\u0003כיצד?\u0004 אם \u0003אמרו: יש\u0004 איסור \u0003נדה בתורה אבל הבא על שומרת יום כנגד יום\u0004 על אשה שראתה דם נידה שלא בזמנה במשך יום אחד, שאז היא צריכה לשמור יום שני ולבדוק אם היא ממשיכה בנידתה, ואף אם לא ראתה ביום השני היא נחשבת אותו יום לנידה, והם הורו שהבא עליה \u0003פטור,\u0004 או שאמרו:","\u0003יש שבת בתורה, אבל המוציא מרשות היחיד לרשות הרבים פטור.\u0004","\u0003יש עבודה זרה בתורה, אבל המשתחוה\u0004 (שלא הקריב לה קרבן) \u0003פטור\u0004 — \u0003הרי אלו חייבין\u0004 על הוראת טעות, \u0003שנאמר: \"ונעלם דבר\"\u0004 (ויקרא ד, יג), לומר \u0003\"דבר\"\u0004 — פרט אחד, \u0003ולא כל הגוף.\u0004","שנינו במשנה שר' שמעון פוטר את מי שעשה על פי בית דין למרות שחזרו בהם. ועל כך \u0003אמר רב יהודה אמר רב: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון? הואיל וברשות בית דין הוא עושה. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 זאת בלשון אחרת: \u0003אמר רב יהודה אמר רב, אומר היה ר' שמעון: כל הוראה שיצאה\u0004 (שפשטה) \u0003ברוב צבור\u0004 אף שבית הדין חזר בו — \u0003יחיד העושה אותה פטור, לפי שלא ניתנה הוראה אלא להבחין בין שוגג למזיד\u0004 שהעושה על פי אותה ההוראה נחשב לשוגג שהרי תלה הדבר בהוראת בית הדין, ואדם זה שלא ידע שבית הדין חזר בו מהוראתו אף הוא הריהו שוגג ולא מזיד.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003פר העלם דבר של צבור ושעירי עבודה זרה\u0004 — \u0003בתחלה גובין עליהן\u0004 כלומר, גובים כסף מהציבור במיוחד לצורך זה, אלו \u0003דברי ר' שמעון. ר' יהודה אומר: מתרומת הלשכה הן באין\u0004 כלומר, היו מביאים קרבנות אלה מן התרומה הכללית שהציבור מביא בכלל לצורך הקרבנות. ולשיטת ר' שמעון עצמו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהיה אדם זה פטור, הלא \u0003כיון דגבי להו\u0004 \u0005[שגובים אותם]\u0006 את הכספים לצורך כל קרבן וקרבן חטאת של הציבור, \u0003הוי ליה\u0004 \u0005[נהיה לו]\u0006 הדבר בגדר \u0003\"הודע\u0004 אליו חטאתו\", שהרי מתוך המגבית בוודאי נודע לו שטעה בית הדין בהוראתו!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003כגון שגבו סתם,\u0004 ולא הודיעוהו לשם מה גובים, כך שלא ידע שבית הדין חזרו בהם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כגון\u0004 ש\u0003לא הוה ליה במתא\u0004 \u0005[היה בעיר]\u0006 בשעה שגבו בעירו, ולא נודע לו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003רב כאידך תנא סבר\u0004 \u0005[כמו התנא האחר\u0006 הוא \u0005סבור],\u0006 \u0003דתניא איפכא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005להיפך]\u0006 שבה נהפכו השיטות הללו וכך נאמר שם: \u0003בתחילה גובין להן, דברי ר' יהודה, ר' שמעון אומר: מתרומת הלשכה הן באין\u0004 ולפיכך לשיטת ר' שמעון שבברייתא זו יתכן שלא ידע אותו אדם שחזרו בהם בית הדין.","ועוד בענין זה \u0003תני\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 יחיד שעשה לאחר שחזרו בהם בית הדין \u0003ר' מאיר מחייב\u0004 אותו בקרבן חטאת, \u0003ור' שמעון פוטר, ר' אלעזר אומר: ספק, משום\u0004 (בשם) \u0003סומכוס אמרו: תלוי. אמר ר' יוחנן:\u0004 לענין \u0003אשם תלוי איכא בינייהו\u0004 \u0005[יש ביניהם,\u0006 בין ר' אלעזר לסומכוס, \u0005הבדל\u0006 בהלכה\u0005]\u0006 שלדעת ר' אלעזר מביא אשם תלוי, ולדעת סומכוס צד החיוב של האיש תלוי בספק, ואף אשם תלוי אינו מביא.","\u0003אמר ר' זירא: משל\u0004 לשיטת \u0003ר' אלעזר למה הדבר דומה? לאדם שאכל\u0004 חתיכה שהיא \u0003ספק חלב ספק שומן\u0004 וחשב שהוא שומן, ואכלה. \u0003ו\u0004אחר כך \u0003נודע לו\u0004 שהוא ספק איסור כרת, \u0003ש\u0004במקרה זה \u0003מביא אשם\u0004 תלוי. ואף לענין זה, כיון שנודע לו לאחר זמן שחזרו בית הדין, הרי זה כמי שספק בידו אם חטא."],["\u0003ולא מבעיא למאן דאמר\u0004 \u0005[נצרכה ל\u0006דעת \u0005מי שאומר]\u0006 \u0003צבור מייתי\u0004 \u0005[מביא]\u0006 קרבן, \u0003דמפרסמא מלתא\u0004 \u0005[שמתפרסם הדבר]\u0006 בציבור שחזרו בהם, \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003בית דין מביאין,\u0004 ש\u0003לא מפרסמא מלתא\u0004 \u0005[מתפרסם הדבר]\u0006 שחזרו בהם, מכל מקום יש לומר \u0003אי הוה שאיל, הוו אמרין ליה\u0004 \u0005[אם היה שואל, היו אומרים לו]\u0006 שחזרו בהם בית דין, ויש מקום לומר שעשה על דעת עצמו ולא תלה בבית הדין, לכן מביא אשם תלוי.","\u0003אמר ר' יוסי בר אבין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יוסי בר זבידא: משל\u0004 לשיטת \u0003סומכוס למה הדבר דומה? לאדם שהביא\u0004 קרבן \u0003כפרתו בין השמשות,\u0004 שהוא זמן מסופק, ספק יום ספק לילה, והרי זה \u0003ספק מבעוד יום נתכפר לו, ספק משחשכה נתכפר לו\u0004 ואין כפרתו כפרה, דינו \u0003שאין מביא אשם תלוי.\u0004","אף שבמקום שיש ספק אם חייב חטאת — מביא אשם תלוי, מכל מקום בבין השמשות שהוא ספק שאי אפשר לבררו אין זה ספק רגיל ולא מביא אשם תלוי, \u0003ולא מבעיא למאן דאמר\u0004 \u0005[נצרכה ל\u0006דעת \u0005מי שאומר]\u0006 \u0003בית דין מביאין,\u0004 ש\u0003לא אפרסמא מלתא\u0004 \u0005[התפרסם הדבר],\u0006 \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003צבור מביאין, דמפרסמא מלתא, והוו אמרינן ליה\u0004 \u0005[שמתפרסם הדבר, והיו אומרים לו]\u0006 שבית הדין חזרו בהם, \u0003דהכא\u0004 \u0005[שכאן]\u0006 הרי זה דומה ל\u0003ספק מבעוד יום ספק משחשכה, אי שאיל\u0004 \u0005[אם היה שואל]\u0006 \u0003לא אשכח אינש דמשייליה\u0004 \u0005[היה מוצא אדם לשאול אותו].\u0006","שנינו במשנה, \u0003אמר לו בן עזאי: מאי שנא מן היושב\u0004 בביתו? וענה לו ר' עקיבא שההולך למדינת הים אין לו אפשרות לשמוע. ושואלים: \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' עקיבא לבן עזאי\u0004 להסביר את ההבדל, וכיצד לא עמד חכם גדול כבן עזאי על כך?","\u0003אמר רבא:\u0004 כאן מדובר לא במי שכבר הלך למדינת הים, אלא במי ש\u0003החזיק בדרך,\u0004 שעדיין לא יצא למדינת הים, אלא שהוא טרוד בהכנות ליציאה, ובענין זה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003לבן עזאי חייב\u0004 — \u0003דהא בביתיה איתיה\u0004 \u0005[שהרי בביתו\u0006 הוא \u0005נמצא]\u0006 ואין הבדל בין זה לבין היושב בביתו, \u0003לר' עקיבא פטור\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003החזיק בדרך\u0004 והרי הוא כמי שיצא לדרך.","שנינו במשנה שאם \u0003הורו לו בית דין לעקור את כל הגוף,\u0004 אין זו הוראה, ובית דין פטורים. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ונעלם דבר\u0004 מעיני הקהל\" (ויקרא ד, יג) — \u0003ולא שיעקר המצוה כולה. כיצד? אמרו: אין נדה בתורה,\u0004 או שאמרו: \u0003אין שבת בתורה,\u0004 וכן אם אמרו: \u0003אין עבודה זרה בתורה, יכול יהו חייבין? תלמוד לומר: \"ונעלם דבר\", ולא שתתעלם מצוה כולה,\u0004 ואם הורו כך בטעות — \u0003הרי אלו פטורין.\u0004","\u0003אבל אמרו: יש נדה בתורה אבל הבא על שומרת יום כנגד יום פטור,\u0004 או שאמרו: \u0003יש שבת בתורה אבל המוציא מרשות היחיד לרשות הרבים פטור,\u0004 וכן אם אמרו: \u0003יש עבודה זרה בתורה אבל המשתחוה\u0004 לה \u0003פטור, יכול יהו פטורין? תלמוד לומר: \"ונעלם דבר\" ולא כל הגוף.\u0004","ומבררים, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול יהו פטורין.\u0004 ותוהים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בקיום מקצת וביטול מקצת פטורין, ובעקירת כל הגוף\u0004 כבר אמרנו שהם \u0003פטורין, במאי\u0004 \u0005[במה]\u0006 הם \u0003חייבין?\u0004 ומשיבים: ה\u0003תנא הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו],\u0006 \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003\"דבר\" כולה מילתא משמע\u0004 \u0005[כל הדבר משמעו]!\u0006 שנעלם עניינה של מצוה שלימה, \u0003תלמוד לומר: \"ונעלם דבר\".\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות]?\u0006 כיצד נובע מכאן מה שרצה להוכיח! \u0003אמר עולא: קרי ביה\u0004 \u0005[קרא בו]\u0006 כאילו היתה שם מ' כפולה \u0003\"ונעלם מדבר\".\u0004 מקצת הדבר, ולא כולו.","\u0003חזקיה אמר, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ועשו אחת מכל מצו‍ת\"\u0004 (ויקרא ד, יג), \u0003\"מכל מצו‍ת\"\u0004 — \u0003ולא כל מצו‍ת.\u0004 ותוהים: \u0003\"מצות\"\u0004 לפחות \u0003תרתי\u0004 \u0005[שתים]\u0006 \u0003משמע,\u0004 אם כן לא יביאו קרבן עד שיטעו באחת מן המצוות הרבות ויעקרו אותה לגמרי! \u0003אמר רב נחמן בר יצחק: \"מצות\" כתיב\u0004 \u0005[כתוב]\u0006 בו' אחת, ואנו קוראים בו \"מצות\" חסר.","\u0003רב אשי אמר: יליף\u0004 \u0005[למד]\u0006 גזירה שווה \u0003\"דבר\" \"דבר\" מזקן ממרא, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003בזקן ממרא: \"כי יפלא ממך דבר... לא תסור מן הדבר אשר יגידו לך ימין ושמאל\"\u0004 (דברים יז, ח-יא), \u0003מה\u0004 זקן \u0003ממרא\u0004 רק כשחולק על החכמים בענין שהוא \u0003מן הדבר ולא כל דבר, אף בהוראה\u0004 שטעו בה \u0003דבר ולא כל הגוף.\u0004","\u0003אמר רב יהודה אמר שמואל: אין בית דין חייבין\u0004 להביא קרבן \u0003עד שיורו בדבר שאין הצדוקין מודין בו.\u0004 שאין הצדוקים מקבלים תורה שבעל פה, אלא מבינים את המקרא ככתבו. כלומר, שיטעו בדבר שאינו מפורש בתורה, או נובע בפשטות מן הדברים. \u0003אבל בדבר ש\u0004גם \u0003הצדוקין מודין בו\u0004 — \u0003פטורין; מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003זיל קרי בי רב הוא\u0004 \u0005[לך קרא בבית הרב הוא]\u0006 כלומר, דבר זה פשוט עד כדי כך שגם התינוקות בבית הרב יודעים אותו, ואם בית דין טעו בזה אין זה נחשב שגגת בית דין.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 מתי חייבים, כשטעו ואמרו \u0003יש נדה בתורה, אבל הבא על שומרת יום כנגד יום פטור;\u0004 וקשה לדברי שמואל, \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 חייבים על כך? \u0003שומרת יום כנגד יום הא כתיב\u0004 \u0005[הרי נאמר]\u0006 בתורה בנדה שלא בזמן הוסת \u0003\"וספרה לה\"\u0004 (ויקרא טו, כח), \u0003מלמד שסופרת אחד לאחד\u0004 (\"שומרת יום כנגד יום\") ואם כן נאמר הדבר בכתוב ואף הצדוקים מודים בו!","ומשיבים: לא בעצם דין שומרת יום טעו, אלא \u0003דאמרי\u0004 \u0005[שאמרו]:\u0006 \u0003העראה\u0004 (תחילת ביאה) \u0003שריא\u0004 \u0005[מותרת]\u0006 באשה נדה, \u0003גמר ביאה הוא דאסירא\u0004 \u0005[שאסור].\u0006 ומקשים: \u0003הא נמי כתיב\u0004 \u0005[\u0006הרי \u0005זה גם כן כתוב]:\u0006 \u0003\"את מקורה הערה\"\u0004 (ויקרא כ, יח) שמפורש איסור העראה באשה נדה!","ומשיבים: \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 אם בא עליה \u0003כדרכה\u0004 — \u0003אסירא\u0004 \u0005[אסורה],\u0006 \u0003שלא כדרכה\u0004 (בפי הטבעת) — \u0003שריא\u0004 \u0005[מותרת].\u0006 ומקשים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"משכבי אשה\"\u0004 (ויקרא יח, כב) ומכאן עולה בפשטות שיש שני משכבים באשה, כדרכה ושלא כדרכה והרי זה כאילו כתוב במפורש!","ומשיבים: \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 כך: \u0003כדרכה\u0004 — \u0003אסור אפילו העראה, בשלא כדרכה\u0004 — \u0003גמר ביאה הוא\u0004 ש\u0003אסור, אבל העראה שריא\u0004 \u0005[מותרת].\u0006 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו נדה\u0004 עצמה בזמן וסתה \u0003נמי\u0004 \u0005[גם כן]\u0006 יתירו בה ויאמרו שרק גמר ביאה הוא שאסור ומדוע נאמר במשנה שטעו בשומרת יום כנגד יום!","\u0003אלא לעולם\u0004 בהעראה \u0003כדרכה, ודאמרי\u0004 \u0005[וש\u0006הם \u0005אומרים]:\u0006 \u0003העראה באשה דוה\u0004 (ראה שם יח) בנדה בזמן וסתה \u0003הוא דכתיבא\u0004 \u0005[שכתובה]\u0006 ולא בשומרת יום. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003זבה\u0004 דם ממקורה (שלא בזמן הוסת) \u0003לא הויא\u0004 \u0005[איננה]\u0006 \u0003אלא ביממי\u0004 \u0005[בימים]\u0006 ולא בלילות, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל ימי זובה\"\u0004 (ויקרא טו, כו).","ומיד שואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003יש שבת בתורה, אבל המוציא מרשות לרשות פטור.\u0004 ומקשים: לשמואל \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הוצאה הא כתיבא\u0004 \u0005[הרי נאמרה]:\u0006 \u0003\"לא תוציאו משא מבתיכם\"\u0004 (ירמיהו יז, כב) והצדוקים מודים בה!","ומשיבים: \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003הוצאה הוא\u0004 ש\u0003אסור,\u0004 אבל \u0003הכנסה\u0004 מרשות הרבים לרשות היחיד \u0003מותר. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003הוצאה הוא דאסירא\u0004 \u0005[שאסורה],\u0006 אבל \u0003מושיט וזורק\u0004 מרשות לרשות \u0003שרי\u0004 \u0005[מותר].\u0006","ועוד, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003יש עבודה זרה בתורה, אבל המשתחוה פטור; ואמאי\u0004 \u0005[ומדוע]?\u0006 הלא \u0003המשתחוה הא כתיבא\u0004 \u0005[הרי נאמר],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תשתחוה לאל אחר\"\u0004 (שמות לד, יד)!","ומשיבים: \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003כי אסירא\u0004 \u0005[כאשר אסורה]\u0006 \u0003השתחויה\u0004 הרי זו \u0003כדרכה,\u0004 כאשר זו דרך עבודתה של עבודה זרה זו, \u0003אבל שלא כדרכה\u0004 שאין משתחוים לה — \u0003שריא\u0004 \u0005[מותרת].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003השתחויה גופה\u0004 \u0005[עצמה]\u0006 \u0003כדרכה הוא דאסיר\u0004 \u0005[שאסור],\u0006 ומתי? \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה פשוט ידים ורגלים\u0004 שהיא השתחויה גמורה כמו במקדש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003השתחויה דלית\u0004 \u0005[שאין]\u0006 \u0003בה פשוט ידים ורגלים\u0004 — \u0003שריא\u0004 \u0005[מותרת].\u0006"],["ועוד בענין הוראת בית דין שיש בה עקירת מצוה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף:\u0004 אם הורו בית דין ש\u0003אין\u0004 איסור \u0003חרישה בשבת,\u0004 \u0003מהו?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דקא מודו בכולהו מלתא\u0004 \u0005[שהם מודים בכל הדבר]\u0006 בכל איסורי שבת, והוראתם אינה אלא לענין חרישה בלבד, הרי זה \u0003כביטול מקצת וקיום מקצת דמי\u0004 \u0005[נחשב],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דקא עקריין ליה\u0004 \u0005[שהם עוקרים את]\u0006 מלאכת ה\u0003חרישה כל עיקר,\u0004 הרי זה \u0003כעקירת גוף\u0004 מצות שבת \u0003דמי\u0004 \u0005[נחשב]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003יש נדה בתורה אבל הבא על שומרת יום כנגד יום פטור; ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא עקריין\u0004 \u0005[הרי עקרו]\u0006 את הדין המיוחד של \u0003שומרת יום כנגד יום כל עיקר,\u0004 משמע שדבר כזה אינו נקרא עקירת כל גוף המצוה!","ודוחים: \u0003אמר לך\u0004 \u0005[יכול היה לומר]\u0006 \u0003רב יוסף\u0004 בתשובה לכך כי \u0003שומרת יום דקאמרין\u0004 \u0005[שאומרים]\u0006 \u0003כדשנין\u0004 \u0005[כמו שתירצנו]\u0006 בענין העראה ולא ביטלו את כל האיסור הזה כולו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003יש שבת בתורה, אבל המוציא מרשות היחיד לרשות הרבים פטור; ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא עקריין\u0004 \u0005[הרי עוקרים]\u0006 בית הדין בכך \u0003להוצאה כל עיקר!\u0004","ודוחים: \u0003התם נמי כדשנין\u0004 \u0005[שם גם כן\u0006 יש לומר \u0005כמו שתירצנו\u0006 מקודם\u0005]\u0006 שבית הדין עוקרים רק מקצת המלאכה. כגון הזורק והמושיט.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003יש עבודה זרה בתורה, אבל המשתחוה פטור;\u0004 ועל כך יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא עקריין\u0004 \u0005[והרי\u0006 הם \u0005עוקרים]\u0006 \u0003להשתחויה כל עיקר!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית אותה ראיה: \u0003השתחויה נמי כדשנין\u0004 \u0005[גם כן\u0006 יש לומר \u0005כמו שתירצנו\u0006 מקודם\u0005]\u0006 שהתירו רק בהשתחוויה מעטה, ולא עקרו את כל האיסור. ועוד בענין הוראת בית דין שיש בה עקירת מצוה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא:\u0004 הורו בית הדין ש\u0003אין\u0004 איסור \u0003שבת ב\u0004שנה ה\u0003שביעית\u0004 (שנת השמיטה), \u0003מהו?\u0004 ולפני שמבררים את השאלה, מקדימים ושואלים: \u0003במאי\u0004 \u0005[במה]\u0006 \u0003טעו,\u0004 מה גרם להם לטעות זו? \u0003בהדין קרא\u0004 \u0005[בפסוק זה]\u0006 שנאמר במצות השבת: \u0003\"בחריש ובקציר תשבת\"\u0004 (שמות לד, כא), והם מפרשים: \u0003בזמן דאיכא\u0004 \u0005[שיש]\u0006 \u0003חרישה\u0004 כלומר, בשאר השנים \u0003איכא\u0004 \u0005[יש]\u0006 איסור \u0003שבת, ובזמן דליכא\u0004 \u0005[שאין]\u0006 \u0003חרישה\u0004 בשנת השמיטה, שאסור לחרוש בה \u0003ליכא\u0004 \u0005[אין]\u0006 איסור \u0003שבת\u0004 נוהג.","וצדדי בעייתו של ר' זירא: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דמקיימין לה\u0004 \u0005[אותה]\u0006 את השבת \u0003בשאר שני שבוע\u0004 (שנות מחזור שבע השנים), ומסכימים שבשאר השנים יש איסור שבת, הרי זה \u0003כביטול מקצת וקיום מקצת דמי\u0004 \u0005[נחשב],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דקא עקריין ליה\u0004 \u0005[שהם עוקרים אותה]\u0006 את השבת \u0003בשביעית\u0004 לגמרי, הרי זה \u0003כעקירת הגוף דמי\u0004 \u0005[נחשב]?\u0006","\u0003אמר רבינא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לכך, ממה ששנינו: \u0003נביא שנתנבא לעקור דבר מדברי תורה\u0004 — הרי זה \u0003חייב\u0004 מיתה, שהוא נביא שקר. אם נתנבא \u0003לביטול מקצת ולקיום מקצת\u0004 — \u0003ר' שמעון אומר: פטור, ובעבודה זרה, אפילו אמר\u0004 הנביא: \u0003היום עובדה, ולמחר בטלה\u0004 — הריהו \u0003חייב,\u0004 שבעבודה זרה, אפילו ביטול מקצת האיסור הריהו איסור חמור, ולפי זה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 לענייננו, בית דין שהורה ש\u0003אין שבת בשביעית\u0004 — הרי זה \u0003כביטול מקצת וקיום מקצת דמי\u0004 \u0005[נחשב].\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003הורו בית דין, וידע אחד מהן שטעו, ואמר להן: \"טועין אתם\", או שלא היה מופלא של בית דין\u0004 (גדול החכמים) \u0003שם\u0004 במושב הסנהדרין שהחליט על כך, \u0003או שהיה אחד מהן\u0004 פסול לסנהדרין, כגון שהיה \u0003גר או ממזר או נתין, או זקן שלא ראוי לבנים,\u0004 שכל אלה אינם כשרים לשמש בסנהדרין — \u0003הרי זה פטור,\u0004 שאין זו הוראה גמורה,","\u0003ש\u0004כן \u0003נאמר כאן\u0004 בהוראת בית דין בטעות \u0003\"עדה\"\u0004 (\"ואם כל עדת ישראל ישגו\". ויקרא ד, יג), \u0003ונאמר להלן\u0004 בענין דין הרוצח בשגגה \u0003\"עדה\"\u0004 (\"ושפטו העדה בין המכה ובין גואל הדם\". במדבר לה, כד), \u0003מה \"עדה\" האמורה להלן\u0004 — \u0003כולן ראוין להוראה, אף \"עדה\" האמורה כאן\u0004 — \u0003עד שיהיו כולן ראוין להוראה.\u0004","שנינו במשנה: \u0003או שלא היה מופלא של בית דין שם\u0004 — הרי זה פטור. \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הדין? \u0003אמר רב ששת, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם מ\u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל, מפני מה אמרו\u0004 במשנה: \u0003הורו בדבר שהצדוקין מודין בו\u0004 — \u0003פטורין? מפני\u0004 שאין דייני בית דין שכזה נחשבים ראויים להוראה, כיון \u0003שהיה להם ללמוד ולא למדו,\u0004 ובדומה לזה, כאשר \u0003לא היה מופלא של בית דין שם נמי\u0004 \u0005[גם כן]\u0006 \u0003פטורין, מפני שהיה להם ללמוד ולא למדו.\u0004","עוד שנינו במשנה: \u0003\"נאמר שם עדה ונאמר כאן עדה... עד שיהו כולן ראוין להוראה\".\u0004 ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם מנין לנו]\u0006 שכולם ראויים להוראה? ומשיבים: שכן \u0003אמר רב חסדא אמר קרא\u0004 \u0005[הכתוב]\u0006 במינוי שבעים הזקנים על ידי משה: \u0003\"והתיצבו שם עמך\"\u0004 (במדבר יא, טז), לומר \u0003\"עמך\"\u0004 כוונתו \u0003בדומין לך\u0004 למשה, שיהיו כולם ראויים להוראה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 ש\u0003\"עמך\"\u0004 כוונתו \u0003לשכינה\u0004 וכוונת הכתוב לומר שיתייצבו יחד לקבל השראת השכינה! \u0003אלא אמר רב נחמן בר יצחק,\u0004 למדים אנו שכולם צריכים להיות ראויים להוראה ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בשופטים אותם מינה משה: \"ושפטו את העם בכל עת... והקל מעליך \u0003ונשאו אתך\"\u0004 (שמות יח, כב), כלומר \u0003\"אתך\"\u0004 משמעו: \u0003בדומין לך.\u0004","\u0003הורו בית דין שוגגין, ועשו כל הקהל\u0004 שסמכו על בית הדין \u0003שוגגין\u0004 — \u0003מביאין פר,\u0004 כמפורש בתורה בהעלם דבר של ציבור. אם היו בית דין \u0003מזידין\u0004 שידעו שאין הוראתם נכונה, ו\u0003עשו\u0004 הקהל \u0003שוגגין\u0004 שהם האמינו לדברי בית הדין — \u0003מביאין\u0004 היחידים \u0003כשבה ושעירה\u0004 (כלומר, כבשה או שעירה) כדין חוטאים בשגגה. אם היו בית דין \u0003שוגגין\u0004 וטעו, \u0003ועשו\u0004 הקהל \u0003מזידין\u0004 שידעו שטעה בית הדין ובכל זאת עשו — \u0003הרי אלו פטורין.\u0004","שנינו במשנה: \u0003שוגגין ועשו מזידין\u0004 — \u0003הרי אלו פטורין.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שוגג דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מזיד\u0004 — \u0003חייב\u0004 חטאת, \u0003והיכי דמי\u0004 \u0005[וכיצד בדיוק היה הדבר]?\u0006 \u0003שהורו בית דין שחלב מותר, ו\u0004זה שחטא \u0003נתחלף לו\u0004 חלב \u0003בשומן\u0004 שחשב ששומן הוא חלב זה שלפניו \u0003ואכלו.\u0004","ואם כן, \u0003לימא\u0004 \u0005[אמור]\u0006 מכאן: \u0003תפשוט הא דבעי\u0004 \u0005[תפתור\u0006 בעיה \u0005זו ששאל]\u0006 \u0003רמי בר חמא\u0004 (בדף ב,א) בענין זה ונשארה שאלתו בלא פתרון! ודוחים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 שאין זו ראיה, שכן \u0003משום דתנא רישא\u0004 \u0005[ששנה בתחילה]:\u0006 \u0003מזידין ועשו שוגגין, תנא סיפא\u0004 \u0005[שנה בסוף]:\u0006 \u0003שוגגין ועשו מזידין,\u0004 אבל אין לדייק מכאן.","\u0003הורו בית דין ועשו כל הקהל או רובן\u0004 של הקהל \u0003על פיהן\u0004 — \u0003מביאין פר\u0004 לכפרה, \u0003ו\u0004אם היתה שגגה זו \u0003בעבודה זרה\u0004 — \u0003מביאין פר ושעיר,\u0004 כמבואר בתורה (במדבר טו, כד), אלו \u0003דברי ר' מאיר; ר' יהודה אומר:\u0004 לא בית הדין מביא קרבן אלא הציבור, ואם חטאו \u0003שנים עשר שבטים\u0004 — \u0003מביאין שנים עשר פרים,\u0004 שכל שבט הוא קהל לעצמו. \u0003ובעבודה\u0004 \u0003זרה\u0004 — \u0003מביאין שנים עשר פרים ושנים עשר שעירים;\u0004"],["\u0003ר' שמעון אומר:\u0004 מביאים \u0003שלשה עשר פרים\u0004 שהם פר אחד לכל שבט ושבט, ופר אחד לבית הדין, \u0003ובעבודה זרה\u0004 — \u0003שלשה עשר פרים ושלשה עשר שעירים,\u0004 שהם \u0003פר ושעיר לכל שבט ושבט,\u0004 ועוד \u0003פר ושעיר לבית דין.\u0004","\u0003הורו בית דין ועשו שבעה שבטים או רובן על פיהן\u0004 — \u0003מביאין פר, ובעבודה זרה\u0004 — \u0003מביאין פר ושעיר, דברי ר' מאיר. ר' יהודה אומר: שבעה שבטים שחטאו\u0004 — \u0003מביאין שבעה פרים\u0004 שכל שבט מביא קרבן, \u0003ושאר שבטים שלא חטאו\u0004 — גם הם \u0003מביאין על ידיהן\u0004 (בגללם) של החוטאים \u0003פר\u0004 לכל שבט, \u0003שאף אלו שלא חטאו מביאין על ידי\u0004 ה\u0003חוטאין. ר' שמעון אומר:\u0004 כשחטאו שבעה שבטים — מביאים רק \u0003שמונה פרים,\u0004 שהם שבעה פרים לשבטים שחטאו ועוד אחד לבית דין, \u0003ובעבודה זרה\u0004 — \u0003שמונה פרים ושמונה שעירים,\u0004 שהם \u0003פר ושעיר לכל שבט ושבט,\u0004 ועוד \u0003פר ושעיר לבית דין.\u0004","\u0003הורו בית דין של אחד מן השבטים\u0004 שהיה בית דין כללי לאותו שבט, \u0003ועשה אותו השבט על פיהן\u0004 — \u0003אותו שבט הוא חייב, ושאר כל השבטים פטורין, דברי ר' יהודה. וחכמים אומרים: אין חייבין\u0004 להביא קרבן העלם דבר של ציבור \u0003אלא על הוריות\u0004 (הוראות) \u0003בית דין הגדול בלבד, שנאמר \"ואם כל עדת ישראל ישגו\"\u0004 (ויקרא ד, יג), ללמדנו: דווקא בית דין (\"עדה\") של כל ישראל, \u0003ולא עדת\u0004 (בית דין) של \u0003אותו שבט\u0004 יחיד, שאין זה עדת כל ישראל.","שנינו במשנה מחלוקתם של ר' מאיר, ר' יהודה ור' שמעון, ומביאים עוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ידעו\u0004 בית הדין \u0003שהורו\u0004 הוראה מוטעית, \u0003וטעו\u0004 ביחס ל\u0003מה\u0004 ש\u0003הורו,\u0004 שאינם זוכרים מה בדיוק היה הדבר שהורו בו הוראת טעות, \u0003יכול יהו חייבין\u0004 קרבן על כך? \u0003תלמוד לומר: \"ונודעה החטאת\u0004 אשר חטאו עליה\" (ויקרא ד, יד), \u0003ולא שיודעו החוטאין\u0004 והרי כאן אין החטאת ידועה לבית הדין אלא לחוטאים בלבד.","נאמר באותו הפסוק \u0003\"אשר חטאו\",\u0004 הרי זה מלמד שאם \u0003חטאו שני שבטים\u0004 — \u0003מביאין שני פרים, חטאו שלשה\u0004 שבטים — \u0003מביאין שלשה\u0004 פרים, \u0003או אינו אומר אלא\u0004 שאם \u0003חטאו שני יחידים\u0004 — \u0003מביאין שני פרים, חטאו שלשה\u0004 — \u0003מביאין שלשה? תלמוד לומר: \"הקהל\",\u0004 ללמדנו: \u0003הקהל חייב, וכל קהל וקהל חייב, כיצד?\u0004 אם \u0003חטאו שני שבטים\u0004 — \u0003מביאין שני פרים, חטאו שבעה\u0004 — \u0003מביאין שבעה, ושאר שבטים שלא חטאו\u0004 — \u0003מביאין על ידיהן פר פר\u0004 לכל שבט, \u0003שאפילו אלו שלא חטאו מביאין על ידי החוטאין, לכך נאמר \"קהל\"\u0004 בפסוק זה \u0003לחייב על כל קהל וקהל,\u0004 אלו \u0003דברי ר' יהודה.\u0004","ואילו \u0003ר' שמעון אומר: שבעה שבטים שחטאו\u0004 — \u0003מביאין שבעה פרים, ובית דין מביאין על ידיהן פר, שנאמר למטה\u0004 (הלאה) \u0003\"קהל\"\u0004 (\"והקריבו הקהל\". ויקרא ד, יד) \u0003ונאמר למעלה\u0004 (מקודם) \u0003\"הקהל\"\u0004 (\"ונעלם דבר מעיני הקהל\". ויקרא כא, יג), והרי זה בא ללמדנו: \u0003מה \"קהל\" האמור למעלה\u0004 — \u0003בית דין\u0004 (\"עיני הקהל\") \u0003עם הקהל, אף \"קהל\" האמור למטה\u0004 בהבאת הקרבן — \u0003בית דין עם הקהל.\u0004","\u0003ר' מאיר אומר: שבעה שבטים שחטאו\u0004 — \u0003בית דין\u0004 בלבד \u0003מביאין על ידיהם פר, והן\u0004 (הציבור) \u0003פטורין,\u0004 שכן \u0003נאמר \"קהל\" למטה ונאמר \"קהל\" למעלה, מה \"קהל\" האמור למעלה\u0004 — \u0003בית דין ולא צבור, אף \"קהל\" האמור למטה\u0004 — \u0003בית דין ולא צבור.\u0004","\u0003ר' שמעון בן אלעזר אומר משמו\u0004 של ר' מאיר: \u0003חטאו ששה שבטים והם\u0004 במספרם \u0003רובו של קהל, או\u0004 שחטאו \u0003שבעה\u0004 שבטים \u0003אף על פי שאינו רובו של קהל\u0004 אבל הם רוב שבטי ישראל — \u0003מביאין פר.\u0004","ומפרשים את הברייתא הזו ודנים בה, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"ונודעה החטאת\"\u0004 — \u0003ולא שיודעו החוטאין. מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבא:\u0004 ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006","לגבי מי שהיו לפניו שתי חתיכות, אחת האסורה באיסור חלב ואחת האסורה באיסור נותר, ואכל אחת מהן ואינו יודע איזו, \u0003אמר ר' אליעזר: מה נפשך\u0004 (רצונך)? בכל אופן שתדון בדבר הריהו חייב להביא קרבן חטאת, \u0003אם חלב אכל\u0004 — \u0003חייב,\u0004 אם \u0003נותר אכל\u0004 — \u0003חייב,\u0004 ולכן יביא קרבן. ואף בענייננו, כיון שטעו בית הדין, וברור להם שטעו בדבר שחייבים עליו קרבן, אין זה משנה אם אינם יודעים בדיוק באיזה ענין הורו בטעות. ולדעת ר' אליעזר הריהם חייבים בקרבן, ואילו בברייתא נאמר שהם פטורים.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהברייתא כדעת \u0003ר' אליעזר, שאני הכא\u0004 \u0005[שונה כאן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ונודעה החטאת \u0003אשר חטאו עליה\"\u0004 (ויקרא ד, יד), להדגיש מלשון \"עליה\" שדווקא שידעו על מה הם מביאים קרבן. ושואלים: \u0003התם נמי\u0004 \u0005[שם\u0006 בחטאת יחיד \u0005גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \"או הודע אליו חטאתו \u0003אשר חטא בה\"\u0004 (ויקרא ד, כג)! מן ההדגשה שיש במלה \"בה\" יש ללמוד אותו לימוד. ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 ביטוי\u0005]\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 להדגיש ענין אחר, שחובת הקרבן היא דווקא למי שהתכוון לאותו מעשה של חטא, \u0003פרט למתעסק,\u0004 שאם לא נתכוון לאותו מעשה של חטא אלא למעשה אחר, ובתוך התעסקותו בדבר אחר גרם לו וחטא, אין זה נחשב.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 (המחייב גם שבט אחד שחטא בקרבן?) ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003ארבעה\u0004 פעמים \u0003קהלי כתיבי\u0004 \u0005[נאמר],\u0006 כיצד? הרי יכול היה לכתוב \u0003\"קהל\",\u0004 וכתוב \u0003\"הקהל\"\u0004 הרי שדורשים זאת כאילו היתה המלה \"קהל\" כתובה פעמיים, וכיון שהמלה \"הקהל\" נמצאת פעמיים בענין (\"מעיני הקהל\", \"והקריבו הקהל\") ובשתיהן יכל היה לכתוב \u0003\"קהל\"\u0004 וכתב \u0003\"הקהל\"\u0004 — הרי ארבעה,","\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 בא \u0003לחייב על כל קהל וקהל\u0004 שאף קהל של שבט קרוי קהל, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 (\"הקהל ועשו\") לומר ש\u0003הוראה תלויה בבית דין ומעשה תלוי בקהל. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 בא \u0003ל\u0004למד \u0003גרירה,\u0004 ששבט שלא חטא נגרר אחרי שבט שחטא, וצריך אף הוא להביא קרבן. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 בא \u0003ל\u0004ענין \u0003שבט שעשה בהוראת בית דין\u0004 שלו, שחייב להביא פר.","\u0003ור' שמעון\u0004 סבור כי \u0003תלתא קהלי כתיבי\u0004 \u0005[שלושה קהל כתובים]\u0006 והם: \u0003\"הקהל\", \"קהל\"\u0004 כדרך שדורש ר' יהודה, ועוד פעם אחת \u0003\"הקהל\",\u0004 ומה שנאמר \u0003\"מעיני הקהל\" אורחיה דקרא\u0004 \u0005[דרכו של המקרא]\u0006 \u0003הוא, כדאמרי אינשי\u0004 \u0005[כמו שאומרים אנשים]:\u0006 \u0003מעיני דפלניא\u0004 \u0005[מעיניו של פלוני],\u0006 ואין זו הדגשה דווקא נוספת לרבות עוד קהל אחר, ולכן","\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 בא \u0003לחייב על כל קהל וקהל, ותרי אחריני\u0004 \u0005[ושנים אחרים]\u0006 באו ללמוד מהם גזירה שווה: \u0003נאמר למטה \"קהל\" ונאמר למעלה \"קהל\", מה להלן בית דין עם הקהל\u0004 שהרי ההוראה בטעות היא בבית דין והמעשה תלוי בהם, \u0003אף כאן\u0004 למטה, בענין הבאת קרבן, \u0003בית דין עם הקהל\u0004 שגם בית דין מביא קרבן כפרה כשם שמביא הקהל.","\u0003ו\u0004טעמו של \u0003ר' מאיר,\u0004 שאת הייתור של \u0003\"קהל\", \"הקהל\"\u0004 הוא \u0003לא דריש\u0004 \u0005[דורש],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003תרי קהלי כתיבי\u0004 \u0005[שני קהלים כתובים],\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרכים לו\u0006 הדברים\u0005]\u0006 \u0003ל\u0004גזירה שווה \u0003נאמר למטה \"קהל\" ונאמר למעלה \"קהל\", מה להלן בית דין ולא צבור\u0004 (\"מעיני הקהל\" — שגגת בית דין) \u0003אף כאן\u0004 בהבאת הקרבן רק \u0003בית דין ולא צבור.\u0004","\u0003ור' שמעון בן אלעזר מאי טעמא\u0004 \u0005[מה הטעם\u0006 שלו\u0005]?\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והיה אם מעיני העדה\"\u0004 (במדבר טו, כד), \u0003אלמא מיעוטא\u0004 \u0005[מכאן\u0006 שמדובר ב\u0005מיעוט],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מעיני\"\u0004 למעט — שלא כולם אלא מקצתם עבדו עבודה זרה, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי לכל העם בשגגה\"\u0004 (במדבר טו, כו), \u0003למימרא\u0004 \u0005[לומר]\u0006 גם אם לא נאמר \"כי לכל\" הכוונה לכולם, לפחות \u0003רובא\u0004 \u0005[הרוב]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 — \u0003לא,\u0004 ואם כן יש כאן כעין סתירה,","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 מיישבים את שתי הלשונות: אם \u0003עשו ששה\u0004 שבטים \u0003והן\u0004 מבחינת מספרם \u0003רובו של קהל, או שבעה\u0004 שבטים \u0003אף על פי שאינן רובו של קהל\u0004 — \u0003חייבין.\u0004 שאף שאינם רוב מכל צד — הרי אף המיעוט נכלל במקרא."],["\u0003ו\u0004שואלים: \u0003ר' שמעון ור' מאיר,\u0004 הלכה זו ש\u0003הוראה תלויה בבית דין ומעשה תלוי בקהל מנא להו\u0004 \u0005[מנין להם]?\u0006 \u0003אמר אביי,\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בלשון נפעל: \u0003\"והיה אם מעיני העדה נעשתה לשגגה\"\u0004 (במדבר טו, כד), כלומר שמעשה הקהל נעשה על ידי הוראת הסנהדרין. \u0003רבא אמר:\u0004 לומדים זאת \u0003מ\u0004מה שנאמר \u0003\"לכל העם בשגגה\"\u0004 (במדבר טו, כו), שהשגגה היא של כולם, של בית הדין והקהל, בית הדין בהוראתו והקהל במעשהו.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריכים]\u0006 להיאמר שני המקראות, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"והיה אם מעיני העדה נעשתה לשגגה\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אפילו\u0004 חטא \u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 של הקהל, גם כן יביאו קרבן זה, \u0003להכי כתיב\u0004 \u0005[משום כך נכתב]\u0006 \u0003\"לכל העם בשגגה\", ואי כתיב\u0004 \u0005[ואם היה כותב]\u0006 רק \u0003\"לכל העם בשגגה\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003עד דעבדי\u0004 \u0005[שעושים]\u0006 \u0003בית דין בהדי רובא\u0004 \u0005[יחד עם רוב\u0006 הקהל\u0005],\u0006 שתהא שגגה אחת לכל העם, \u0003להכי כתיב\u0004 \u0005[משום כך נאמר]\u0006 \u0003\"והיה אם מעיני העדה נעשתה לשגגה\"\u0004 — שהשגגה נעשית על פי הוראה, ואין מעשה בית דין משמעותי בזה.","ומקשים: \u0003והא כי כתיבי הני קראי\u0004 \u0005[והרי כאשר כתובים המקראות האלה]\u0006 \u0003ב\u0004שגגת \u0003עבודה זרה הוא דכתיבי\u0004 \u0005[שכתובים]\u0006 ולא בשגגות של הוראות אחרות! ומשיבים: \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 בגזירה שווה \u0003\"מעיני\u0004 הקהל\u0003\"\u0004 (הכתוב בשגגת שאר עבירות) \u0003\"מעיני\u0004 העדה \u0003\"\u0004הכתוב בשגגת עבודה זרה.","שנינו במשנה שאם \u0003הורו בית דין של אחד\u0004 מן השבטים, ר' יהודה אומר שאותו שבט מקריב פר ושאר השבטים פטורים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שבט אחד ל\u0004דעת \u0003ר' יהודה\u0004 כאשר חטאו \u0003בהוראת בית דין הגדול, מי מייתו\u0004 \u0005[האם מביאים]\u0006 קרבן גם \u0003שאר שבטים או לא?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 דווקא כאשר חטאו \u0003שבעה שבטים\u0004 הדין \u0003הוא דמייתו\u0004 \u0005[שמביאים]\u0006 \u0003שאר שבטים בהדייהו\u0004 \u0005[יחד איתם],\u0006 \u0003משום דאיכא רובא\u0004 \u0005[שיש רוב\u0006 שבטים\u0005],\u0006 \u0003אבל\u0004 כאשר חטא \u0003חד שבט, דליכא רובא\u0004 \u0005[שבט אחד, שאין רוב]\u0006 — \u0003לא, או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]!\u0006 ואף שבט אחד גורר את השאר!","ומציעים פתרון: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע\u0006 מברייתא\u0005]:\u0006 \u0003מה הן מביאין? פר אחד, ר' שמעון אומר: שני פרים.\u0004 ונברר: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]\u0006 בברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה \u0003שחטאו שבעה\u0004 שבטים, אם כן לשיטת \u0003ר' שמעון תמניא בעי\u0004 \u0005[שמונה\u0006 פרים \u0005צריך],\u0006 שהם אחד לכל שבט ועוד אחד לבית דין! \u0003אלא\u0004 צריך לומר ש\u0003חטא שבט אחד.\u0004 ונברר: \u0003במאי\u0004 \u0005[במה]?\u0006 כלומר, על פי מי עשו אותו שבט? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שחטאו \u0003בהוראת בית דינו\u0004 של אותו שבט, \u0003ר' שמעון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את הסברה שהוראת בית דין של שבט מחייבת קרבן! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריכים לומר שהכוונה שעשו \u0003בהוראת בית דין הגדול.\u0004","ונברר עוד: \u0003ותנא קמא מני\u0004 \u0005[והתנא הראשון\u0006 האומר שמביאים פר אחד \u0005מיהו]?\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ר' מאיר\u0004 הוא, \u0003הא רובא בעי\u0004 \u0005[הרי רוב\u0006 הוא \u0005צריך]\u0006 ולא די לו בשבט אחד! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' יהודה\u0004 היא, \u0003ו\u0004מדובר פה \u0003כגון שחטא שבט אחד\u0004 ואף הוא אינו מחייב אלא פר אחד, ואין שאר השבטים מביאים קרבן.","את ההוכחה הזאת דוחים: \u0003אמרי\u0004 \u0005[אומרים],\u0006 אפשר להסביר את הברייתא בדרך אחרת: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שחטאו ששה שבטים והן רובן של קהל, ו\u0004שיטת \u0003ר' שמעון בן אלעזר היא\u0004 שמביאים במקרה זה פר. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר משמו\u0004 של ר' מאיר: \u0003חטאו ששה והן רובו של קהל, או שבעה אף על פי שאינן רובו של קהל\u0004 — \u0003מביאין פר.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה מברייתא אחרת, \u0003ר' יהודה אומר: שבט שעשה בהוראת בית דינו\u0004 — \u0003אותו השבט חייב ושאר כל השבטים פטורין, ובהוראת בית דין הגדול\u0004 — \u0003אפילו שאר שבטים חייבים.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך היא דעת ר' יהודה במקרה זה.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003ועשה אותו השבט על פיהם\u0004 — \u0003אותו השבט חייב ושאר כל השבטים פטורין,\u0004 ויש לדייק: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 \u0003ושאר שבטים פטורים? הא תנא\u0004 \u0005[הרי שנה]\u0006 כבר \u0003אותו השבט חייב, וכיון דתנא\u0004 \u0005[ששנה]\u0006 \u0003אותו השבט חייב, ממילא ידענא\u0004 \u0005[ידענו]\u0006 כי \u0003שאר שבטים פטורין! אלא הא קמשמע לן\u0004 \u0005[זה משמיע לנו],\u0006 ש\u0003בהוראת בית דינו הוא\u0004 ש\u0003שאר שבטים פטורים, אבל בהוראת בית דין הגדול\u0004 — \u0003אפילו שאר שבטים חייבין.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שבט אחד שעשה בהוראת בית דין הגדול, ל\u0004דעת \u0003ר' שמעון מי מייתי\u0004 \u0005[האם\u0006 הוא \u0005מביא]\u0006 קרבן \u0003או לא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003מה הן מביאין? פר אחד, ר' שמעון אומר: שני פרים.\u0004 ונברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שחטאו שבעה\u0004 שבטים, אם כן במקרה זה \u0003שני פרים\u0004 מביאים? \u0003שמנה פרים בעי\u0004 \u0005[צריכים]\u0006 להביא לשיטתו! \u0003אלא\u0004 צריך לומר ש\u0003חטא שבט אחד, ובמאי\u0004 \u0005[ובמה]\u0006 על פי הוראת מי חטאו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בהוראת בית דינו\u0004 של אותו שבט, הלוא אמרנו ש\u0003ר' שמעון לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 סברה זו שהוראת בית דין של שבט מחייבת! \u0003אלא בהוראת בית דין הגדול.\u0004 משמע שאף הוא היה מסכים שבמקרה זה שבט אחד מביא קרבן!","את הראיה הזו דוחים, \u0003ותסברא\u0004 \u0005[ויכול אתה לסבור כן],\u0006 שבמקרה כזה מדובר? אם כן, \u0003תנא קמא מני\u0004 \u0005[התנא הראשון מיהו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר ש\u0003ר' מאיר\u0004 הוא, \u0003הא\u0004 \u0005[הרי]\u0006 לשיטתו \u0003רובא בעי\u0004 \u0005[רוב\u0006 ישראל \u0005צריך]\u0006 שיחטאו, ושבט אחד שחטא אינו מביא קרבן! \u0003אי\u0004 \u0005[אם]\u0006 \u0003ר' יהודה\u0004 הוא, הרי לשיטתו \u0003שאר שבטים נמי מייתו\u0004 \u0005[גם כן מביאים]!\u0006 אלא \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' שמעון בן אלעזר היא,\u0004 וכשחטאו ששה שבטים והן רוב הקהל, ובמקרה זה סובר ר' שמעון שמביאים שני פרים, אחד הקהל ואחד בית הדין, \u0003וכדתניא\u0004 \u0005[וכמו ששנינו\u0006 בברייתא\u0005]\u0006 וכמו שהסברנו קודם. ואין ראיה מכאן לשאלה בשבט אחד שעשה בהוראת בית דין.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממשנתנו: \u0003וחכמים אומרים: לעולם אינו חייב אלא על הוראת בית דין הגדול.\u0004 ונברר: \u0003מאן\u0004 \u0005[מיהם]\u0006 \u0003חכמים\u0004 אלה שנזכרו פה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' מאיר,\u0004 הלא לשיטתו, אין צורך בסברה זו, שהרי לדעתו \u0003רובא בעי\u0004 \u0005[רוב צריך]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' שמעון היא!\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שלדעת ר' שמעון שבט אחד שחטא בהוראת בית דין הגדול מביא פר.","ומבררים ענין נוסף שהזכרנו קודם: \u0003ור' יהודה ור' שמעון\u0004 שמחייבים שבט אחד שחטא, מפני שהוא \"קהל\", \u0003שבט אחד דאקרי\u0004 \u0005[שנקרא]\u0006 \u0003קהל מנא להו\u0004 \u0005[מנין להם]?\u0006 \u0003אמרי: דכתיב\u0004 \u0005[אומרים:\u0006 מפני \u0005שנאמר]:\u0006 \u0003\"ויעמד יהושפט בקהל יהודה וירושלים נכח חצר בית ה' החדשה\"\u0004 (דברי הימים ב כ, ה). אגב כך שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חדשה\"? אמר ר' יוחנן, ש\u0004באותו זמן \u0003חידשו דברים ואמרו: טבול יום\u0004 כלומר, מי שנטמא וטבל ועדיין לא העריב השמש ולא נטהר לגמרי, \u0003אל יכנס\u0004 אפילו \u0003במחנה לויה.\u0004 ומכל מקום למדנו ששבט אחד (יהודה) נקרא קהל.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הוכחה זו \u0003רב אחא בר יעקב: ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק ששבט אחד נקרא קהל, \u0003דלמא שאני\u0004 \u0005[שמא שונה]\u0006 היא \u0003ירושלים, דהוה נמי\u0004 \u0005[שהיה גם כן]\u0006 שבט \u0003בנימין\u0004 בירושלים והיו בה שני שבטים ולא אחד! \u0003אלא אמר רב אחא בר יעקב,\u0004 הראיה לכך היא \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 ליעקב בבואו מפדן ארם: \u0003\"ויאמר אלי הנני מפרך והרביתך ונתתיך לקהל עמים\" וגו'\u0004 (בראשית מח, ד). \u0003מאן אתיליד ליה ההיא שעתא\u0004 \u0005[מי נולד לו באותה שעה]\u0006 נוסף לבנים שהיו לו? רק \u0003בנימין, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הכי קאמר רחמנא\u0004 \u0005[כך אמר\u0006 לו \u0005הקב\"ה]:\u0006 \u0003מתיליד לך השתא\u0004 \u0005[יוולד לך היום]\u0006 \u0003קהל אחרינא\u0004 \u0005[אחר].\u0006 הרי ששבט אחד קרוי קהל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שבא לרב כהנא, דלמא הכי קאמר ליה רחמנא\u0004 \u0005[שמא כך אמר לו הקב\"ה]:\u0006 \u0003לכי מתיליד\u0004 \u0005[כאשר יוולד]\u0006 \u0003לך בנימין, הוא דהוו\u0004 \u0005[שיהיו]\u0006 לך אז \u0003שנים עשר שבטים דמתקריית\u0004 \u0005[שאתה תיקרא]\u0006 בכך \u0003קהל! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אלא\u0004 לשיטתך \u0003שנים עשר שבטים איקרו\u0004 \u0005[נקראו]\u0006 \u0003קהל, אחד עשר שבטים לא איקרו\u0004 \u0005[נקראו]\u0006 \u0003קהל?\u0004 והרי ודאי הוא שרוב ישראל נקראים קהל, אלא יש ללמוד מכאן שאף שבט אחד קרוי קהל.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון אומר, מה תלמוד לומר: \"ופר שני בן בקר תקח לחטאת\"\u0004 (במדבר ח, ח)? האמור אצל טהרת הלויים אחרי חטא העגל \u0003אם ללמד שהם שנים\u0004 שיש עוד פר שני, \u0003והלא כבר נאמר: \"ועשה את האחד חטאת ואת האחד עלה לה' \"\u0004(במדבר ח, יב)! \u0003אלא יכול תהא נאכלת חטאת ללוים?\u0004 שחטאת זו שהביאו עבור הלויים תאכל כשאר חטאות, \u0003תלמוד לומר: \"ופר שני\"\u0004 שבא הכתוב להדגיש שהיא \u0003שני לעולה\u0004 ודומה לה, \u0003מה עולה לא נאכלת\u0004"],["\u0003אף חטאת\u0004 זו \u0003לא נאכלת.\u0004","\u0003כיוצא בו, אמר ר' יוסי:\u0004 נאמר בשבים מבבל בימי עזרא \u0003\"הבאים מהשבי\u0004 בני \u0003הגולה הקריבו עלות לאלהי ישראל פרים שנים עשר\u0004 על כל ישראל אילים תשעים וששה כבשים שבעים ושבעה צפירי חטאת שנים עשר \u0003הכל עולה\"\u0004 (עזרא ח, לה), ויש לשאול: \u0003הכל עולה סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, וכי \u0003אפשר שחטאת\u0004 האמורה שם היא \u0003עולה? אלא\u0004 לומר שזו כוונת הכתוב: \u0003הכל\u0004 נעשה \u0003כעולה, מה עולה לא נאכלת, אף חטאת\u0004 זו \u0003לא נאכלת. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: על עבודה זרה הביאום, ואמר רב יהודה אמר שמואל: על\u0004 אותה \u0003עבודה זרה שעשו בימי צדקיהו.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 במשנתנו, \u0003משכחת לה להני\u0004 \u0005[מוצא אתה לאותם]\u0006 \u0003שנים עשר חטאות כגון\u0004 ש\u0003חטאו שנים עשר שבטים\u0004 בעבודה זרה, \u0003דמייתו\u0004 \u0005[שמביאים]\u0006 \u0003שנים עשר שעירים\u0004 (\"צפירי חטאת\"), \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשרות אחרת ש\u0003חטאו\u0004 רק \u0003שבעה שבטים ושארא אינך\u0004 \u0005[ושאר\u0006 השבטים \u0005הם]\u0006 \u0003בגרירה, ולר' שמעון נמי משכחת לה\u0004 \u0005[גם כן אתה יכול למצוא אותה]\u0006 אפשרות שמביאים שנים עשר שעירים, \u0003כגון\u0004 ש\u0003חטאו אחד עשר שבטים, דמייתו\u0004 \u0005[שמביאים]\u0006 \u0003אחד עשר שעירים ואידך\u0004 \u0005[ו\u0006השעיר ה\u0005אחר]\u0006 הוא של \u0003בית דין, אלא ל\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר: בית דין מביאין ולא צבור,\u0004 ומביאים רק פר אחד, \u0003שנים עשר היכי משכחת ליה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 ומשיבים: \u0003כגון\u0004 ש\u0003חטאו והדר\u0004 \u0005[וחזרו]\u0006 ו\u0003חטאו והדר\u0004 \u0005[וחזרו]\u0006 ו\u0003חטאו, עד תריסר זימני\u0004 \u0005[שתים עשרה פעמים].\u0006","ושואלים: \u0003והא מייתי להו הנהו\u0004 \u0005[והרי מתו להם\u0006 כבר \u0005אלה]\u0006 ש\u0003חטאו\u0004 בעבודה זרה בימי צדקיהו בזמן גלות בבל, וכיצד יכולים בניהם להביא קרבן חטאת בשביל אבותיהם שהיו בימי צדקיהו? והרי דינם כחטאת שמתו בעליה שאינה קריבה למזבח!","\u0003אמר רב פפא: כי גמירי\u0004 \u0005[כאשר למדו]\u0006 דין של \u0003חטאת שמתו בעליה\u0004 שהיא \u0003במיתה\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003ביחיד\u0004 שמת, \u0003אבל לא בצבור, לפי שאין מיתה בצבור,\u0004 שהציבור נשאר קיים. ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לרב פפא הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר]:\u0006 \u0003\"תחת אבותיך יהיו בניך\"\u0004 (תהלים מה, יז), ונחשב כאילו האבות קיימים, \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו ביחיד נמי\u0004 \u0005[גם כן]\u0006 יהיו הבנים תחת האבות שמתו, ויקריבו את חטאתם!","\u0003אלא דוקיא\u0004 \u0005[דיוקו]\u0006 של \u0003רב פפא\u0004 ולימודו \u0003משעיר\u0004 של \u0003ראש חדש,\u0004 שכן \u0003אמר רחמנא\u0004 \u0005[הכתוב]:\u0006 \u0003מייתי\u0004 \u0005[הבא]\u0006 אותם \u0003מתרומת הלשכה,\u0004 בה נמצאות התרומות שנתרמו על ידי עם ישראל עבור הקרבנות בחודש אדר בכל שנה, \u0003ו\u0004יש לשאול: \u0003הא מייתי להו\u0004 \u0005[הרי מתו להם\u0006 אנשים\u0005]\u0006 \u0003מישראל\u0004 בינתיים מחודש אדר ועד לזמן בו יוקרב הקרבן במהלך השנה, \u0003ו\u0004אם כן \u0003הנך דפיישי היכי מייתו\u0004 \u0005[ואלה שנשארים היאך מביאים]\u0006 קרבן חטאת שהרי מקצת מבעלי הקרבן כבר מתו! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003חטאת שמתו בעליה ב\u0004קרבן \u0003צבור קרבה.\u0004","ותוהים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 ב\u0003שעיר ראש חדש\u0004 יש מקום לומר \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא מייתו\u0004 \u0005[מתו]\u0006 מן ה\u0003צבור\u0004 בינתיים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשבי ציון מבבל \u0003ודאי מייתו\u0004 \u0005[מתו]\u0006 אותם שחטאו בעבודה זרה בימי צדקיהו, שהרי עברו שנים רבות מאז! \u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רב פפא מהכא\u0004 \u0005[מכאן]\u0006 מכתוב זה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בוידוי על העגלה הערופה: \u0003\"כפר לעמך ישראל אשר פדית ה'\"\u0004 (דברים כא, ח), לומר: \u0003ראויה כפרה זו שתכפר על יוצאי מצרים, מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 \u0003\"אשר פדית\",\u0004 שהם יוצאי מצרים שפדה ה' מן הגלות, ואף שכבר מתו יוצאי מצרים מזמן רב.","ועדיין מקשים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 \u0003התם, כולהו איתינון\u0004 \u0005[שם, כולם נמצאים]\u0006 בזמן שמביאים את העגלה לכפרה עליהם, ואפשר לומר \u0003מגו דמכפרה אחיים, מכפרה נמי אמתים\u0004 \u0005[מתוך ש\u0006היא \u0005מכפרת על החיים,\u0006 הריהי \u0005מכפרת גם על המתים],\u0006 \u0003אלא הכא מי הוו\u0004 \u0005[כאן האם היו\u0006 אנשים\u0005]\u0006 \u0003חיים\u0004 שנשארו מאז ימי צדקיהו שיתכפר להם חטאם בקרבן זה? ומשיבים: \u0003אין, הכי נמי\u0004 \u0005[כן, כך גם כן\u0006 היה\u0005]\u0006 שנשארו עוד אנשים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ורבים מהכהנים והלוים וראשי האבות\u0004 הזקנים אשר ראו את הבית הראשון ביסדו זה הבית בעיניהם בוכים בקול גדול ורבים בתרועה בשמחה להרים קול","\u0003\"\u0004(עזרא ג, יב), ונמצא שהיו אז עדיין אנשים שחיו עוד בזמן הבית הראשון. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אותם הזקנים \u0003מועטין הוו\u0004 \u0005[היו]\u0006 \u0003ולא רבים הוו\u0004 \u0005[היו]!\u0006 ורוב קהל היה מאלה שלא היו בימי צדקיהו? ומשיבים: \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 בפסוק שלאחריו: \u0003\"(ולא הכירו בקול) ואין העם מכירים קול תרועת השמחה לקול בכי העם\u0004 כי העם מריעים תרועה גדולה \u0003והקול נשמע עד למרחוק\".\u0004 משמע שרבים היו הזקנים הבוכים יותר מן הצעירים.","ומקשים קושיה בסיסית יותר לעצם הענין: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מזידין הוו\u0004 \u0005[היו]\u0006 בעבודה זרה בימי צדקיה, ואם כן מה להם להביא קרבנות חטאת, שמביאים על שגגה? ומשיבים: \u0003הוראת שעה היתה.\u0004 ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 מה שנאמר שם \u0003\"אילים תשעים וששה כבשים שבעים ושבעה\", כנגד מי\u0004 הם באים? \u0003אלא הוראת שעה היתה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין הכפרה על הזדונות \u0003הוראת שעה היתה.\u0004","ובנושא קרוב לזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 שגגו בית דין בהוראתם ועשו הקהל על פיהם, ובינתיים \u0003מת אחד מן הצבור\u0004 — \u0003חייבין\u0004 להביא קרבן, אם מת \u0003אחד מבית דין\u0004 — \u0003פטורין.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב חסדא אמר ר' זירא אמר רב ירמיה אמר רב,\u0004 שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: בית דין מביאים ולא צבור, הלכך\u0004 \u0005[על כן]\u0006 אם \u0003מת אחד מן הצבור\u0004 — \u0003חייבין, דהא קאים כוליה\u0004 \u0005[שהרי עומד,\u0006 נמצא \u0005כל]\u0006 \u0003בית\u0004 ה\u0003דין,\u0004 אבל אם \u0003מת אחד מבית דין\u0004 — \u0003פטורין, דהויא לה\u0004 \u0005[שהרי היא]\u0006 כ\u0003חטאת שמת אחד מן השותפין, ומשום הכי\u0004 \u0005[כך]\u0006 \u0003פטורין.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף, ונוקמה\u0004 \u0005[ונעמיד אותה]\u0006 את ההלכה הזו \u0003כר' שמעון\u0004 ש\u0003אמר: בית דין\u0004 מביאים \u0003עם הצבור,\u0004 ולכן אם \u0003מת אחד מן הצבור\u0004 — \u0003חייבין,\u0004 משום ש\u0003אין צבור מתים, מת אחד מבית דין\u0004 — \u0003פטורין, כדאמרינן\u0004 \u0005[כמו שאמרנו]\u0006 ש\u0003חטאת שותפין היא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף, \u0003שמעינן ליה\u0004 \u0005[שמענו אותו]\u0006 את \u0003ר' שמעון\u0004 ש\u0003אמר: חטאת שותפין אינה מתה, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003פר ושעיר של יום הכפורים שאבדו, והפריש אחרים תחתיהם\u0004 ונמצאו — \u0003ימותו כולן, דברי ר' יהודה. ר' אלעזר ור' שמעון אומר: ירעו, לפי שאין חטאת צבור מתה,\u0004 והרי פר זה של יום הכפורים הוא פר של הכהנים, ונחשב כפר השותפים, ובכל זאת אין דנים בו לדעת ר' שמעון כפר שמתו בעליו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 לאביי: \u0003כהנים קא אמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003כהנים, דאיקרו\u0004 \u0005[שהם נקראים\u0006 בעצמם\u0005]\u0006 \u0003קהל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"על הכהנים ועל כל עם הקהל יכפר\"\u0004 (ויקרא טז, לג)."],["ושואלים: אם הכהנים קרויים קהל \u0003אלא מעתה, נייתו\u0004 \u0005[שיביאו]\u0006 \u0003פר\u0004 על חטאתם \u0003בהוראה\u0004 של בית דין, כמו שמביא כל שבט (לדעת ר' שמעון) שהרי גם הם קהל! \u0003וכי תימא, הכי נמי\u0004 \u0005[ואם תאמר,\u0006 אכן \u0005כך\u0006 הוא \u0005גם כן],\u0006 אם כן, \u0003טפי להו\u0004 \u0005[התרבו להם]\u0006 \u0003שבטים,\u0004 שיש מעתה שלושה עשר שבטים!","\u0003אלא אמר רב אחא בר' יעקב: שבטו של לוי לא איקרו\u0004 \u0005[נקראו]\u0006 \u0003קהל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנני מפרך והרביתך ונתתיך לקהל עמים\u0004 ונתתי את הארץ הזאת לזרעך אחריך אחוזת עולם\" (בראשית מח, ד), לומר \u0003כל\u0004 שבט \u0003שיש לו אחוזה\u0004 נחלה בארץ — \u0003איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל, וכל שאין לו אחוזה\u0004 — \u0003לא איקרי\u0004 \u0005[נקרא]\u0006 \u0003קהל,\u0004 ושבט לוי אין לו חלק ונחלה בארץ, וכן הכהנים הבאים משבט לוי. ושואלים: \u0003אם כן, חסרי להו\u0004 \u0005[חסרים להם]\u0006 \u0003שנים עשר שבטים\u0004 כיון שיש רק אחד עשר שבטים בלא לוי! \u0003אמר אביי:\u0004 נאמר \u0003\"אפרים ומנשה כראובן ושמעון יהיו לי\"\u0004 (בראשית מח, ה), והם נמנים כשני שבטים. \u0003אמר רבא, והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"על שם אחיהם יקראו בנחלתם\"\u0004 (בראשית מח, ו) לומר שדווקא \u0003לנחלה הוקשו\u0004 (הושוו) לשבטים \u0003ולא לדבר אחר!\u0004","ושואלים: \u0003ולא?\u0004 וכי אינם נחשבים לשבטים אף לעניינים אחרים? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חלוקין\u0004 הם \u0003בדגלים\u0004 במסע בני ישראל במדבר, שבכל דגל היו שלושה שבטים, וגם אפרים ומנשה נמנו במנין השבטים בדגלים כשני שבטים נבדלים! ומשיבים: \u0003כנחלתן כך חנייתן\u0004 סביב למשכן, \u0003כדי לחלק כבוד לדגלים.\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 הם \u0003חלוקים בנשיאים,\u0004 שלשבט אפרים ומנשה היו נשיאים נבדלים! ומשיבים: \u0003ההוא, לחלוק כבוד לנשיאים,\u0004 ומכאן אין ראיה שהם נחשבים לשני שבטים לענין אחר. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שלמה עשה שבעה ימי חנוכה\u0004 בחנוכת בית המקדש, \u0003ומה ראה משה לעשות שנים עשר ימי חנוכה\u0004 בחנוכת המשכן? \u0003כדי לחלוק כבוד לנשיאים,\u0004 שכל נשיא שבט יקריב באחד מימים אלה, ומפני כבודם של נשיאיהם נחשבים אפרים ומנשה לשנים.","","ושואלים: לגופו של דבר, האם סבור ר' שמעון שחטאת השותפים שונה מחטאת הציבור, כפי שאמר רב יוסף, או כדברי אביי שאין הבדל ביניהם? \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]?\u0006 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' שמעון אומר, חמש חטאות מתות\u0004 כלומר, גורמים להן למות, משום שאי אפשר להקריבן, והן: \u0003ולד חטאת,\u0004 אם בהמת קרבן שהוקדשה לחטאת (שהיא נקבה) ילדה ולד, וולד זה יש בו קדושה אבל אי אפשר להביא אותו לקרבן. \u0003ותמורת חטאת,\u0004 אם המירו בהמה אחרת בבהמה לחטאת, שנתקדשה באותה קדושה, אבל אי אפשר להקריבה. \u0003וחטאת שמתו בעליה. וחטאת שנתכפרו בעליה\u0004 בקרבן אחר. \u0003וחטאת שעברה שנתה,\u0004 שהיא צריכה להיות בת שנה, ועברה שנתה. \u0003ואי אתה יכול לומר ולד חטאת בצבור, שאין צבור מפרישין\u0004 קרבן חטאת \u0003נקבה. ואי אתה יכול לומר תמורת חטאת בצבור, שאין תמורה בצבור,\u0004 שדין התמורה הוא רק ביחיד. \u0003ואי אתה יכול לומר חטאת שמתו בעליה בצבור, שאין צבור מתים.\u0004","","\u0003שנתכפרו בעליה ושעברה שנתה לא שמענו\u0004 מה דינם, \u0003יכול ימותו? אמרת\u0004 (אומר אתה): \u0003ילמוד סתום מן המפורש, מה מצינו בולד חטאת ותמורת חטאת ושמתו בעליה\u0004 שדין זה \u0003ביחיד דברים אמורים ולא בצבור, אף\u0004 חטאת \u0003שנתכפרו בעליה ושעברה שנתה\u0004 — \u0003ביחיד דברים אמורים ולא בצבור.\u0004 ומאותו לימוד נלמד לענייננו לגבי חטאת השותפים, שכשם שמצינו בולד חטאת ותמורת חטאת שדינם ביחיד ולא בשותפים, כמו כן גם לגבי חטאת השותפים שמת אחד מהשותפים.","ושואלים: \u0003וכי דנין אפשר משאי אפשר?\u0004 הרי יש פה דברים שאינם יכולים להיות בציבור מעצם טבעו של הציבור, אבל אין ללמוד מכאן על דברים שהם אפשריים בציבור! ומשיבים: \u0003ר' שמעון בחד מקום גמיר\u0004 \u0005[במקום אחד\u0006 הוא \u0005לומד]\u0006 שכל דיני חטאות המתות נמסרו כהלכה אחת, ובמקום שאי אפשר לקיים כולה — כל הדין הזה בטל.","","\u0003הורה כהן משיח לעצמו\u0004 להתיר דבר האסור מן התורה \u0003שוגג\u0004 (מתוך טעות), \u0003ועשה\u0004 ב\u0003שוגג\u0004 על פי הוראתו — \u0003מביא פר\u0004 העלם דבר של כהן משיח. אם הורה לעצמו \u0003שוגג ועשה מזיד,\u0004 או הורה \u0003מזיד ועשה שוגג\u0004 — \u0003פטור\u0004 מכל קרבן. \u0003ש\u0004כלל הוא: \u0003הוראת כהן משיח\u0004 שמורה \u0003לעצמו\u0004 הלכה, הרי היא \u0003כהוראת בית דין\u0004 שמורה \u0003לצבור.\u0004 שרק במקרה שהיו מביאים פר העלם דבר של ציבור, מביא הכהן הגדול פר על שגגתו. שנינו במשנה: \u0003שוגג ועשה שוגג\u0004 — \u0003מביא פר.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שהרי הוא שוגג ודאי, וחייב קרבן כדינו הכתוב בתורה!","","\u0003אמר אביי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שהורה\u0004 להיתר, \u0003ושכח מאיזה טעם הורה, ובשעה שטעה\u0004 ועשה מעשה \u0003אמר: הריני עושה על דעת הוראתו,\u0004 ש\u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003כיון\u0004 ש\u0003אילו מתידע ליה\u0004 \u0005[היה נודע לו]\u0006 הטעם באותה שעה \u0003שמא הדר ביה\u0004 \u0005[היה חוזר בו],\u0006 ואם שכח ובכל זאת עשה הריהו \u0003כמזיד דמי\u0004 \u0005[נחשב]\u0006 \u0003ולא לחייב\u0004 \u0005[יתחייב]\u0006 להביא קרבן על כך, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם זה קרוי שוגג.","שנינו במשנה: שוגג ועשה מזיד, \u0003מזיד ועשה שוגג\u0004 — פטור. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים האלה],\u0006 כל הדינים המיוחדים של פר כהן משיח? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר \"אם הכהן המשיח יחטא \u0003לאשמת העם\"\u0004 (ויקרא ד, ג), \u0003הרי\u0004 שדין ה\u0003משיח כ\u0004דין ה\u0003צבור,\u0004 (שאשמתו היא כדרך אשמת העם). ודנים בדבר, \u0003שיכול\u0004 היית לומר שאין צורך בכתוב זה, \u0003והלא דין הוא\u0004 שאפשר ללמוד אותו מן הסברה:"],["\u0003צבור מוצא מכלל יחיד\u0004 שהרי היחיד מביא כבשה או שעירה על חטאתו, ואילו הציבור מביא פר, \u0003ו\u0004כן כהן \u0003משיח\u0004 ש\u0003מוצא מכלל יחיד\u0004 שהריהו מביא פר לחטאתו, \u0003מה צבור אין חייבין אלא על העלם דבר עם שגגת מעשה, אף משיח לא יהא חייב אלא על העלם דבר עם שגגת מעשה.\u0004","ואולם ראיה זו אינה מכרעת, \u0003או כלך\u0004 (לך) \u0003לדרך זו\u0004 ועשה השוואה אחרת: \u0003נשיא\u0004 גם הוא \u0003מוצא מכלל יחיד,\u0004 לפי שהנשיא מביא שעיר על חטאתו, \u0003ומשיח מוצא מכלל יחיד, מה נשיא מביא בשגגת מעשה בלא העלם דבר\u0004 כמו שמביא כל אדם חטאת, \u0003אף משיח מביא בשגגת מעשה בלא העלם דבר!\u0004 אם כן, יש דרכים להשוות לכאן ולכאן את דינו של כהן משיח.","וממשיכים לדון: \u0003נראה למי\u0004 מבין אלו השניים ציבור ונשיא \u0003דומה\u0004 כהן משיח? \u0003צבור\u0004 מתכפרים \u0003בפר ואין מביאין אשם תלוי, ו\u0004אף \u0003משיח\u0004 מתכפר \u0003בפר ואין מביא אשם תלוי,\u0004 ולכן נוכל לומר: \u0003מה צבור אינו חייב אלא על העלם דבר עם שגגת מעשה, אף משיח לא יהא חייב אלא על העלם דבר עם שגגת מעשה.\u0004","אולם גם כאן אין זו הוכחה גמורה, ואפשר לומר: \u0003או כלך\u0004 (לך) \u0003לדרך זו\u0004 של השוואה: \u0003נשיא מביא שעירה בעבודה זרה ומביא\u0004 גם \u0003אשם ודאי\u0004 על חטאים אחרים, \u0003ומשיח מביא שעירה\u0004 על \u0003עבודה זרה ומביא אשם ודאי,\u0004 ואילו הציבור מביא פר חטאת על עבודה זרה, ואינו מביא כלל אשם. ולכן נאמר גם כי \u0003מה נשיא מביא בשגגת מעשה\u0004 בלא העלם דבר, \u0003אף משיח מביא בשגגת מעשה\u0004 בלא העלם דבר, ואם כן מצד הסברה יש שיקולים לכל צד, ואין ללמוד את דינו של כהן משיח מבנין אב.","\u0003תלמוד לומר: \"לאשמת העם\"\u0004 (ויקרא ד, ג), לומר ש\u0003הרי הוא משיח כצבור, מה צבור אינו מביא אלא על העלם דבר עם שגגת מעשה, אף משיח אינו מביא אלא על העלם דבר עם שגגת מעשה.\u0004","ושואלים: אם דין הכהן המשיח כציבור, נשווה ביניהם לגמרי \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003מה צבור\u0004 אם \u0003הורה\u0004 בית הדין \u0003ועשו אחריו בהוראתו\u0004 — \u0003חייבין, אף משיח כשהורה ועשו אחריו\u0004 הציבור \u0003בהוראתו\u0004 — \u0003יהא חייב\u0004 אם סמכו על הוראתו! \u0003תלמוד לומר: \"והקריב על חטאתו אשר חטא\"\u0004 (ויקרא ד, ג), \u0003על מה שחטא הוא\u0004 עצמו בהוראתו הריהו \u0003מביא, ואין מביא על מה שחטאו אחרים\u0004 בהוראתו.","ונפנים לברר את האמור למעלה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003משיח בפר ואין מביא אשם תלוי.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 דין זה שהכהן המשיח \u0003אין מביא אשם תלוי?\u0004","\u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין האשם: \u0003\"וכפר עליו הכהן על שגגתו אשר שגג\"\u0004 (ויקרא ה, יח), והרי זה בא ללמד: \u0003מי שחטאתו ושגגתו שוה,\u0004 שמביא קרבן כאשר שגג במעשה ולא ידע שהוא אסור, \u0003יצא\u0004 מכלל זה \u0003משיח שאין שגגתו וחטאתו שוה,\u0004 שהרי הוא מביא קרבן רק אם שגג בהוראה ולא בטעות במעשה בלבד, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בכהן משיח: \u0003\"לאשמת העם\",\u0004 (ויקרא טז, ד, ג) לומר ש\u0003הרי הוא משיח כצבור.\u0004","על הראיה הזו תוהים: כיצד יכול לסמוך את דבריו על מדרש הכתוב \u0003\"לאשמת העם\"\u0004 הרי \u0003עד כאן לא קאמר ליה\u0004 \u0005[אמר אותו]\u0006 את הכתוב הזה, שהרי ממנו נובעת עיקר ההוכחה, ונמצא שהתנא של הברייתא מתבסס על ההלכה שאותה עצמה הוא צריך להוכיח. \u0003אלא אשם כדי נסבה\u0004 \u0005[לריק הביא אותו]\u0006 כלומר, אף שהדין הוא אמיתי, לא היה מקום להביאו כאן כלל.","\u0003הורה\u0004 הכהן הגדול \u0003בפני עצמו ועשה בפני עצמו\u0004 — \u0003מתכפר לו בפני עצמו\u0004 בפר העלם דבר שלו, \u0003הורה עם הצבור ועשה עם הצבור\u0004 — \u0003מתכפר לו עם הצבור, שאין בית דין חייבין עד שיורו לבטל מקצת\u0004 מן המצוה \u0003ולקיים מקצת, וכן\u0004 הדין בהוראת הכהן \u0003המשיח, ו\u0004כן \u0003לא\u0004 מתחייבים \u0003ב\u0004שגגת \u0003עבודה זרה עד שיורו לבטל מקצת ולקיים מקצת.\u0004","ומבררים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 שיש הבדל בין שגגת הכהן המשיח לעצמו לבין אם שגג עם הציבור? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003הורה עם הצבור ועשה עם הצבור, יכול יביא פר לעצמו?\u0004","\u0003ודין\u0004 (לימוד) \u0003הוא,\u0004 שכך אפשר היה ללמוד: \u0003נשיא מוצא מכלל יחיד ו\u0004אף \u0003משיח מוצא מכלל יחיד\u0004 ששניהם מביאים קרבנות חטאת מיוחדים, \u0003מה נשיא,\u0004 אם \u0003חטא בפני עצמו\u0004 — \u0003מביא\u0004 חטאת \u0003בפני עצמו\u0004 (שעיר נשיא), אם \u0003חטא עם הצבור\u0004 — \u0003מתכפר לו עם הצבור. אף משיח,\u0004 אם \u0003חטא בפני עצמו\u0004 — \u0003מביא בפני עצמו\u0004 (פר של כהן משיח), \u0003חטא עם הצבור\u0004 — \u0003מתכפר לו עם הצבור!\u0004","ודוחים: \u0003לא, אם אמרת בנשיא\u0004 — \u0003שכן מתכפר לו עם הצבור ביום הכפורים,\u0004 שהרי הוא לענין זה כאחד העם. \u0003תאמר במשיח\u0004 — \u0003שאין מתכפר לו עם הצבור ביום הכפורים,\u0004 אלא מביא פר מיוחד לקרבן לכפר על עצמו!","\u0003הואיל ואין מתכפר לו עם הצבור ביום הכפורים, יכול יביא פר לעצמו\u0004 גם אם שגג עם הציבור? \u0003תלמוד לומר: \"על חטאתו אשר חטא\"\u0004 (ויקרא ד, ג), שמשמע שהוא לבדו חטא, ולא עם הציבור, \u0003הא כיצד?\u0004 אם \u0003חטא בפני עצמו\u0004 — \u0003מביא בפני עצמו, חטא עם הצבור\u0004 — \u0003מתכפר לו עם הצבור.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]\u0006 שהכהן המשיח הורה בפני עצמו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003הוא\u0004 הכהן הגדול \u0003מופלא\u0004 בחכמתו \u0003והם\u0004 הדיינים של בית דין הגדול \u0003אינן מופלאין, פשיטא\u0004 \u0005[פשוט]\u0006 ש\u0003מתכפר לו בפני עצמו,\u0004 כי ה\u0003הוראה דלהון\u0004 \u0005[שלהם]\u0006 היא, אינה נחשבת \u0003ולא כלום,\u0004 שהרי לא שאלו את גדול הדור, \u0003ובעי אתויי\u0004 \u0005[ו\u0006הם \u0005צריכים להביא]\u0006 \u0003כשבה או שעירה\u0004 לחטאת \u0003כל חד וחד\u0004 \u0005[אחד ואחד],\u0006 שאין להוראה תוקף של הוראת בית דין! ולהיפך, \u0003ואי דאינון\u0004 \u0005[ואם שהם]\u0006 \u0003מופלאין והוא לאו\u0004 \u0005[לא]\u0006 \u0003מופלא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003מתכפר לו בפני עצמו? הא\u0004 \u0005[הרי]\u0006 \u0003הוראה דידיה\u0004 \u0005[שלו]\u0006 \u0003ולא\u0004 \u0003כלום היא\u0004 ואינה נחשבת כהוראה אלא כשגגת מעשה בלבד."],["\u0003אמר רב פפא: כגון שהיו מופלין שניהן\u0004 שגם הכהן המשיח וגם בית הדין היו גדולים בתורה ורשאים להורות.","\u0003סבר אביי למימר\u0004 \u0005[לומר]\u0006 כך: מה שאמרו במשנה \u0003חטא בפני עצמו ועשה בפני עצמו היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003דיתבי\u0004 \u0005[שיושבים]\u0006 הכהן הגדול ובית הדין \u0003בשני מקומות\u0004 שונים \u0003וקא מורו בתרי איסורי\u0004 \u0005[והם מורים בשני איסורים\u0006 שונים\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אטו\u0004 \u0005[וכי]\u0006 \u0003שני מקומות\u0004 הם ה\u0003גורמין\u0004 שייחשב כחטא בפני עצמו? \u0003אלא אפילו יתבי\u0004 \u0005[יושבים]\u0006 הכהן הגדול ובית הדין \u0003בחד מקום\u0004 \u0005[במקום אחד],\u0006 \u0003וכיון דקא מורו בתרי איסורי\u0004 \u0005[שהם מורים בשני איסורים\u0006 שונים\u0005]\u0006 \u0003חטא בפני עצמו הוא.\u0004","ומעתה דנים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, אם \u0003הוא\u0004 הורה \u0003בחלב והן בעבודה זרה,\u0004 הרי זה ברור ש\u0003חטא בפני עצמו הוא, דהא\u0004 \u0005[שהרי]\u0006 \u0003חלוקין בטעמייהו\u0004 \u0005[בטעמיהם],\u0006 שלכל אחד מהם יש מקור אחר לדבריו מכתובים שונים \u0003ו\u0004גם שהם \u0003חלוקין בקרבנות,\u0004 ש\u0003הוא\u0004 הכהן הגדול מתכפר על שגגתו בחטא זה \u0003בפר, והן\u0004 בית הדין בשגגת עבודה זרה מתכפרים \u0003בפר ושעיר, דהא קא מייתו הני\u0004 \u0005[שהרי הללו מביאים הם]\u0006 גם \u0003שעיר, והוא לא מייתי\u0004 \u0005[מביא].\u0006 \u0003וכל שכן\u0004 אם \u0003הוא\u0004 שגג \u0003בעבודה זרה והן\u0004 הורו \u0003בחלב,\u0004 ש\u0003חלוקין בקרבנותיהן לגמרי,\u0004 ש\u0003הוא\u0004 מביא \u0003שעירה\u0004 לחטאת, \u0003ואינהו\u0004 \u0005[והם]\u0006 מביאים \u0003פר,\u0004","\u0003אלא\u0004 הספק הוא כאשר \u0003הוא\u0004 הורה למשל \u0003בחלב המכסה את הקרב והן\u0004 הורו \u0003בחלב שעל הדקין\u0004 (מעיים), \u0003מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 במקרה זה: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003קרבנן שוה, כיון דמתרי קראי קאתו\u0004 \u0005[שמשני מקראות\u0006 שונים \u0005באים,\u0006 נובעים\u0005]\u0006 האיסורים הללו \u0003הא פליגין בטעמייהו\u0004 \u0005[הרי\u0006 הם \u0005חלוקים בטעמיהם],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שם חלב אחד הוא,\u0004 והוא נחשב כחטא אחד?","\u0003אם תמצא לומר שם חלב אחד הוא,\u0004 אם הורה \u0003הוא בחלב והן בדם, מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003בטעמייהו הא פליגין\u0004 \u0005[בטעמיהם הרי\u0006 הם \u0005חלוקים],\u0006 שהרי יש לכל איסור מקור אחר בתורה, ואם מתירים אותם הרי זה מפני נימוקים שונים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003שוין בקרבן\u0004 (שכפרת חלב ודם שוה) \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003קרבן אזלינן\u0004 \u0005[אנו הולכים]?\u0006 שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ומבררים את ההלכות האמורות במשנתנו. שנינו \u0003שאין בית דין חייבין עד שיורו לבטל מקצת ולקיים מקצת וכו'.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003עד שיורו לבטל מקצת ולקיים מקצת?\u0004 ומשיבים: \u0003כדאמרינן באידך פירקין\u0004 \u0005[כמו שאמרנו בפרק האחר\u0006 הראשון במסכת \u0005שלנו]:\u0006 \u0003\"ונעלם דבר\"\u0004 (ויקרא ד, יג) לומר \u0003\"דבר\"\u0004 — \u0003ולא כל הגוף.\u0004","עוד שנינו: \u0003וכן המשיח.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 הלכה זו? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לאשמת העם\"\u0004 (ויקרא ד, ג), לומר ש\u0003הרי משיח כצבור.\u0004","עוד שנינו: \u0003ולא בעבודה זרה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003לפי שיצאה עבודה זרה לדון בעצמה,\u0004 שיש פרק מיוחד (במדבר טו) שנתייחד לשגגת עבודה זרה, \u0003יכול יהו חייבין\u0004 בענין זה \u0003על עקירת מצוה כולה?\u0004","ומשיבים: \u0003נאמר כאן\u0004 בעבודה זרה \u0003\"מעיני\"\u0004 (במדבר טו, כד) \u0003ונאמר להלן\u0004 בהעלם דבר של ציבור בשאר עבירות \u0003\"מעיני\"\u0004 (ויקרא ד, יג), \u0003מה להלן\u0004 מדובר \u0003בבית דין, אף כאן נמי\u0004 \u0005[גם כן]\u0006 \u0003בבית דין, ומה להלן\u0004 בשגגת ציבור, מדובר על העלם \u0003דבר\u0004 מן המצוה \u0003ולא כל הגוף, אף כאן נמי\u0004 \u0005[גם כן]\u0006 \u0003דבר ולא כל הגוף.\u0004","\u0003אין חייבין\u0004 בית הדין \u0003אלא על העלם דבר\u0004 של טעות בהוראה \u0003עם שגגת המעשה\u0004 ששגגו העם ועשו לפי הוראה זו, \u0003וכן המשיח\u0004 אינו חייב אלא באופן זה, בטעות הוראה שהוא נוהג לפיה, \u0003ולא\u0004 \u0003בעבודה זרה\u0004 — \u0003אין חייבין\u0004 בית דין להביא קרבן \u0003אלא על העלם דבר עם שגגת המעשה.\u0004","ומבררים את ההלכות במשנתנו. שנינו שאין חייבים אלא על העלם דבר עם שגגת מעשה. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר \u0003\"ישגו\"\u0004 (ויקרא ד, יג) — \u0003יכול יהו חייבין\u0004 להביא פר \u0003על שגגת מעשה? תלמוד לומר: \"ישגו ונעלם דבר\"\u0004 (ויקרא ד, יג), ללמד ש\u0003אין חייבין אלא על העלם דבר עם שגגת מעשה.\u0004","עוד שנינו: \u0003וכן המשיח.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במשיח: \u0003\"לאשמת העם\"\u0004 (ויקרא ד, ג), \u0003הרי\u0004 למדנו כי \u0003משיח\u0004 דינו \u0003כצבור.\u0004","עוד שנינו במשנה: \u0003ולא בעבודה זרה אלא על העלם דבר עם שגגת המעשה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה?","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003לפי שיצאה עבודה זרה לדון בעצמה, יכול יהו חייבין\u0004 בה \u0003על שגגת המעשה\u0004 בלבד? ומשיבים: \u0003נאמר כאן \"מעיני\" ונאמר להלן \"מעיני\", מה להלן אין חייבין\u0004 בית דין \u0003אלא על העלם דבר עם שגגת מעשה, אף כאן אין חייבין אלא על העלם דבר עם שגגת מעשה.\u0004","ומעירים: \u0003ואילו משיח בעבודה זרה לא קתני\u0004 \u0005[שנה]\u0006 ולא פירש שדינו כבית דין, ואם כן \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבי היא;\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003משיח\u0004 ששגג \u0003בעבודה זרה\u0004 — \u0003רבי אומר:\u0004 מביא קרבן \u0003בשגגת מעשה,\u0004 שאם שגג במעשה בלבד כשאר העם, מביא קרבן. \u0003וחכמים אומרים:\u0004 \u0003בהעלם דבר. ושוין\u0004 שניהם \u0003ש\u0004מביא הכהן המשיח קרבנו לכפר על עבודה זרה \u0003בשעירה, ושוין שאין מביא אשם תלוי.\u0004 וממה שמשנתנו השמיטה את דין הכהן המשיח בעבודה זרה נראה שהיא כדעת רבי האומר שלענין זה דינו כאדם פרטי.","ודוחים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור\u0006 כן\u0005]\u0006 הרי את ההלכה שאין חייב הכהן משיח בעבודה זרה אלא על דבר ש\u0003בזדונו כרת ובשגגתו חטאת מי קתני\u0004 \u0005[האם שנה]?\u0006","\u0003אלא תני הא\u0004 \u0005[שנה\u0006 דבר \u0005זה]\u0006 שחייב בשאר עבירות על העלם דבר ושגגת מעשה \u0003הוא הדין להא\u0004 \u0005[לזה],\u0006 שחייבים בעבודה זרה על דבר שזדונו כרת, \u0003הכא נמי תנא הא\u0004 \u0005[כך גם כן שנה זה]\u0006 שדין המשיח כדין ציבור בשאר עבירות \u0003והוא הדין להא\u0004 \u0005[לזה].\u0006 דינו של משיח בעבודה זרה. ואם כן אין להוכיח מכאן שמשנתנו איננה כדברי חכמים.","ולגופו של דבר, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי? אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין עבודה זרה: \u0003\"וכפר הכהן על הנפש השגגת בחטאה בשגגה\"\u0004 (במדבר טו, כח), \u0003\"הנפש\"\u0004 — \u0003זה משיח, \"השגגת\"\u0004 — \u0003זה נשיא, \"בחטאה בשגגה\"\u0004 — \u0003רבי סבר: חטא זה בשגגה יהא,\u0004 ולא בהעלם דבר.","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 הפסוק בא לומר שדין זה הוא ב\u0003מי שחטאתו\u0004 בשאר עבירות היא \u0003בשגגה, יצא משיח שאין\u0004 קרבן \u0003חטאתו\u0004 המיוחד \u0003בשגגה\u0004 בלבד \u0003אלא בהעלם דבר.\u0004","שנינו בברייתא: \u0003ושוין\u0004 רבי וחכמים \u0003ש\u0004הוא מביא \u0003שעירה כיחיד.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואם נפש אחת\u0004 תחטא בשגגה והקריבה עז בת שנתה לחטאת\" (ויקרא ד, כז), לומר: \u0003אחד יחיד\u0004 סתם \u0003ואחד נשיא ואחד משיח\u0004 — \u0003כולם בכלל נפש אחת הן.\u0004"],["\u0003ו\u0004עוד שנינו בברייתא כי רבי וחכמים \u0003שוין שאין מביא אשם תלוי.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בענין האשם התלוי: \u0003\"וכפר עליו הכהן על שגגתו אשר שגג\"\u0004 (ויקרא ה, יח), ובפירוש כוונת פסוק זה נחלקו רבי וחכמים לשיטותיהם; \u0003רבי סבר: מי שכל חטאו בשגגה\u0004 כלומר, שכל חטאת שהוא מביא אינה אלא על שגגת מעשה, \u0003יצא\u0004 (למעט) \u0003זה\u0004 הכהן המשיח \u0003שאין כל חטאו בשגגה אלא\u0004 מביא חטאת אם היה גם \u0003בהעלם דבר.\u0004","ותוהים: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003\"כל\u0004 חטאו בשגגה\" \u0003כתיב\u0004 \u0005[נאמר]?\u0006 הרי נאמר רק \"על שגגתו\"! ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 כלומר, אף שלא נאמר \"כל\", זו היא משמעות הכתוב, ש\u0003אם כן נכתוב\u0004 \u0005[שיכתוב]\u0006 רק \u0003\"על שגגתו\", למה לי\u0004 התוספת \u0003\"אשר שגג\"? הא קא משמע לן\u0004 \u0005[זה משמיע לנו]\u0006 ש\u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003כל חטאו בשגגה,\u0004 מביא אשם תלוי, \u0003יצא משיח שאין כל חטאו בשגגה אלא בעבודה זרה, ולא בשאר מצו‍ת\u0004 שבהן אינו מביא קרבן \u0003אלא בהעלם דבר עם שגגת מעשה.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מפרשים את הכתוב לשיטתם שהכהן המשיח, גם בעבודה זרה, מביא קרבן רק על העלם דבר ושגגת מעשה: \u0003מי שחטאו בשגגה, יצא משיח שאין חטאו בשגגה לא בעבודה זרה ולא בשאר מצו‍ת אלא בהעלם דבר עם שגגת מעשה.\u0004","\u0003אין בית דין חייבין\u0004 להביא קרבן על העלם דבר \u0003עד שיורו בדבר שזדונו\u0004 (אם עושים אותו בזדון) חייבים עליו \u0003כרת ושגגתו חטאת, וכן המשיח\u0004 חייב רק על הוראה כזו, \u0003ו\u0004כן \u0003לא\u0004 חייבים בחטאת \u0003בעבודה זרה עד שיורו על דבר שזדונו כרת ושגגתו חטאת.\u0004","על האמור במשנה שאין חייבים אלא על דבר שזדונו כרת ושגגתו חטאת שואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה?","ומשיבים: \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: נאמר כאן \"עליה\"\u0004 (\"החטאת אשר חטאו עליה\". ויקרא ד, יד) \u0003ונאמר להלן\u0004 באיסור לקיחת שתי אחיות \u0003\"עליה\"\u0004 (\"ואשה אל אחותה לא תקח לצרור לגלות ערותה עליה\". ויקרא יח, יח), ללמדנו: \u0003מה להלן\u0004 הוא \u0003דבר שזדונו כרת ושגגתו חטאת, אף כאן\u0004 הוא דווקא \u0003דבר שזדונו כרת ושגגתו חטאת.\u0004","ואומרים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ראיה לענין \u0003צבור,\u0004 ואולם \u0003משיח מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: שנאמר בענין המשיח \u0003\"לאשמת העם\"\u0004 (ויקרא ד, ג), לומר: \u0003הרי משיח כצבור.\u0004","ושואלים: \u0003נשיא\u0004 מנין לנו דין זה בו? ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 \u0003\"מצות\" \"מצות\", כתיב גבי\u0004 \u0005[נאמר אצל]\u0006 \u0003נשיא: \"ועשה אחת מכל מצו‍ת ה'\u0004 אשר לא תעשינה\" (ויקרא ד, כב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בצבור: \"ועשו אחת מכל מצות\u0004 ה' אשר לא תעשינה\" (ויקרא ד, יג), והרי זה ללמד: \u0003מה צבור\u0004 — חייבים על \u0003דבר שזדונו כרת ושגגתו חטאת, אף נשיא\u0004 — חייב על \u0003דבר שזדונו כרת ושגגתו חטאת.\u0004","ושואלים עוד: \u0003יחיד\u0004 מנין שעל דבר שכזה הוא מביא חטאת? ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואם נפש\u0004 אחת תחטא בשגגה מעם הארץ\" (ויקרא ד, כז), שיש ו' החיבור המחבר בין זה לזה שקדם \u0003וילמד תחתון מעליון,\u0004 שכמו שעל הדברים שאמורים קודם (\"עליון\") מביא רק על דבר שזדונו כרת, כך דין זה שנמצא אחריהם (\"תחתון\") אף הוא בדבר שזדונו כרת.","שנינו במשנה: \u0003ולא בעבודה זרה עד שיורו\u0004 בדבר שזדונו כרת וכו'. ושואלים: \u0003בעבודה זרה מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003לפי שיצאה עבודה זרה לדון בעצמה,\u0004 שהרי מביאים עליה קרבנות אחרים, \u0003יכול יהו\u0004 בית דין \u0003חייבין אפילו על דבר שאין זדונו כרת ושגגתו חטאת?\u0004","ומשיבים: \u0003נאמר כאן\u0004 בענין שגגת עבודה זרה \u0003\"מעיני\"\u0004 (במדבר טו, כב), \u0003ונאמר להלן\u0004 בשאר עבירות \u0003\"מעיני\"\u0004 (ויקרא ד, יג), \u0003מה להלן דבר שזדונו כרת ושגגתו חטאת, אף כאן דבר שזדונו כרת ושגגתו חטאת.\u0004","\u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה לגבי \u0003צבור.\u0004 ב\u0003יחיד, נשיא, משיח\u0004 בעבודה זרה \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הדין? \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואם נפש אחת\"\u0004 (ויקרא ד, יג), לומר אחד יחיד ואחד נשיא ואחד משיח כולן בכלל \"נפש אחת\" הן, וילמד תחתון יחיד נשיא ומשיח, \u0003מן העליון\u0004 מציבור שמביאים רק על דבר שזדונו כרת.","ושואלים: \u0003הניחא למאן דמפיק לה\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שמוציא\u0006 את \u0005זאת]\u0006 המלה \u0003\"עליה\" לגזרה שוה\u0004 ללמוד שאין בית דין חייבים בהוראה אלא בדבר שזדונו כרת, \u0003כדאמרן\u0004 \u0005[כמו שאמרנו],\u0006 \u0003אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003דמפקי לה\u0004 \u0005[שמוציאים אותה]\u0006 את המלה \u0003\"עליה\"\u0004 האמור בפרשת עריות, ללמד \u0003ל\u0004ענין \u0003עריות וצרות\u0004 לעריות בדיני יבמות, אם כן \u0003דבר שזדונו כרת ושגגתו חטאת\u0004 בציבור עצמו \u0003מנא להו\u0004 \u0005[מנין להם]?\u0006","ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 דבר זה \u0003מדמתני ליה\u0004 \u0005[כמו שהיה משנה,\u0006 מלמד אותו\u0005]\u0006 \u0003ר' יהושע בן לוי לבריה\u0004 \u0005[לבנו]:\u0006 נאמר \u0003\"תורה אחת יהיה לכם לעשה בשגגה והנפש אשר תעשה ביד רמה\" וגו'\u0004 (במדבר טו, כט —ל), \u0003הוקשה\u0004 (הושוותה) \u0003כל התורה כולה\u0004 (\"תורה אחת\") \u0003לעבודה זרה, מה עבודה זרה\u0004 חייבים עליה קרבן חטאת רק בדבר \u0003שחייבין על זדונו כרת ועל שגגתו חטאת, אף כאן\u0004 בכל התורה הדין הוא \u0003שחייבין על\u0004 דבר ש\u0003זדונו כרת ועל שגגתו חטאת.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא דין זה לגבי \u0003יחיד, נשיא, ומשיח בין בעבודה זרה בין בשאר מצו‍ת\u0004 שכל אלו הוקשו בפסוק \"ואם נפש וגו' \" לעבודה זרה, \u0003צבור מנלן\u0004 \u0005[מנין לנו]\u0006 שהם מביאים רק על דבר שזדונו כרת? ומשיבים: \u0003יליף\u0004 \u0005[לומד]\u0006 \u0003עליון\u0004 שכתוב למעלה בענין הציבור \u0003מתחתון\u0004 ממה שכתוב למטה הלאה בענין יחיד.","ושואלים: \u0003ורבי\u0004 שלמד דבר זה מהמילה \"עליה\", \u0003הא\u0004 \u0005[זה]\u0006 הכתוב שדרש \u0003ר' יהושע בן לוי מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005לו]?\u0006 ומשיבים: \u0003מפיק ליה לכדתניא\u0004 \u0005[מוציא,\u0006 דורש \u0005אותו לכמו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לפי שמצינו שחלק הכתוב\u0004 בדין עבודה זרה \u0003בין רבים\u0004 רוב העיר \u0003ליחידים\u0004 שחטאו, ש\u0003רבים\u0004 בעיר הנדחת נידונים \u0003בסייף וממונן אבד\u0004 שצריכים להשמיד גם את רכושם, ואילו \u0003יחידים\u0004 נידונים \u0003בסקילה וממונן פלט, יכול\u0004 אם עשו בשגגה \u0003נחלוק בקרבנותיהם? תלמוד לומר: \"תורה אחת יהיה\u0004 לכם לעושה בשגגה\" (במדבר טו, כט —ל).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חלקיה מהגרוניא: טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא חלק הכתוב\u0004 בענין זה, \u0003הא חלק\u0004 \u0005[הרי\u0006 אם \u0005היה מחלק]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003נחלוק\u0004 שיביאו רבים שחטאו קורבן שונה על שגגתם. ונברר: \u0003מאי נייתי\u0004 \u0005[מה,\u0006 איזה קרבן \u0005יביאו]?\u0006","אם נאמר \u0003נייתי\u0004 \u0005[שיביאו]\u0006 \u0003פר,\u0004 הלוא \u0003צבור בשאר מצו‍ת הוא דמייתו\u0004 \u0005[שמביאים]!\u0006 אלא תאמר \u0003נייתי\u0004 \u0005[שיביאו]\u0006 \u0003פר לעולה ושעיר לחטאת,\u0004 הרי \u0003צבור בעבודה זרה הוא דמייתו\u0004 \u0005[שמביאים]\u0006 קרבן זה בהעלם דבר! \u0003נייתי\u0004 \u0005[שיביאו]\u0006 קרבן \u0003שעיר,\u0004 הלוא \u0003נשיא בשאר מצו‍ת הוא דמייתי\u0004 \u0005[שמביא]\u0006 קרבן זה! \u0003נייתי\u0004 \u0005[שיביאו]\u0006 \u0003שעירה, יחיד נמי היינו\u0004 \u0005[גם כן זהו]\u0006 \u0003קרבנו\u0004 שהוא מביא!","ודוחים: \u0003אלמה\u0004 \u0005[מפני מה]\u0006 \u0003לא איצטריך\u0004 \u0005[הוצרך]\u0006 הכתוב \"תורה אחת\" להשוותם? שהרי יש אפשרות אחרת, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003צבור מייתי\u0004 \u0005[מביא]\u0006 \u0003פר לעולה ושעיר לחטאת, הני נייתי איפכא\u0004 \u0005[אלה\u0006 רבים שחטאו \u0005שיביאו להיפך],\u0006 \u0003פר לחטאת ושעיר לעולה. אי נמי\u0004 \u0005[או גם כן]\u0006 יכול להיות ש\u0003צריך\u0004 מספר רב של אנשים ששגגו בעבודה זרה להביא קרבן אחר \u0003ואין לו תקנה\u0004 לפי שאין דרך לעשות זאת, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שאין מחלקים בין רבים ליחידים לענין זה.","ושואלים: \u0003דכולי עלמא מיהת\u0004 \u0005[על כל פנים ל\u0006דעת \u0005הכל]\u0006 \u0003כי כתיבי הני קראי\u0004 \u0005[כאשר נאמרו המקראות אלה]\u0006 בספר במדבר — \u0003בעבודה זרה הוא דכתיבי\u0004 \u0005[שנאמרו],\u0006 אבל אין הדבר מפורש במקרא שמדובר שם בעבודה זרה, אם כן \u0003מאי משמע\u0004 \u0005[מה המשמעות]?\u0006 כיצד עולה משמעות זו מן הכתוב! \u0003אמר רבא, ואי תימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יהושע בן לוי, ואמרי לה כדי\u0004 \u0005[ויש אומרים אותה סתם]\u0006 בלי שם, \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"וכי תשגו ולא תעשו את כל המצו‍ת האלה\u0004 אשר דבר ה' אל משה\" (במדבר טו, כב), \u0003איזו היא מצוה שהיא שקולה ככל המצו‍ת? הוי אומר: זו עבודה זרה.\u0004","\u0003דבי\u0004 \u0005[בבית המדרש]\u0006 של \u0003רבי תנא\u0004 \u0005[שנה],\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"אשר דבר ה' אל משה\"\u0004 (במדבר טו, כב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אשר צוה ה' אליכם ביד משה\"\u0004 (במדבר טו, כג), \u0003איזו היא מצוה שהיא בדיבורו של הקדוש ברוך הוא\u0004 באופן שגם כל ישראל שמעוה, כשדיבר ה' אל משה, \u0003ו\u0004גם \u0003צוה\u0004 אותה בתורה \u0003על ידי משה? הוי אומר: זו עבודה זרה,\u0004 ומנין שנאסרה מצוה זו מפי ה' אלינו? \u0003דתנא\u0004 \u0005[ששנה]\u0006 \u0003ר' ישמעאל:\u0004 הדברות של \u0003\"אנכי\" ו\"לא יהיה לך\u0004 אלהים אחרים על פני\" (שמות כ, ב—ג) \u0003מפי הגבורה שמענום\u0004 כלומר, כל ישראל שמעו אותם במישרין מפי ה'.","\u0003דבי\u0004 \u0005[בבית המדרש]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006"],["\u0003\"למן היום אשר צוה ה' והלאה לדורותיכם\"\u0004 (במדבר טו, כג), \u0003איזו היא מצוה שהיא נאמרה בתחלה\u0004 ראשונה לכל המצות? \u0003הוי אומר: זו עבודה זרה\u0004 שנאמרה ראשונה בעשרת הדברות. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003עשר מצו‍ת נצטוו ישראל\u0004 בהיותם \u0003במרה\u0004 ביציאתם ממצרים, קודם למתן תורה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"והיה אם שמוע תשמע לקול ה' אלהיך\u0004. . .והאזנת למצוותיו\" (שמות טו, כו), ואם כן היו מצוות קודמות לכך? \u0003אלא, מחוורתא כדשנינן מעיקרא\u0004 \u0005[ברור כמו שתירצנו מתחילה].\u0006","\u0003אין\u0004 בית דין \u0003חייבין\u0004 פר העלם דבר של ציבור \u0003על\u0004 הוראת \u0003עשה ועל לא תעשה שבמקדש\u0004 הנאמר בדין טומאת מקדש, והוא בעשה שצריך להוציא את הטמאים מן המקדש, ובלא תעשה שאסור להיכנס למקדש כשהוא טמא, \u0003ואין מביאין\u0004 כלל \u0003אשם תלוי על עשה ועל לא תעשה שבמקדש.\u0004","\u0003אבל חייבין\u0004 בית דין \u0003על עשה ועל לא תעשה שבנדה, ומביאים אשם תלוי על עשה ועל לא תעשה שבנדה. איזו היא מצות עשה שבנדה? פרוש מן הנדה,\u0004 שאם בא על אשה ונטמאה הנדה — חייב לפרוש ממנה, \u0003ומצות לא תעשה? אל תבא על הנדה.\u0004 אם יודע אתה שהיא טמאה.","על האמור במשנתנו שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 ש\u0003צבור לא מחייבי\u0004 \u0005[חייבים]\u0006 \u0003קרבן בעלמא\u0004 \u0005[בכלל]\u0006 על חטא כמו זה של טומאת המקדש שיש בו רק לאו ואין חייבים על שגגתו חטאת, \u0003ויחיד אשם תלוי נמי\u0004 \u0005[גם כן]\u0006 מניין ש\u0003לא\u0004 מביא בטומאת המקדש?","\u0003אמר רב יצחק בר אבדימי: נאמר \"ואשם\"\u0004 (ויקרא ד, כז) \u0003בחטאת ובאשם תלוי\u0004 (ויקרא ה, יז), \u0003ונאמר \"ואשמו\"\u0004 (ויקרא ד, יג) \u0003בצבור, מה \"ואשם\"\u0004 האמור \u0003ביחיד\u0004 הרי הוא בא על חטא שהוא \u0003בחטאת קבועה,\u0004 כמפורש שם, \u0003אף \"ואשמו\"\u0004 האמור \u0003ב\u0004חטא של \u0003צבור\u0004 הרי הוא דווקא \u0003ב\u0004חטא שיש עליו \u0003חטאת קבועה,\u0004 להוציא טומאת המקדש וקדשיו, שהיא בחטאת עולה ויורדת ואינה קבועה.","\u0003ומה צבור\u0004 דווקא \u0003בחטאת קבועה, אף אשם תלוי נמי\u0004 \u0005[גם כן]\u0006 \u0003אין בא אלא על ספק חטאת קבועה,\u0004 ומכאן למדנו שבטומאת המקדש וקדשיו אין הציבור מביא, ואין היחידים מביאים כלל אשם תלוי. \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם על הלימוד ממלה זו אתה נסמך, \u0003קרבן עולה ויורד נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר\u0006 בו\u0005]:\u0006 \u0003והיה כי יאשם לאחת מאלה\"\u0004 (ויקרא ה, ה)! ומשיבים: \u0003דנין \"אשם\" מן \"אשמו\" ואין דנין \"אשם\" מן \"יאשם\",\u0004 אף ששניהם בלשון יחיד נאמרו. ומקשים: \u0003ומאי\u0004","\u0003נפקא מינה\u0004 \u0005[ומה יוצא מכאן]\u0006 שיש הבדל? \u0003והא תני דבי\u0004 \u0005[והרי שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: \"ושב הכהן\"\u0004 (ויקרא יד, טו) \u0003\"ובא הכהן\"\u0004 (ויקרא יד מב) — \u0003זו היא שיבה זו היא ביאה\u0004 שעניינם אחד, ויש כאן גזירה שווה, למרות שהמילים אינן דומות כלל! \u0003ועוד\u0004 אפשר להקשות: \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003מן \"ואשם\" מטומאת מקדש וקדשיו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והוא טמא ואשם\"\u0004 (ויקרא ה, ב)!","\u0003אמר רב פפא: דנין\u0004 מקום שכתוב בו \u0003\"ואשם\" ו\u0004גם \u0003\"מצות ה'\"\u0004 באשם התלוי (ויקרא ה, יז) \u0003מן\u0004 קרבן הציבור שכתוב בו \u0003\"ואשם\" ו\"מצות ה' \"\u0004(ויקרא ד, יג) ולא מקרבן עולה ויורד שלא נאמר בו \"מצות ה'\". \u0003אמר ליה\u0004 (לו) \u0003רב שימי בר אשי לרב פפא: ונילף\u0004 \u0005[ונלמד]\u0006 \u0003\"ואשם\" ונשיאת עון מן \"ואשם\" ונשיאת עון\u0004 שכתוב בטומאת מקדש ובאשם תלוי!","\u0003אלא\u0004 יש לדחות מה שאמרנו, \u0003אמר רב נחמן בר יצחק: דנין\u0004 מקום שכתוב בו \u0003\"ואשם\" ו\"מצו‍ת ה' אשר לא תעשינה\"\u0004 באשם תלוי \u0003מ\u0004מקום שכתוב בו \u0003\"ואשם\" ו\"מצו‍ת ה' אשר לא תעשינה\",\u0004 בחטאת קבועה, \u0003ואל יוכיח שמיעת קול וביטוי שפתים וטומאת מקדש וקדשיו\u0004 (שכולם בעולה ויורד) \u0003שלא נאמר בהם \"ואשם\" ו\"מצו‍ת ה' אשר לא תעשינה\".\u0004","\u0003אין\u0004 בית דין \u0003חייבין\u0004 בהוראה \u0003על שמיעת קול\u0004 (שבועת העדות), שדורשים מאדם להעיד על מה שידע ואינו מעיד, \u0003ועל ביטוי שפתים\u0004 (שבועת שקר), \u0003ועל טומאת מקדש וקדשיו. והנשיא כיוצא בהם,\u0004 שגם הוא פטור מלהביא קרבן על חטאים אלה, אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: הנשיא חייב בכולן חוץ משמיעת הקול,\u0004 והטעם אינו משום פטור מהותי אלא משום \u0003שהמלך לא דן ולא דנין אותו, לא מעיד ולא מעידין אותו,\u0004 וכיון שכך לא שייך בו הציווי שיבוא להעיד עדות.","על האמור במשנה \u0003אמר עולא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי הגלילי? אמר קרא\u0004 \u0005[המקרא]\u0006 בקרבן עולה ויורד: \u0003\"והיה כי יאשם לאחת מאלה\"\u0004 (ויקרא ה, ב) לומר: \u0003כל שמתחייב באחת\u0004 מהן \u0003מתחייב בכולן, ושאין מתחייב באחת אין מתחייב בכולן.\u0004 וכיון שהמלך פטור מאחת (שמיעת קול) הריהו פטור גם מן האחרות.","ומקשים: מדוע נאמר כך? \u0003ואימא\u0004 \u0005[ואמור]\u0006 אחרת: מי ש\u0003מתחייב באחת מהן ואף על פי שאין מתחייב בכולן!\u0004","\u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יוסי הגלילי מהכא\u0004 \u0005[מכאן],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' ירמיה אומר: נאמר\u0004"],["\u0003\"לא תגיע ידו\"\u0004 (ויקרא ה, ז), \u0003ונאמר \"לא תשיג ידו\"\u0004 (ויקרא ה, יא), לומר שדינים אלה אמורים דווקא ב\u0003מי שבא לידי עניות ועשירות, יצא\u0004 מכלל זה \u0003נשיא ומשיח שאין באין לידי עניות,\u0004 שהרי","\u0003נשיא\u0004 אינו בא לידי עניות — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשה אחת מכל מצו‍ת ה' אלהיו\"\u0004 (ויקרא ד, כב), ולפיכך הגדרת נשיא היא: \u0003מי שאין על גביו אלא ה' אלהיו\u0004 שהוא גדול מכל העם, ואין הוא עני התלוי באחרים. \u0003משיח\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והכהן הגדול מאחיו\"\u0004 (ויקרא כא, י), לומר: \u0003שהוא גדול מאחיו בנוי בכח בחכמה ובעושר,\u0004 ולכן אינו בא לידי עניות. \u0003אחרים אומרים: מנין שאם אין לו\u0004 לכהן הגדול עושר משלו יש ל\u0003גדלהו מ\u0004כספם \u0003של אחיו? תלמוד לומר: \"והכהן הגדול מאחיו אשר יוצק על ראשו\"\u0004 (ויקרא כא, י), לומר: \u0003גדלהו מאחיו\u0004 כלומר, שאחיו יתנו לו משלהם עד שיתעשר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבינא מרב נחמן בר יצחק: נשיא שנצטרע, מהו\u0004 דינו לענין קרבן עולה ויורד? וצדדי השאלה: האם \u0003מידחא דחי\u0004 \u0005[נדחה\u0006 לגמרי\u0005]\u0006 \u0003או\u0004 רק \u0003מיפטר פטיר\u0004 \u0005[פטור]?\u0006 כלומר, האם בזמן נשיאותו הוא נדחה לגמרי מקרבן עולה ויורד, ואינו מתחייב עוד על כך, או שרק נפטר מקרבן זה, וכשנצטרע הריהו חוזר לחיובו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דילך\u0004 \u0005[משלך]\u0006 הוא נוטל \u0003או דגזא\u0004 \u0005[משל האוצר]\u0006 הפרטי שלו? וכיון שהוא נוטל משל האוצר לא בטל חיובו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: משיח פטור מכולן,\u0004 מכל קרבן עולה ויורד. \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא? אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"זה קרבן אהרן ובניו\u0004 אשר יקריבו לה' ביום המשח אותו עשירית האיפה סלת מנחה . . .\" (ויקרא ו, יג). ומדייקים: דווקא \u0003זו\u0004 עשירית האיפה \u0003באה חובה לו, ואין אחרת באה חובה לו.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003כי ממעט ליה רחמנא\u0004 \u0005[כאשר ממעטת אותו,\u0006 את כהן משיח, \u0005התורה]\u0006 הרי זה דווקא \u0003מדלי דלות,\u0004 כלומר, מקרבן מנחת סולת שמביאים העניים שבעניים, \u0003ומאי ניהו\u0004 \u0005[ומהו]?\u0006 \u0003עשירית האיפה,\u0004 כאמור בכתוב, \u0003אבל\u0004 לגבי דבר שיש בו רק \u0003עניות ועשירות\u0004 כשבים או תורים, \u0003לא מעטיה רחמנא\u0004 \u0005[מיעטו הכתוב]!\u0006 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בענין קרבן עולה ויורד: \u0003\"וכפר עליו הכהן על חטאתו אשר חטא מאחת מאלה\"\u0004 (ויקרא ה, יג), לומר: זה \u0003המתכפר באחת\u0004 מהן מכל אחת מקרבנות אלה — \u0003מתכפר בכולן, ו\u0004אילו זה \u0003שאין מתכפר באחת\u0004 — כהן גדול שאינו מביא קרבן מנחה — \u0003אין מתכפר בכולן.\u0004","ותוהים: \u0003אלא מעתה,\u0004 לפי דרך דרשה זו, זה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"והיה כי יאשם לאחת מאלה\"\u0004 (ויקרא ה, ה), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר באותו אופן: ש\u0003כל המתחייב באחת\u0004 מאלה שחייבים בקרבן עולה ויורד — \u0003מתחייב בכולן, ושאין מתחייב באחת\u0004 — \u0003אין מתחייב בכולן, אלמה תנן\u0004 \u0005[מפני מה שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' עקיבא אומר: נשיא חייב חוץ משמיעת קול,\u0004 משמע שיכול להתחייב באחת ולא בכולן!","\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כתירוץ לקושי זה: הכתוב \u0003\"מאחת\" משמע ליה\u0004 \u0005[נשמע לו]\u0006 לר' עקיבא ללמוד מכאן, אבל הכתוב \u0003\"לאחת\" לא משמע ליה\u0004 \u0005[נשמע לו]\u0006 כלימוד. ושואלים על כך: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 הכתוב \u0003\"מאחת\"\u0004 מהכתוב \"לאחת\" \u0003דמשמע ליה\u0004 \u0005[שנשמע לו]\u0006 כלימוד?","ומשיבים: \u0003דכתביה רחמנא\u0004 \u0005[שכתבה אותו התורה]\u0006 \u0003לבסוף\u0004 בסוף פרשת קרבן עולה ויורד \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עשירית האיפה, למימרא\u0004 \u0005[לומר]\u0006 ש\u0003כל דמחייב\u0004 \u0005[שמתחייב]\u0006 \u0003ב\u0004הבאת \u0003עשירית האיפה\u0004 — \u0003מחייב\u0004 \u0005[מתחייב]\u0006 \u0003בכולן, דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר \u0003מתחייב באחת אף על פי שאין מתחייב בכולן,\u0004 אם כן \u0003נכתביה להאי\u0004 \u0005[שיכתוב את\u0006 ההוראה \u0005הזו]\u0006 \u0003\"מאחת מאלה\" בדלות, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003בעשירות,\u0004 וכיון שלא כתב קודם לכן — משמע שדווקא בענין זה נאמר שמי שלא מתחייב בזו פטור מן הכל. לפיכך כהן משיח שאינו מתכפר בעשירית האיפה, אינו מתכפר בקרבן עולה ויורד כלל.","ובסיכומם של דברים: \u0003כל המצו‍ת שבתורה שחייבין על זדונן כרת ועל שגגתן חטאת\u0004 — \u0003היחיד מביא כשבה\u0004 או \u0003שעירה, והנשיא\u0004 מביא \u0003שעיר\u0004 דווקא, \u0003ומשיח ובית דין\u0004 שטעו בהוראתם בזה \u0003מביאין פר. ובעבודה זרה\u0004 — \u0003היחיד והנשיא והמשיח\u0004 ששגגו בו \u0003מביאין שעירה, ובית דין\u0004 מביאים \u0003פר ושעיר, פר לעולה ושעיר לחטאת.\u0004","\u0003אשם תלוי\u0004 — \u0003היחיד והנשיא חייבין\u0004 בו, \u0003ומשיח ובית דין פטורין\u0004 ממנו. \u0003אשם ודאי\u0004 — \u0003היחיד והנשיא והמשיח חייבין, ובית דין פטורין.\u0004","וקרבן עולה ויורד \u0003על שמיעת הקול, ועל בטוי שפתים, ועל טומאת מקדש וקדשיו\u0004 — \u0003בית דין פטורין, והיחיד והנשיא והמשיח חייבין, אלא שאין כהן גדול משיח חייב על טומאת מקדש וקדשיו,\u0004 אלו \u0003דברי ר' שמעון. ומה הן מביאין? קרבן עולה ויורד\u0004 לפי רכושם כמבואר בתורה. \u0003ר' אליעזר אומר: הנשיא מביא שעיר.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון היה נותן כלל: כל שהיחיד באשם תלוי\u0004 — אף \u0003הנשיא כיוצא בו, משיח ובית דין פטורין. וכל שהוא באשם ודאי\u0004 — \u0003נשיא ומשיח כיוצא בהן, ובית דין פטורין.\u0004","\u0003שמיעת הקול, ובטוי שפתים, וטומאת מקדש וקדשיו\u0004 — \u0003בית דין פטורין, נשיא ומשיח חייבין, אלא שאין הנשיא חייב בשמיעת הקול\u0004 משום שאינו מעיד, \u0003ולא משיח בטומאת מקדש וקדשיו.\u0004 ובכלל, \u0003כל שהוא בעולה ויורד\u0004 — \u0003נשיא כיוצא בו, משיח ובית דין פטורין.\u0004","ותוהים: \u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 \u0003אמרת: שאין משיח חייב בטומאת מקדש וקדשיו,\u0004 ונדייק מכאן: \u0003בטומאת מקדש וקדשיו הוא\u0004 ש\u0003פטור, אבל בשמיעת הקול ובטוי שפתים\u0004 — \u0003חייב. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של ברייתא זו ש\u0003כל שהוא בעולה ויורד\u0004 — \u0003נשיא כיוצא בו, משיח ובית דין פטורין, קתני\u0004 \u0005[שנה]:\u0006 \u0003משיח ובית דין פטורין, מה בית דין פטורין מכולהון\u0004 \u0005[מכולן]\u0006 מכל שלושה האלה, \u0003אף משיח פטור מכולהון\u0004 \u0005[מכולן],\u0006 משמע שאינו חייב באף אחת מהן,"],["ואם כן, \u0003קשיין אהדדי\u0004 \u0005[קשות\u0006 הן \u0005זו על זו]\u0006 שתי הפסקאות!","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 שכן יש להבחין ביניהן, \u0003כאן\u0004 שחייב — המדובר בהבאה \u0003בדלות, כאן\u0004 — \u0003בדלי דלות, ור' שמעון סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' עקיבא בחדא\u0004 \u0005[ב\u0006הלכה \u0005אחת]\u0006 \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחת],\u0006 ובאופן זה: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' עקיבא בדלי דלות\u0004 שהכהן משיח \u0003פטור\u0004 מלהביא קרבן מנחה זה, \u0003ופליג עליה\u0004 \u0005[וחולק עליו]\u0006 \u0003בדלות\u0004 שאינו סבור כר' עקיבא שהכהן המשיח פטור לגמרי מקרבן עולה ויורד. שנינו במשנה שר' שמעון אומר: \u0003אלא שאין כהן גדול חייב\u0004 על טומאת מקדש וקדשיו. ועל כך \u0003אמר חזקיה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון? דכתיב\u0004 \u0005[שנאמר]\u0006 במי שנטמא ונכנס למקדש: \"ואיש אשר יטמא ולא יתחטא \u0003ונכרתה הנפש ההיא מתוך הקהל\u0004 כי את מקדש ה' טמא מי נדה לא זרק עליו טמא הוא\" (במדבר יט, כ), ולמדנו מכאן שדין זה הוא דווקא ב\u0003מי שקרבנו שוה לקהל, יצא\u0004 מכלל \u0003זה\u0004 הכהן הגדול \u0003שאין קרבנו שוה לקהל,\u0004 שהרי הוא מביא פר לעצמו על שגגתו. ומקשים על כך: \u0003אם כן, נשיא נמי\u0004 \u0005[גם כן]\u0006 הלוא \u0003אין קרבנו שוה לקהל\u0004 שהוא מביא שעיר! ומשיבים: מכל מקום \u0003שוה\u0004 הנשיא לקהל \u0003בכפרה\u0004 של \u0003יום הכיפורים,\u0004 שמתכפר עם כל הקהל. ועוד מקשים על חזקיה: \u0003אם כן\u0004 אתה אומר, \u0003כהנים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא שוו\u0004 \u0005[שוים]\u0006 \u0003לקהל בכפרה\u0004 של \u0003יום הכיפורים!\u0004 שהם מתכפרים לעצמם בפרו של הכהן הגדול, ויהיו פטורים מלהביא קרבן על טומאת מקדש וקדשיו! ומשיבים: \u0003כהנים שוו\u0004 \u0005[שוים]\u0006 \u0003לקהל בשאר מצו‍ת\u0004 של ה\u0003שנה כולה.\u0004","","","ומקשים: \u0003משיח נמי\u0004 \u0005[גם כן]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שוה בשאר מצו‍ת\u0004 של ה\u0003שנה! אלא אמר רבא, אימא הכי\u0004 \u0005[אמור כך]:\u0006 \u0003מי שחטאתו שוה ליחידים, ומאי ניהו\u0004 \u0005[ומהו]\u0006 \u0003קהל.\u0004 שקהל שחטאו בשגגה בלי הוראת בית דין, נידונים כיחידים, ואילו הכהן הגדול אין חטאתו שוה ליחידים, שהרי הוא מביא קרבן על חטאו רק כשעבר על הוראתו. שנינו במשנה ש\u0003ר' אליעזר אומר: הנשיא מביא שעיר וכו'\u0004 ולא קרבן עולה ויורד. ומסבירים את שיטת ר' אליעזר. \u0003אמר ר' יוחנן: לא אמר ר' אליעזר\u0004 את שיטתו זו \u0003אלא בטומאת מקדש וקדשיו,\u0004 \u0003הואיל ונאמר כרת בו\u0004 באיסור זה \u0003כב\u0004 כל דבר שיש בו חטאת \u0003קבועה.\u0004 והואיל ונשיא מביא על חטא שיש בו כרת שעיר, כמו כן יביא גם בטומאת מקדש וקדשיו שעיר, אבל שאר עבירות שהן בקרבן עולה ויורד ואין עליהן כרת, מביא הנשיא קרבן עולה ויורד ולא שעיר.","","\u0003אמר רב פפא: הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003ר' אליעזר על כולהון קאמר\u0004 \u0005[כולן\u0006 כל העבירות השנויות במשנה \u0005אמר],\u0006 שהנשיא מביא שעיר במקום קרבן עולה ויורד, \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003שעיר נשיא ופר משיח במקום יחיד לחטאת קאי\u0004 \u0005[עומד\u0006 הוא\u0005],\u0006 ואם סבור הוא שבקרבן עולה ויורד מביא הנשיא את קרבן החטאת המיוחד לו — אף בכהן גדול צריך לומר כן, ולכן \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]:\u0006 \u0003משיח מביא פר בשמיעת קול ובטוי שפתים, אלא מ\u0004מה ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 ר' אליעזר \u0003משיח, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שעל \u0003טומאת מקדש וקדשיו קאי\u0004 \u0005[עומד,\u0006 מתייחס הוא\u0005],\u0006 ש\u0003משיח פטור\u0004 ממנה, וכדברי ר' שמעון, ועל חטא זה בלבד מביא הנשיא שעיר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן לרב פפא: ממאי\u0004 \u0005[ממה]\u0006 אתה מוכיח זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ר' אליעזר אכולהון קאי\u0004 \u0005[על כולם\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 \u0003ובמשיח סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' עקיבא,\u0004 ש\u0003אמר: משיח פטור בכולן\u0004 בכל קרבן עולה ויורד! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ור' עקיבא מי פטר ליה\u0004 \u0005[האם\u0006 הוא \u0005פוטר אותו]\u0006 \u0003מפר?\u0004 שמה שאמר ר' עקיבא אינו אלא לפוטרו מקרבן עולה ויורד, אבל הוא מחייב את הכהן הגדול להביא את קרבנו המיוחד, פר העלם דבר. \u0003ותו לא מידי\u0004 \u0005[ושוב אין\u0006 לדון \u0005בזה].\u0006 \u0003אמר ר' יוחנן: מודה ר' אליעזר שאין\u0004 הנשיא \u0003מביא אשם\u0004 תלוי על טומאת מקדש וקדשיו. \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב ששת: אשם תלוי בא על טומאת מקדש וקדשיו. אמר ליה\u0004 \u0005[לו]:\u0006 אותו חכם ש\u0003אמר לך\u0004 משנה זו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 אמרה לך? שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: הואיל ונאמר בו\u0004 בטומאת מקדש \u0003כרת כבקבועה מייתי\u0004 \u0005[מביא]\u0006 \u0003נשיא שעיר עליה.\u0004 וכיון שנדון כקבועה, אף מביא אשם תלוי. ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: מודה ר' אליעזר שאין מביא אשם תלוי!\u0004 ומשיבים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר מדברי ר' יוחנן.","","","","\u0003כהן משיח שחטא\u0004 לאחר שהורה לעצמו בטעות \u0003ואחר כך עבר\u0004 (פסק) \u0003ממשיחותו\u0004 כגון שנפל בו מום ונפסל, לפני שהביא את חטאתו, \u0003וכן נשיא שחטא ואחר כך עבר מגדולתו\u0004 (מנשיאותו) לפני שהביא את קרבנו — \u0003כהן משיח מביא פר\u0004 למרות שעבר ממשיחותו, \u0003והנשיא מביא שעיר\u0004 כמו שהיה בזמן היותו נשיא. אבל \u0003משיח שעבר ממשיחותו ואחר כך חטא, וכן הנשיא שעבר מגדולתו ואחר כך חטא\u0004 — \u0003כהן משיח מביא פר\u0004 כמו שהיה חייב מתחילה, \u0003והנשיא\u0004 דינו \u0003כהדיוט.\u0004","על לשון המשנה תוהים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003יש לומר:\u0004 אם \u0003עבר ממשיחותו\u0004"],["\u0003ואחר כך חטא מביא פר, חטא ואחר כך עבר ממשיחותו\u0004 \u0003צריכא למימר\u0004 \u0005[\u0006וכי \u0005צריך לומר]\u0006 דבר זה? מובן מאליו שיצטרך להביא פר! ומשיבים: \u0003משום דקתני גבי\u0004 \u0005[ששנה אצל\u0006 בענין\u0005]\u0006 \u0003נשיא, דכי\u0004 \u0005[שכאשר]\u0006 \u0003עבר מנשיאותו ואחר כך חטא, כהדיוט מייתי\u0004 \u0005[מביא],\u0006 \u0003אהכי תני\u0004 \u0005[משום כך שנה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003משיח: חטא ואחר כך עבר מביא פר.\u0004","על האמור במשנה שמשיח שעבר ואחר כך חטא שמביא פר שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בכהן גדול \u0003\"והקריב על חטאתו\u0004 אשר חטא\" (ויקרא ד, ג), \u0003מלמד שמביא\u0004 פר לקרבן על \u0003חטאתו\u0004 גם \u0003משעבר\u0004 מכהונתו, ובא לימוד זה,","\u0003ש\u0004כן \u0003יכול,\u0004 ניתן היה לומר \u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה נשיא שמביא בשגגת מעשה\u0004 — \u0003אין מביא חטאתו\u0004 שעיר \u0003משעבר\u0004 מגדולתו, \u0003משיח שאין מביא בשגגת מעשה אלא על העלם דבר עם שגגת מעשה\u0004 — \u0003לא כל שכן\u0004 שלא יביא פר לחטאתו לאחר שעבר מכהונתו זו! \u0003תלמוד לומר: \"והקריב על חטאתו\u0004 אשר חטא\", \u0003מלמד שמביא על חטאתו משעבר.\u0004","ושואלים: \u0003ונייתי נמי\u0004 \u0005[ושיביא גם כן]\u0006 \u0003נשיא\u0004 שעבר שעיר לחטאת \u0003מקל וחומר\u0004 זה: \u0003ומה משיח שאין מביא בשגגת מעשה\u0004 — \u0003מביא חטאת משעבר, נשיא שמביא חטאת בשגגת מעשה\u0004 — \u0003אינו דין שמביא חטאתו משעבר! תלמוד לומר: \"אשר נשיא יחטא\"\u0004 (ויקרא ד, כב), לומר \u0003כשהוא נשיא\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003כשהוא הדיוט\u0004 — \u0003לא.\u0004","\u0003חטאו\u0004 נשיא או כהן משיח \u0003עד שלא\u0004 (בטרם) \u0003נתמנו, ואחר כך נתמנו\u0004 — \u0003הרי אלו\u0004 דינם \u0003כהדיוטות\u0004 ומביאים קרבן כיחידים. \u0003ר' שמעון אומר: אם נודע להם\u0004 שחטאו \u0003עד שלא נתמנו\u0004 — הרי אלו \u0003חייבים\u0004 בקרבן כיחידים, \u0003ו\u0004אולם אם נודע להם \u0003משנתמנו\u0004 — \u0003פטורים\u0004 לגמרי.","ומבארים: \u0003איזהו נשיא? זה מלך, שנאמר:\u0004 \"אשר נשיא יחטא ועשה אחת \u0003מכל מצו‍ת ה' אלהיו\u0004 אשר לא תעשינה בשגגה ואשם\" (ויקרא ד, כב), לומר: מי \u0003שאין על גביו אלא ה' אלהיו\u0004 ולא שררה אחרת, ואין זה אלא מלך.","שנינו במשנה: חטאו עד שלא נתמנו ואחר כך נתמנו — הרי אלו כהדיוטות. ועל כך שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"אם הכהן המשיח יחטא\"\u0004 (ויקרא ד, ג) — \u0003פרט לקודמות,\u0004 לעבירות שעבר בשגגה לפני שנעשה כהן משיח,","\u0003שיכול, והלא דין\u0004 (קל וחומר) \u0003הוא: ומה נשיא שמביא בשגגת מעשה\u0004 — \u0003אין מביא על הקודמות, משיח שאין מביא אלא על העלם דבר עם שגגת מעשה\u0004 — \u0003אינו דין שלא יביא על הקודמות!\u0004","ודוחים: \u0003לא, אם אמרת בנשיא שכן אין מביא חטאתו\u0004 (שעיר) \u0003משעבר\u0004 מנשיאותו, אלא מביא חטאת כהדיוט, \u0003תאמר במשיח שמביא\u0004 פר עבור \u0003חטאתו\u0004 גם \u0003משעבר, הואיל ומביא חטאתו משעבר יביא\u0004 גם \u0003על הקודמות\u0004 על מה שחטא לפני היותו כהן משיח יביא פר לחטאת? \u0003תלמוד לומר: \"המשיח יחטא\"\u0004 (יקרא ד, ג), לומר: אם \u0003חטא כשהוא משיח\u0004 — \u0003מביא\u0004 קרבן זה, \u0003כשהוא הדיוט\u0004 — \u0003אינו מביא.\u0004","\u0003ותניא נמי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005גם כן]\u0006 ל\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003נשיא כהאי גוונא\u0004 \u0005[כגון זה]:\u0006 \u0003\"אשר נשיא יחטא\"\u0004 (ויקרא ד כב) — \u0003פרט לקודמות,\u0004","\u0003והלא דין הוא: ומה משיח שמביא\u0004 על \u0003חטאתו משעבר\u0004 — \u0003אינו מביא על הקודמות, נשיא שאין מביא חטאתו משעבר\u0004 — \u0003אינו דין שלא יביא על הקודמות?\u0004 ואם כן אין צריך ללימוד זה!","ואולם יש לדחות: \u0003מה למשיח שכן אין מביא בשגגת מעשה\u0004 לבד, אלא עם הוראת היתר, \u0003תאמר בנשיא שמביא בשגגת מעשה? הואיל ומביא בשגגת מעשה יביא על הקודמות? תלמוד לומר: \"אשר נשיא יחטא\"\u0004 — \u0003שחטא והרי הוא\u0004 באותה עת \u0003נשיא, ולא שחטא ועודהו הדיוט.\u0004","ועוד בענין נשיא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אשר נשיא יחטא\", יכול גזרה\u0004 היא שהנשיא מתמיד לחטוא? \u0003תלמוד לומר: \"אם הכהן המשיח יחטא\"\u0004 (ויקרא ד ג), \u0003מה להלן\u0004 כוונת הכתוב היא \u0003לכשיחטא, אף כאן\u0004 כוונת הכתוב היא \u0003לכשיחטא.\u0004 ומבררים את הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003יכול גזרה.\u0004 ותוהים: \u0003גזרה, מהיכא תיתי\u0004 \u0005[מהיכן תבוא]?\u0006 מהיכן יעלה על דעתנו שתהיה גזירה מסוג כזה שיחטא הנשיא?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה \u0003אין\u0004 \u0005[כן],\u0006 יש מקום לסברה זו, שכן \u0003אשכחן\u0004 \u0005[אנו מוצאים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כי תבואו אל ארץ כנען אשר אני נותן לכם לאחוזה \u0003ונתתי נגע צרעת בבית ארץ אחזתכם\"\u0004 (ויקרא יד, לד), הרי זו \u0003בשורה\u0004 והודעה מראש \u0003היא להם\u0004 לבני ישראל \u0003שנגעים באים עליהם\u0004 לכשיהיו בארץ ישראל, \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 הפסוק הזה בא לומר שנגעים מטמאים רק אם הם באים מידי שמים, והרי זה בא ללמד מיעוט: \u0003פרט לנגעי אונסין\u0004 שבאו מחמת סיבה אחרת. ולענייננו, \u0003לאו\u0004 \u0005[וכי לא]\u0006 \u0003אמר ר' יהודה\u0004 שדבר כמו צרעת הוא \u0003בשורה? הכא נמי אימא\u0004 \u0005[כאן\u0006 אצל נשיא \u0005גם כן אמור]\u0006 \u0003גזרה היא\u0004 שיחטא! \u0003הלכך כתיב\u0004 \u0005[על כן נאמר]:\u0006 \u0003\"אם\u0004 הכהן המשיח יחטא\", שאין חטאו ודאי.","ושואלים: לגופם של הדברים האמורים בברייתא זו, \u0003ולר' שמעון, נגעי אונסין מי לא מטמו\u0004 \u0005[האם אינם מטמאים]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"אדם כי יהיה\u0004 בעור בשרו שאת או ספחת . . .\" (ויקרא יג, ב) — \u0003מן הדבור ואילך\u0004 כלומר, מזמן שניתנה מצוה זו לישראל והלאה (\"כי יהיה\"), ואינו כולל נגעים שהיו קודם לכן. \u0003והלא דין\u0004 (לימוד) \u0003הוא: טמא בזב וטמא בנגעים, מה זב\u0004 אינו טמא אלא \u0003מן הדבור ואילך, אף נגעים מן הדבור ואילך?\u0004 ואין צריך לזה לימוד מיוחד!","ויש לדחות: \u0003לא, אם אמרת בזב שכן אין מטמא באונס,\u0004 שאם ראה זוב לאונסו אין זה מטמא, \u0003תאמר בנגעים שמטמאין באונס? תלמוד לומר: \"אדם כי יהיה\",\u0004 לומר \u0003מן הדבור ואילך.\u0004 על כל פנים אנו למדים מכאן שנגעים מטמאים באונס! \u0003רבא אמר:\u0004 הפסוק \"ונתתי נגע צרעת\" בא למעט \u0003פרט לנגעי רוחות\u0004 כלומר, שהנגע בא מחמת רוחות רעות ולא על ידי אדם. \u0003רב פפא אמר:\u0004 הפסוק בא למעט \u0003פרט לנגעי כשפים.\u0004","ועוד בענין נשיא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אשר נשיא יחטא\"\u0004 — \u0003פרט לחולה.\u0004 ותוהים: \u0003משום דהוה ליה\u0004 \u0005[שנהיה לו]\u0006 \u0003חולה,\u0004 הוא \u0003אידחי ליה מנשיאותיה\u0004 \u0005[נדחה לו מנשיאותו]?\u0006 \u0003אמר רב אבדימי בר חמא:\u0004 אין הכוונה לכל חולי אלא \u0003פרט לנשיא שנצטרע, שנאמר: \"וינגע ה' את המלך ויהי מצרע עד יום מתו וישב בבית החפשית ויותם בן המלך על הבית\u0004 שופט את עם הארץ\" (מלכים ב טו, ה). הרי שהוסר ממלכותו כאשר נצטרע. ומעירים בענין זה: \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאומר]\u0006 הכתוב \u0003\"בבית החפשית\", מכלל\u0004 \u0005[מכאן]\u0006 ש\u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003עבד הוה\u0004 \u0005[היה]\u0006 לפי שהיה משועבד לצרכי הציבור.","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבן גמליאל ור' יהושע הוו אזלי בספינתא\u0004 \u0005[היו הולכים בספינה\u0006 יחד\u0005],\u0006 \u0003בהדי\u0004 \u0005[עם]\u0006 \u0003רבן גמליאל הוה פיתא\u0004 \u0005[היה לחם]\u0006 מספיק לצורך הנסיעה, \u0003בהדי\u0004 \u0005[עם]\u0006 \u0003ר' יהושע הוה פיתא וסולתא\u0004 \u0005[היה לחם וסולת].\u0006 \u0003שלים פיתיה\u0004 \u0005[נגמרה פיתו]\u0006 של \u0003רבן גמליאל,\u0004 שהנסיעה נמשכה יותר ממה ששיער מראש. \u0003סמך אסולתיה\u0004 \u0005[על הסולת]\u0006 של \u0003ר' יהושע. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי הוה\u0004 \u0005[האם]\u0006 \u0003ידעת\u0004 מתחילה \u0003דהוה לן עכובא כולי האי, דאיתית סולתא\u0004 \u0005[שיהיה לנו עיכוב כל כך, שהבאת\u0006 אתך \u0005סולת]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כוכב אחד\u0004 יש, שאחת \u0003לשבעים שנה\u0004 הוא \u0003עולה\u0004 (מופיע) \u0003ומתעה את הספנים\u0004 בדרכם בים, וגורם לנסיעתם שתתארך, \u0003ואמרתי: שמא יעלה\u0004 כוכב זה בדרכנו \u0003ויתעה אותנו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003כל כך בידך\u0004 חכמה \u0003ואתה עולה בספינה\u0004 לצרכי פרנסתך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עד שאתה תמה עלי\u0004 שאתה מכיר אותי, \u0003תמה על שני תלמידים שיש לך ביבשה, ר' אלעזר חסמא ור' יוחנן בן גודגדא,\u0004 שהם חכמים עד \u0003שיודעין לשער כמה טפות יש בים, ואין להם פת לאכול ולא בגד ללבוש! נתן\u0004 רבן גמליאל \u0003דעתו\u0004 למנותם ו\u0003להושיבם בראש.\u0004","\u0003כשעלה\u0004 מהספינה, \u0003שלח להם\u0004 שליח להזמינם לצורך זה \u0003ולא באו, חזר ושלח ובאו. אמר להם:\u0004 אין אתם רוצים במינוי זה משום ש\u0003כמדומין אתם ששררה אני נותן לכם\u0004 על ידי מינוי זה?"],["\u0003עבדות אני נותן לכם\u0004 במינויי, \u0003שנאמר: \"וידברו אליו לאמר אם היום תהיה עבד לעם הזה\"\u0004 (מלכים א יב, ז).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אשר נשיא יחטא\"\u0004 (ויקרא ד, כב) — \u0003אמר רבן יוחנן בן זכאי:\u0004 לשון \"אשר\" רמז היא: \u0003אשרי הדור שהנשיא שלו מביא קרבן על שגגתו,\u0004 שמרגיש צורך להביא קרבן, \u0003אם נשיא שלו מביא קרבן צריך אתה לומר מהו הדיוט! ואם על שגגתו מביא\u0004 הנשיא \u0003קרבן,\u0004 כל שכן \u0003צריך אתה לומר מהו\u0004 עושה תשובה על \u0003זדונו!\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה: אלא מעתה,\u0004 לפי דרך דרש זו על המלה \"אשר\", מה זו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת אשר חטא מן הקדש ישלם\"\u0004 (ויקרא ה, טז), \u0003ובירבעם בן נבט דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"אשר חטא ואשר החטיא\"\u0004 (מלכים א יד, טו), האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תדרוש ש\u0003אשרי הדור הוא!\u0004 ומתרצים: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 \u0003דשני קרא בדבוריה\u0004 \u0005[ששנה הכתוב בדיבורו],\u0006 שהלשון במקרים דומים היא \"אם\", וכאן נאמר \"אשר\", מה שאין כן הכתובים האחרים שהמילה \"אשר\" היא כדרכה.","ובדרך מדרש זו על המלה \"אשר\" \u0003דרש רב נחמן בר רב חסדא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"יש הבל אשר נעשה על הארץ\u0004 אשר יש צדיקים אשר מגיע אליהם כמעשה הרשעים ויש רשעים שמגיע אליהם כמעשה הצדיקים\" (קהלת ח, יד)? \u0003אשריהם לצדיקים שמגיע אליהם\u0004 (קורה להם) \u0003כמעשה הרשעים של עולם הבא\u0004 שהם סובלים שם יסורים, וכמו כן מגיע לצדיקים \u0003בעולם הזה, אוי להם לרשעים שמגיע אליהם כמעשה\u0004 (כמו שנעשה) ל\u0003צדיקים של עולם הבא\u0004 שיש להם כל טוב, ולרשעים הוא מגיע \u0003בעולם הזה.\u0004","\u0003אמר רבא: אטו צדיקי אי אכלי תרי עולמי, מי סני להו\u0004 \u0005[וכי הצדיקים אם\u0006 היו \u0005אוכלים\u0006 ונהנים \u0005משני עולמות, האם היה מגונה להם]?\u0006 מדוע צריך אתה לומר שהצדיקים חייבים לסבול בעולם הזה? \u0003אלא אמר רבא\u0004 כך צריך לומר: \u0003אשריהם לצדיקים שמגיע אליהם כמעשה הרשעים של עולם הזה\u0004 (כלומר, כל טוב) \u0003בעולם הזה, אוי להם לרשעים שמגיע אליהם כמעשה הצדיקים של עולם הזה\u0004 (שהרבה מהם סובלים ומתיסרים) וקורה גם לרשעים \u0003בעולם הזה.\u0004","מסופר, \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003אוקימתון מסכתא פלן ומסכתא פלן\u0004 \u0005[העמדתם,\u0006 למדתם היטב \u0005מסכת פלונית ומסכת פלונית]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003איעתריתו פורתא\u0004 \u0005[\u0006האם \u0005אתם עשירים מעט]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003דזבנן קטינא דארעא\u0004 \u0005[שמכרנו חלקת אדמה\u0006 ופרנסתנו ממנה\u0005].\u0006 \u0003קרי עלייהו\u0004 \u0005[קרא עליהם]:\u0006 \u0003אשריהם לצדיקים שמגיע אליהם כמעשה הרשעים שבעולם הזה בעולם הזה.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כי ישרים דרכי ה' וצדקים ילכו בם ופשעים יכשלו בם\"\u0004 (הושע יד, י)? \u0003משל לשני בני אדם שצלו פסחיהם, אחד אכלו\u0004 את הפסח שלו \u0003לשום\u0004 (לשם) \u0003מצוה, ואחד אכלו\u0004 לתאוה \u0003לשום אכילה גסה, זה שאכלו לשום מצוה\u0004 — קוראים בו \u0003\"צדקים ילכו בם\", זה שאכלו לשום אכילה גסה\u0004 — \u0003\"ופשעים יכשלו בם\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש\u0004 לר' יוחנן: \u0003רשע קרית ליה\u0004 \u0005[אתה קורא לו]\u0006 לזה שאכל כך? \u0003נהי דלא עביד\u0004 \u0005[אם אמנם שלא עשה]\u0006 \u0003מצוה מן המובחר\u0004 כשאכל לשם אכילה גסה, קרבן \u0003פסח מי לא קאכיל\u0004 \u0005[האם לא אכל]?\u0006 ואם כן, כיצד אפשר לקרוא לו רשע! \u0003אלא\u0004 כך צריך להסביר: \u0003משל לשני בני אדם, זה אשתו ואחותו עמו בבית וזה אשתו ואחותו עמו בבית\u0004 בחשיכה, \u0003אחד נזדמנה לו אשתו\u0004 ובא עליה, \u0003ואחד נזדמנה לו אחותו\u0004 בטעות, \u0003זה שנזדמנה לו אשתו\u0004 — נאמר בו \u0003\"צדקים ילכו בם\", וזה שנזדמנה לו אחותו\u0004 — \u0003\"ופשעים יכשלו בם\".\u0004","ומקשים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 \u0003אנן קאמרינן חדא דרך\u0004 \u0005[אנו אומרים דרך אחת]\u0006 שבאותה דרך עצמה הולך גם הצדיק וגם הרשע, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003שני\u0004 \u0003דרכים\u0004 הם, שהרי שני האנשים אינם עושים אותו דבר! \u0003אלא משל\u0004 נכון לדבר הוא \u0003ללוט ושתי בנותיו, הן שנתכוונו לשם מצוה\u0004 בבואן אל אביהן שחשבו שחרב כל העולם ורק הם נשארו בו — \u0003\"צדקים ילכו בם\", הוא שנתכוון לשם עבירה\u0004 — \u0003\"ופשעים יכשלו בם\".\u0004","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003הוא נמי\u0004 \u0005[גם כן]\u0006 \u0003לשם מצוה הוא מכוין! אמר ר' יוחנן, כל הפסוק הזה\u0004 \"וישא לוט את עיניו וירא את כל ככר הירדן כי כולה משקה\" (בראשית יג, י), \u0003לשם עבירה נאמר:\u0004 נאמר","\u0003\"וישא לוט\"\u0004 מרמז למה שנאמר \u0003\"ותשא אשת אדניו את עיניה\u0004 אל יוסף ותאמר שכבה עמי\" (בראשית לט, ז), נאמר \u0003\"את עיניו\"\u0004 הוא רמז למה שנאמר \u0003\"ויאמר שמשון אותה קח לי כי היא ישרה בעיני\"\u0004 (שופטים יד, ג), \u0003\"וירא\"\u0004 שנאמר בלוט הוא כעין \u0003\"וירא אתה שכם בן חמור\u0004. . . וישכב אותה\" (בראשית לד,ב), \u0003\"את כל ככר הירדן\"\u0004 הוא רמז לכתוב \u0003\"כי בעד אשה זונה עד ככר לחם\"\u0004 (משלי ו, כו), מה שנאמר \u0003\"כי כלה משקה\"\u0004 מזכיר את \u0003\"אלכה אחרי מאהבי נתני לחמי ומימי צמרי ופשתי שמני ושקויי\"\u0004 (הושע ב, ז).","ותוהים: מדוע מאשימים את לוט במעשה עם שתי בנותיו \u0003והא מינס אניס\u0004 \u0005[והרי אנוס היה\u0006 לוט\u0005]\u0006 שהיה שיכור וישן! \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003משום\u0004 (בשם) \u0003ר' יוסי בר ר' חוני\u0004: נאמר (בראשית יט, לג) \"ולא ידע בשכבה ובקומה\", \u0003למה נקוד\u0004 בספר התורה \u0003על וי\"ו ש\u0004במילה \u0003\"בקומה\" של בכירה? לומר לך, שבשכבה לא ידע אבל בקומה ידע,\u0004 ואם כן לא היה לגמרי אנוס. ושואלים: \u0003ומאי הוה ליה למעבד\u0004 \u0005[ומה היה לו לעשות]?\u0006 \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה]!\u0006 ומשיבים: \u0003נפקא מינה דלפניא אחרינא לא איבעי ליה למישתי\u0004 \u0005[יוצא מזה שלערב אחר לא היה לו לשתות],\u0006 וכיון שחזר ושתה משמע שנתכוין לכך.","\u0003דרש רבה, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אח נפשע מקרית עז ומדינים כבריח ארמון\"\u0004 (משלי יח, יט)? \u0003\"אח נפשע מקרית עז\"\u0004 — \u0003זה לוט שפירש מאברהם, \"ומדינים כבריח ארמון\"\u0004 — \u0003שהטיל מדינים\u0004 (מריבות) \u0003בין ישראל לעמון, שנאמר: \"לא יבא עמוני ומואבי בקהל ה'\"\u0004 (דברים כג, ד).","ועוד בענין לוט \u0003דרש רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יצחק, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לתאוה יבקש נפרד בכל תושיה יתגלע\"\u0004 (משלי יח, א)? \u0003\"לתאוה יבקש נפרד\"\u0004 — \u0003זה לוט שנפרד מאברהם\u0004 משום תאוותו, \u0003\"בכל תושיה יתגלע\"\u0004 — \u0003שנתגלה קלונו בבתי כנסיות ובבתי מדרשות,\u0004 שבבתי כנסיות ובבתי מדרשות קוראים ולומדים את מה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עמוני ומואבי\u0004 שנולדו מלוט \u0003אסורין איסור עולם.\u0004","\u0003ואמר עולא\u0004 כעין אותם הדברים שמעשים דומים אינם שוים זה לזה בערכם: \u0003תמר זנתה\u0004 עם יהודה \u0003וזימרי זינה, תמר זנתה\u0004 — ו\u0003יצאו ממנה מלכים ונביאים, זימרי זינה\u0004 — ו\u0003נפלו\u0004 בגללו \u0003כמה רבבות מישראל. אמר רב נחמן בר יצחק: גדולה עבירה\u0004 שעושה אדם \u0003לשמה\u0004 לשם שמים \u0003ממצוה שלא לשמה, שנאמר: \"תברך מנשים יעל אשת חבר הקיני מנשים באהל תברך\"\u0004 (שופטים ה, כד), \u0003מאן נינהו\u0004 \u0005[מי הן]\u0006 \u0003\"נשים באהל\"?\u0004 אלו הן \u0003שרה, רבקה, רחל ולאה,\u0004 ויעל ברוכה מהן.","ושואלים: \u0003איני\u0004 \u0005[כך הוא]?\u0006 כך צריך לומר? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצו‍ת אפילו שלא לשמה, שמתוך שלא לשמה בא לשמה,\u0004 אם כן מצוה שלא לשמה גם היא דבר חשוב. ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 שעבירה לשמה היא שקולה \u0003כמצוה שלא לשמה.\u0004","ובענין יעל \u0003אמר ר' יוחנן: שבע בעילות בעל אותו רשע\u0004 (סיסרא) \u0003באותה שעה, שנאמר: \"בין רגליה כרע נפל שכב\u0004 בין רגליה כרע נפל באשר כרע שם נפל שדוד\" (שופטים ה,, כז), שכל פועל שנאמר שם רומז לבעילה. ומקשים: \u0003והא קא מיתהניא\u0004 \u0005[והרי היא נהנית]\u0006 \u0003מעבירה\u0004 מן העבירה הזו של הביאה, מודוע הכתוב משבחה? \u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי: אפילו טובתם של רשעים\u0004 כלומר, כאשר הרשעים עושים להם טובה \u0003רעה היא אצל צדיקים.\u0004","\u0003אמר רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצו‍ת אפילו שלא לשמה, שמתוך שלא לשמה בא לשמה,\u0004 כיצד? \u0003שבשכר ארבעים ושנים קרבנות שהקריב בלק הרשע,\u0004 כמסופר בבמדבר פרק כג שהוא הקריב אותם כדי לקלל את ישראל, כיון שבכל זאת הקריב קרבן לה', \u0003זכה ויצתה ממנו רות,\u0004 ש\u0003אמר ר' יוסי בר' חנינא: רות בת בנו של עגלון בן בנו של בלק מלך מואב\u0004 היתה.","ועוד בענין לוט ובנותיו \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מנין שאין הקדוש ברוך הוא מקפח\u0004 שכרו של כל מעשה טוב ו\u0003אפילו שכר שיחה נאה\u0004 כלומר, לשון נקיה ויפה? \u0003מהכא\u0004 \u0005[מכאן],\u0006 ש\u0003אילו\u0004 האחות ה\u0003בכירה דקרייה\u0004 \u0005[שקראה אותו]\u0006 את בנה \u0003מואב,\u0004 ורמזה בכך שהוא בא מן האב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רחמנא\u0004 \u0005[הקדוש ברוך הוא]\u0006 \u0003למשה: \"אל תצר את מואב ואל תתגר בם מלחמה\"\u0004 (דברים ב, ט), ומכאן נדייק: \u0003מלחמה\u0004"],["\u0003הוא\u0004 ש\u0003לא\u0004 עושים איתם, \u0003הא צעורי צערינהו\u0004 \u0005[הרי לצער\u0006 מותר \u0005לצער\u0006 אותם\u0005].\u0006 \u0003ואילו צעירה דקרייה\u0004 \u0005[שקראה אותו]\u0006 \u0003\"בן עמי\"\u0004 אלא שאמרה בלשון נקיה שהוא מן המשפחה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקב\"ה למשה: \u0003\"אל תצרם ואל תתגר בם\"\u0004 (דברים ב, יט), כלומר אסור להתגרות בהם \u0003כלל, אפילו צעורי\u0004 \u0005[לצער]\u0006 \u0003לא.\u0004","\u0003אמר ר' חייא בר אבין אמר ר' יהושע בן קרחה: לעולם יקדים אדם לדבר מצוה, שבשכר לילה אחת שקדמה בכירה לצעירה, זכתה וקדמתה ארבע דורות למלכות,\u0004 לפי שממואב יצאה רות המואביה שקדמה בכמה דורות לנעמה העמונית שנכנסה גם כן לתוך מלכות ישראל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \"ואם נפש אחת תחטא בשגגה \u0003מעם הארץ\"\u0004 (ויקרא ד, כז) — הרי זה לשון מיעוט — \u0003פרט למשיח, \"מעם הארץ\"\u0004 — \u0003פרט לנשיא, ו\u0004יש לשאול:","\u0003הלא כבר יצאו\u0004 במפורש בפסוקים הקודמים \u0003משיח לידון\u0004 ולהביא \u0003פר, נשיא לידון בשעיר,\u0004 ואם כן, לשם מה צריך מיעוט נוסף! ומשיבים: \u0003שיכול,\u0004 הייתי לומר כך: \u0003משיח על העלם דבר עם שגגת מעשה מביא פר, על שגגת מעשה לחודיה\u0004 \u0005[בלבד]\u0006 \u0003מביא כשבה ושעירה\u0004 כשאר אדם? \u0003תלמוד לומר: \"מעם הארץ\"\u0004 — לומר \u0003פרט למשיח,\u0004 שפטור לגמרי מקרבן. וכן \u0003\"מעם הארץ\"\u0004 — \u0003פרט לנשיא.\u0004","ומקשים: \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003משיח,\u0004 שהסברנו מדוע נצרך הכתוב \u0003אלא נשיא\u0004 הלוא \u0003בשגגת מעשה הוא דמייתי\u0004 \u0005[שמביא]!\u0006 ואם כן, מה בא למעט?","\u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שאכל\u0004 בשגגה \u0003כזית חלב כשהוא הדיוט, ונתמנה\u0004 למלכות \u0003ואחר כך נודע לו\u0004 שחטא, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003נייתי\u0004 \u0005[שיביא]\u0006 \u0003כשבה או שעירה\u0004 שהרי חטא כהדיוט, \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שיביא שעיר כנשיא. ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' שמעון דאזל בתר\u0004 \u0005[שהולך אחר]\u0006 ה\u0003ידיעה,\u0004 ולפי הזמן שנודע לו כך מביא את הקרבן, \u0003אלא לרבנן דאזלו בתר חטאה מאי איכא למימר\u0004 \u0005[ל\u0006דעת \u0005חכמים שהולכים אחר\u0006 זמן \u0005החטא מה יש לומר]?\u0006","\u0003אלא אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שאכל\u0004 בשגגה \u0003חצי כזית חלב כשהוא הדיוט, ונתמנה\u0004 לנשיאות \u0003והשלימו\u0004 לכזית שלם שחזר ואכל עוד חצי זית מזה, \u0003ואחר כך נודע לו\u0004 שהיה זה חלב, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003נצטרף\u0004 שיצטרפו שני חצאי הזיתים, \u0003ונייתי\u0004 \u0005[ויביא]\u0006 \u0003כשבה או שעירה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו].\u0006 הכתוב שאין הנשיא ככל אדם, וכיון שיש לו קרבן מיוחד אין חטאו מצטרף כהדיוט.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: נשיאות מהו שתפסיק\u0004 שלא יצטרפו שני חלקים של עבירה, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003כגון שאכל חצי כזית חלב כשהוא הדיוט, ונתמנה\u0004 לנשיאות ואחר כך \u0003ועבר\u0004 ממינויו, \u0003והשלימו\u0004 אכל עוד מחצית כזית באותו העלם, וצדדי השאלה: האם נאמר, \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 במקרה הקודם ש\u0003לא מצטרף, דאכליה פלגא\u0004 \u0005[שאכל אותו חצי]\u0006 \u0003כשהוא הדיוט ופלגא\u0004 \u0005[וחצי]\u0006 \u0003כשהוא נשיא, אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דאידי ואידי\u0004 \u0005[שזה וזה]\u0006 \u0003כשהוא הדיוט אכליה\u0004 \u0005[אכלו]\u0006 — \u0003מצטרף\u0004 והרי זה כאוכל שיעור שלם באותו מצב, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 שכיון שנתמנה לנשיאות נשתנה דינו בינתים. \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","ומציעים: \u0003תפשוט ליה מהא\u0004 \u0005[תפתור את\u0006 הבעיה \u0005הזו מזו]\u0006 ש\u0003אמר עולא אמר ר' יוחנן:\u0004 מי ש\u0003אכל חלב והפריש קרבן\u0004 על שגגתו \u0003והמיר\u0004 דתו, \u0003ו\u0004אחר כך \u0003חזר בו\u0004 מהמרתו, אף על פי כן \u0003הואיל ונדחה\u0004 מהקרבן הזה בהיותו מומר — \u0003ידחה\u0004 לגמרי. ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003מומר לאו בר אתויי\u0004 \u0005[לא בן הבאת]\u0006 \u0003קרבן הוא\u0004 מכל סוג, \u0003האי\u0004 \u0005[זה]\u0006 הנשיא \u0003בר אתויי\u0004 \u0005[בן הבאת]\u0006 \u0003קרבן הוא\u0004 אלא שהוא מביא קרבן אחר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' זירא מרב ששת: אכל ספק חלב כשהוא הדיוט, ונתמנה ונודע לו על ספקו, מהו?\u0004 ומעתה, \u0003אליבא דרבנן דאזלי בתר חטאה\u0004 \u0005[לדעת חכמים שהולכים אחר\u0006 זמן \u0005החטא]\u0006 \u0003לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, שבוודאי \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003אשם תלוי, אלא כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה היא \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' שמעון,\u0004 האם נאמר","\u0003מדאשתני\u0004 \u0005[מכיון שהשתנה\u0006 דינו\u0005]\u0006 \u0003ל\u0004גבי \u0003ודאי\u0004 שאם היה חייב ודאי חטאת ונודע לו אחר שהתמנה לנשיא משתנה דינו ופטור לגמרי, גם \u0003אשתני\u0004 \u0005[השתנה\u0006 דינו\u0005]\u0006 גם \u0003ל\u0004ענין \u0003ספק,\u0004 ויהיה פטור מאשם תלוי, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כי אשתני\u0004 \u0005[כאשר השתנה\u0006 דינו\u0005]\u0006 \u0003ל\u0004גבי \u0003ודאי, דאשתני\u0004 \u0005[שהשתנה]\u0006 \u0003קרבן דידיה\u0004 \u0005[שלו],\u0006 שהרי כנשיא חייב בשעיר \u0003אבל הכא דלא אשתני\u0004 \u0005[כאן שלא השתנה]\u0006 \u0003קרבן דידיה\u0004 \u0005[שלו]\u0006 \u0003אימא לייתי\u0004 \u0005[אמור שיביא]\u0006 \u0003אשם תלוי?\u0004 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"מעם הארץ\"\u0004 (ויקרא ד, כז) — הרי זה ממעט! \u0003פרט למשומד,\u0004 שאינו מביא קרבן חטאת,","\u0003ר' שמעון בר יוסי אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 ראיה אחרת יש לכך, שנאמר בסוף הפסוק \u0003\"אשר לא תעשינה בשגגה ואשם\"\u0004 (ויקרא ד, כז), לומר: \u0003השב בידיעתו\u0004 כלומר, כאשר נודע לו שחטא — חוזר מיד בתשובה, הוא האיש ש\u0003מביא קרבן על שגגתו,\u0004 אבל מי ש\u0003לא שב בידיעתו\u0004 שהוא משומד ואינו עושה תשובה על חטאיו, \u0003אינו מביא\u0004 כלל \u0003קרבן על שגגתו.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין חכמים ור' שמעון למעשה אם זו או זו הראיה? \u0003אמר רב המנונא:\u0004 ההבדל הוא לגבי מי שהיה \u0003משומד לאכול חלב,\u0004 שהוא אוכל חלב מתוך זדון, \u0003ומביא קרבן על הדם\u0004 שחטא בו בשגגה, בזה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003כיון\u0004 ש\u0003משומד לאכול חלב\u0004 — \u0003ל\u0004גבי \u0003דם נמי\u0004 \u0005[גם כן]\u0006 \u0003משומד הוי\u0004 \u0005[הוא],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003לדם מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003שב בידיעתו הוא,\u0004 שהרי אינו אוכל דם, ומשנודע לו הוא חוזר בתשובה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003משומד לאכול חלב לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003משומד לדם! אלא, הכא\u0004 \u0005[כאן]\u0006 \u0003באוכל נבלה לתאבון\u0004 כלומר, הוא שאוכל נבילה אוכל דבר איסור מרצון, לשם נוחיותו, \u0003ונתחלף לו\u0004 במקרה חלב \u0003בשומן ואכלו,\u0004 בזה \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה\u0006 חכמים \u0005סבור]:\u0006 \u0003כיון\u0004 ש\u0003לתאבון אכיל\u0004 \u0005[\u0006הוא \u0005אוכל]\u0006 \u0003במזיד\u0004 — \u0003משומד הוא, ומר סבר\u0004 \u0005[וחכם זה\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003כיון\u0004 ש\u0003אילו אשכח דהיתרא לא אכל דאיסורא\u0004 \u0005[היה מוצא היתר לא היה אוכל\u0006 של \u0005איסור]\u0006 שאינו אוכל בכוונה כדי לעבור אלא משום תאוותו, אם כן איש זה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משומד הוא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אכל חלב —\u0004 \u0003זהו משומד, ואיזהו משומד? אכל נבילות וטריפות, שקצים ורמשים, ושתה יין נסך. ר' יהודה אומר: אף הלובש כלאים.\u0004 ומבררים את ענין הברייתא: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אכל חלב זהו משומד, ואיזהו משומד? אוכל נבילות כו'.\u0004 ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 הרי יש פה שינוי דברים לא מובן!","\u0003אמר רבה בר בר חנה אמר ר' יוחנן, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אכל חלב לתאבון\u0004 — \u0003הרי זה משומד,\u0004 אם אכל \u0003להכעיס\u0004 — \u0003הרי זה מין\u0004 (כופר), \u0003ואיזהו משומד\u0004 ש\u0003בסתמו מין\u0004 שלפי מעשיו מסתבר שהוא מין? \u0003הוי אומר: אוכל נבילה וטריפה, שקצים ורמשים, ושתה יין נסך\u0004 שרואים שעובר גם על איסורים חמורים, ועל דברים שאין בהם תאוה, ובודאי מוכיח שהוא כופר בכל התורה כולה. \u0003ר' יוסי בר' יהודה אומר: אף הלובש כלאים.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 בין נבילה וכלאים! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי הלובש בגד שהוא \u0003כלאים\u0004 רק מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 מי שעובר על עבירה \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוי\u0004 \u0005[הרי הוא]\u0006 \u0003משומד,\u0004 מי שעובר על איסורים \u0003דרבנן\u0004 \u0005[של סופרים]\u0006 \u0003לא הוי\u0004 \u0005[איננו]\u0006 \u0003משומד. ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוסי, \u0005סבור]:\u0006 \u0003כלאים כיון דמפרסם אסוריה\u0004 \u0005[שמפורסם האיסור שלו]\u0006 והכל רואים שהוא עובר, \u0003אפילו בדרבנן\u0004 \u0005[\u0006בדבר האסור מדברי \u0005חכמים]\u0006 \u0003הוי\u0004 \u0005[הרי הוא]\u0006 \u0003משומד.\u0004","\u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כך: מי שאוכל איסור \u0003לתאבון\u0004 מפני תאוות ליבו או מפני שזה נוח לו — הריהו \u0003משומד,\u0004 מי שאוכל \u0003להכעיס\u0004 — הריהו \u0003מין. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: להכעיס נמי\u0004 \u0005[גם\u0006 כן\u0005]\u0006 \u0003משומד, אלא איזהו מין? כל העובד עבודה זרה. מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003אכל פרעוש אחד או יתוש אחד\u0004 — \u0003הרי זה משומד. והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003להכעיס הוא,\u0004 שוודאי אינו אוכל אותם לתיאבון, \u0003וקא קרי ליה\u0004 \u0005[והוא קורא לו]\u0006 \u0003משומד!\u0004 ומשיבים: כאן מדובר במי שאוכל פרעוש לתיאבון, ומה התיאבון שבדבר? \u0003התם דאמר\u0004 \u0005[שם ש\u0006הוא \u0005אומר]:\u0006 \u0003אטעום טעם דאיסורא\u0004 \u0005[של האיסור]\u0006 שהוא רוצה לטעום טעמו של דבר האסור, ולא משום כפירה, אלא משום תאוה לטעום טעם של דבר שאף פעם לא אכלו.","שנינו במשנה: \u0003ואיזהו נשיא? זה מלך כו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"נשיא\"\u0004 — \u0003יכול נשיא שבט כנחשון בן עמינדב? תלמוד לומר\u0004 בהמשך הפסוק: \u0003\"מכל\u0004 \u0003מצו‍ת ה' אלהיו\"\u0004 (ויקרא ד, כב), \u0003ולהלן\u0004 בדין מלך: \u0003הוא אומר \"למען ילמד ליראה את ה' אלהיו\"\u0004 (דברים יז, יט),"],["\u0003מה להלן\u0004 בספר דברים מדובר במלך \u0003שאין על גביו אלא ה' אלהיו, אף נשיא\u0004 הכתוב בספר ויקרא הוא מי \u0003שאין על גביו אלא ה' אלהיו.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבי מר' חייא: כגון אני\u0004 שאני נשיא בארץ ישראל \u0003מהו בשעיר,\u0004 האם דיני כנשיא או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי צרתך\u0004 (שותפך) \u0003בבבל\u0004 שהרי יש בבבל ראש הגולה שהוא גדול כמותך. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבי: \u0003מלכי ישראל ומלכי בית דוד, אלו מביאים\u0004 קרבן \u0003לעצמם\u0004 כמלכים, \u0003ואלו מביאים לעצמם,\u0004 משמע שאף שיש מלך כמותו גם הוא נחשב מלך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם לא כייפי אהדדי\u0004 \u0005[שם לא היו כפופים זה לזה],\u0006 \u0003הכא אנן כייפינן להו לדידהו\u0004 \u0005[כאן אנו כפופים להם]\u0006 משום שכוח שררתו של ראש הגולה גדול משל הנשיא.","\u0003רב ספרא מתני הכי\u0004 \u0005[היה שונה\u0006 את המעשה הזה \u0005כך],\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבי מר' חייא: כגון אני מהו בשעיר? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בגולה ראש הגולה יש לו \u0003\"שבט\"\u0004 (סמכות), \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003\"מחוקק\", ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"לא יסור שבט מיהודה\"\u0004 (בראשית מט, י) — \u0003זה ראש גולה שבבבל,\u0004 שיש שבט בידו, \u0003שרודה את ישראל במקל\u0004 מפני שיש לו כוח מטעם המלכות. \u0003\"ומחוקק מבין רגליו\"\u0004 (בראשית מט, י) — \u0003אלו\u0004 הנשיאים \u0003בני בניו של הלל שמלמדים תורה לישראל ברבים,\u0004 אבל אין להם כוח סמכות מטעם הממשלה.","\u0003ואיזהו\u0004 הכהן \u0003המשיח?\u0004 זה הכהן הגדול \u0003המשוח בשמן המשחה, לא\u0004 זה \u0003המרובה בבגדים\u0004 שלא היה שמן המשחה למשוח אותו, אף על פי שהוא מכהן בכהונה גדולה ולובש כל שמונה בגדי כהונה. \u0003אין בין כהן המשוח בשמן המשחה למרובה בגדים,\u0004 ההבדל להלכה \u0003אלא\u0004 לענין \u0003פר הבא על כל המצו‍ת,\u0004 שהכהן המשוח מביא על שגגתו פר וכהן גדול אחר אינו מביא.","\u0003ואין בין כהן\u0004 גדול ש\u0003משמש\u0004 בפועל \u0003לכהן שעבר\u0004 מאיזה סיבה \u0003אלא פר יום הכיפורים\u0004 שהכהן המשמש מביא משלו, \u0003ועשירית האיפה,\u0004 שהכהן המשמש מביא מנחה זו בכל יום. וזה שעבר אינו מביא.","אבל \u0003זה וזה שוים בעבודת יום הכיפורים\u0004 שהם יכולים לעשות את שאר העבודה של יום הכיפורים, \u0003ומצווים על הבתולה\u0004 שיש להם מצוות עשה לשאת רק נערה בתולה, \u0003ואסורים על האלמנה\u0004 ושניהם אסורים לשאת אלמנה, \u0003ואינם מטמאים בקרוביהם\u0004 שאסור להם להיטמא אפילו לקרובי המשפחה שלהם, \u0003ולא פורעים\u0004 מגדלים שערם, \u0003ולא פורמים\u0004 את בגדיהם בזמן שהם אבלים, \u0003ומחזירין הרוצח,\u0004 אם אחד מהם מת הרי הרוצח בעיר המקלט יכול לחזור לביתו בגלל מותו של הכהן הגדול.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמן המשחה שעשה משה במדבר,\u0004 כיצד עשו אותו? \u0003היו שולקים\u0004 (מבשלים) \u0003בו את העיקרים\u0004 את השורשים של הסמים המנויים שם, \u0003דברי ר' יהודה. ר' יוסי אומר: והלא\u0004 הכמות של השמן אפילו \u0003לסוך\u0004 בו \u0003את העקרים אינו סופק\u0004 (מספיק) לפי שהיה נבלע בהם, ואיך יכלו לבשל בו?! \u0003אלא\u0004 כך היו עושים: \u0003שורין את העקרים במים,\u0004 כדי שלא יבלע בהם השמן, והיה הבושם עולה מעט מעט \u0003ומציף עליו\u0004 על המים \u0003שמן, וקולט\u0004 השמן \u0003את הריח וקפחו\u0004 ואחר כך היה מוריד את השמן מלמעלה ומכאן נעשה שמן המשחה.","\u0003אמר לו ר' יהודה: וכי נס אחד נעשה בשמן המשחה? והלא תחלתו\u0004 היה רק \u0003שנים עשר לוגין, וממנו היה נמשח משכן וכליו אהרן ובניו כל שבעת ימי המלואים, וכולו קיים לעתיד לבוא, שנאמר: \"שמן משחת קדש יהיה זה לי לדורותיכם\"\u0004 (שמות ל, לא), ואם כן כיון שנעשו בו ניסים כאלה אין לתמוה שגם דרך עשייתו מתחילה היתה בדרך נס.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"ויקח משה את שמן המשחה וימשח את המשכן ואת כל אשר בו\"\u0004 (ויקרא ח, י) — \u0003ר' יהודה אומר: שמן המשחה שעשה משה במדבר, כמה נסים נעשו בו מתחלה ועד סוף, תחלתו לא היה אלא שנים עשר לוגין, ראה כמה יורה\u0004 (סיר) שבה מבשלים \u0003בולעת\u0004 ממה שמבשלים בה, \u0003וכמה עקרים\u0004 (השורשים) \u0003בולעים\u0004 בתוכם, \u0003וכמה האור\u0004 (האש) \u0003שורף, ובו\u0004 בשמן המשחה הזה \u0003נמשח משכן וכליו ואהרן ובניו כל שבעת ימי המלואים, ובו נמשחו כהנים גדולים ומלכים\u0004 במשך הדורות.","ואומרים עוד בענין שמן המשחה: \u0003ואפילו כהן גדול בן כהן גדול\u0004 בכל זאת היה \u0003טעון משיחה, ואין מושחים מלך בן מלך\u0004 משום שאינו צריך לכך. \u0003ואם תאמר: מפני מה משחו\u0004 בכל זאת \u0003את שלמה\u0004 המלך שהיה בן מלך? \u0003מפני מחלוקתו של אדוניה\u0004 שהיה אדוניה חולק עליו ומתנשא למלוך, \u0003ואת יואש\u0004 משחו \u0003מפני עתליה\u0004 שהיתה המושלת, \u0003ואת יהואחז\u0004 משחו \u0003מפני יהויקים, שהיה גדול ממנו שתי שנים,\u0004 ולכן היה צריך להדגיש שהוא המלך. \u0003ואותו שמן\u0004 עצמו \u0003קיים לעתיד לבוא, שנאמר: \"שמן משחת קדש יהיה זה לי לדורותיכם\", \"זה\"\u0004 — \u0003בגימטריא שנים עשר לוגין הוו\u0004 \u0005[היו]\u0006 וכך נשאר תמיד באותו שיעור למרות השימוש בו.","ומעתה מבארים כמה דברים בברייתא זו. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ואפילו כהן גדול בן כהן גדול טעון משיחה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והכהן המשיח תחתיו מבניו\"\u0004 (ויקרא ו, טו), \u0003נימא קרא\u0004 \u0005[שיאמר הפסוק]\u0006 רק \u0003\"והכהן מתחתיו מבניו\", מאי\u0004 \u0005[מה]\u0006 הצורך לומר \u0003המשיח? קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם אם הוא \u0003מבניו\u0004 של \u0003כהן גדול, אי הוי\u0004 \u0005[אם הוא]\u0006 \u0003משיח\u0004 כלומר, משוח בשמן — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003כהן גדול, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא הוי\u0004 \u0005[איננו]\u0006 \u0003כהן גדול.\u0004","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ואין מושחין מלך בן מלך.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר רב אחא בר יעקב, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"למען יאריך ימים על ממלכתו\u0004 הוא ובניו בקרב ישראל\" (דברים יז, כ), שכיון שנזכרו כאן בניו, הרי זה ללמד כי \u0003ירושה היא לכם\u0004 המלוכה. ושואלים: \u0003ומנלן דכי איכא\u0004 \u0005[ומנין לנו שכאשר יש]\u0006 \u0003מחלוקת בעי\u0004 \u0005[צריך]\u0006 \u0003משיחה, ולאו כל דבעי מלכא מורית מלכותא לבניה\u0004 \u0005[ולא\u0006 את \u0005כל מי שרוצה המלך מוריש\u0006 את \u0005המלכות לבניו]\u0006 ודי בכך, \u0003אמר רב פפא, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"הוא ובניו בקרב ישראל\"\u0004 (דברים יז, כ), \u0003בזמן ששלום בישראל קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"הוא ובניו\", ואפילו בלא משיחה,\u0004 ולא כשיש מחלוקת.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אף יהוא בן נמשי\u0004 מלך ישראל \u0003לא נמשח אלא מפני מחלוקתו של יורם.\u0004 ואומרים: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו]\u0006 הלכה זו שצריך משיחה \u0003משום\u0004 ש\u0003ראשון הוא,\u0004 שהרי יהוא לא היה בן מלך! ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 צריך \u0005לשנותה]:\u0006 \u0003מלכי בית דוד משוחין\u0004 בשמן המשחה, \u0003מלכי ישראל אין משוחין.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר רבא, אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"קום משחהו כי זה\u0004 הוא\" (שמואל א טז, יז), ללמדנו: \u0003זה\u0004 דוד המלך \u0003טעון משיחה ואין\u0004 מלך \u0003אחר\u0004 מבית אחר \u0003טעון משיחה.\u0004","ועל דין זה \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אף יהוא בן נמשי\u0004 שהיה מלך ישראל \u0003לא נמשח אלא מפני מחלוקתו של יורם.\u0004 ושואלים: \u0003ומשום מחלוקתו של יורם בן אחאב נמעול בשמן\u0004 ונשתמש בו שלא לצורך? שהרי אמרנו שמלכי ישראל אינם נמשחים! ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב פפא\u0004 בענין אחר: שמשחו אותו \u0003באפרסמא דכיא\u0004 \u0005[באפרסמון זך]\u0006 ולא בשמן המשחה, \u0003הכי נמי באפרסמא דכיא\u0004 \u0005[כאן גם כן באפרסמון זך]\u0006 ולא בשמן המשחה.","אמרנו שמשחו \u0003את יהואחז מפני יהויקים, שהיה גדול ממנו שתי שנים.\u0004 ושואלים: \u0003ומי קשיש מיניה\u0004 \u0005[והאם גדול\u0006 היה \u0005ממנו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ובני יאשיהו הבכור יוחנן השני יהויקים השלישי צדקיהו הרביעי שלום\"\u0004 (דברי הימים א ג, טו), \u0003ואמר ר' יוחנן: הוא שלום הוא צדקיהו\u0004 שהוא שני שמות של איש אחד, וכן \u0003הוא יוחנן\u0004 הנזכר כאן \u0003הוא יהואחז\u0004 הנזכר בספר מלכים, נמצא שיהואחז היה הבן הגדול, ואם כן מפני מה היו צריכים למשוח אותו?! ומשיבים: \u0003לעולם\u0004 יש לומר ש\u0003יהויקים קשיש\u0004 \u0005[מבוגר],\u0006 יותר מיהואחז, \u0003ומאי\u0004 \u0005[ומהו]\u0006 מה שכתוב במקרא ה\u0003\"בכור\u0004 יוחנן\"? כוונתו \u0003בכור למלכות.\u0004","ושואלים: \u0003ומי מלכי זוטרי מקמי קשישי\u0004 \u0005[והאם מולכים\u0006 הבנים \u0005הקטנים לפני הגדולים]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואת הממלכה נתן ליהורם כי הוא הבכור\"\u0004 (דברי הימים ב כא, ג)! ומשיבים: \u0003יהורם ממלא מקום אבותיו הוה\u0004 \u0005[היה]\u0006 והיה ראוי להיות מלך, וכיון שבכור היה, קיבל את המלוכה, \u0003יהויקים לאו\u0004 \u0005[לא]\u0006 \u0003ממלא מקום אבותיו הוה\u0004 \u0005[היה]\u0006 ולא היה ראוי להיות מלך, ולכן הומלך אחיו תחילה.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הוא שלום הוא צדקיהו, הוא יוחנן הוא יהואחז.\u0004 ושואלים: \u0003והא חד חד קא חשיב\u0004 \u0005[והרי אחד אחד הוא מונה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"השלישי... הרביעי\"\u0004 (דברי הימים א ג, טו) משמע ששנים הם! ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלישי\"\u0004 כוונתו \u0003שלישי לבנים, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"רביעי\"\u0004 — \u0003רביעי למלכות,\u0004 כיצד? \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003מלך יהואחז, ולבסוף\u0004 ואחר כך \u0003יהויקים, ולבסוף יכניה ולבסוף צדקיהו,\u0004 והיה איפוא הרביעי למלכות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הוא שלום הוא צדקיהו, ולמה נקרא שמו שלום? שהיה משולם במעשיו\u0004 הטובים. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 נתכנה \u0003\"שלום\"\u0004 — \u0003ששלמה\u0004 (נגמרה) \u0003מלכות בית דוד בימיו, ומה שמו\u0004 האמיתי? \u0003מתניה שמו, שנאמר: \"וימלך מלך בבל את מתניה דודו תחתיו ויסב את שמו צדקיהו\"\u0004 (מלכים ב כד, יז), ומדוע קרא לו בשם זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יה יצדיק עליך את הדין אם תמרוד בי, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וגם במלך נבוכדנצר מרד אשר השביעו באלהים\"\u0004 (דברי הימים ב לו, יג)."],["ושואלים על מה שנאמר שמשחו את יהואחז: \u0003ומי הוה\u0004 \u0005[והאם היה]\u0006 בימי יהואחז \u0003שמן המשחה? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003משנגנז ארון\u0004 הברית \u0003נגנז\u0004 עמו גם \u0003שמן המשחה, וצנצנת המן, ומקלו של אהרן\u0004 ובו \u0003שקדיה ופרחיה, וארגז ששלחו פלשתים דורון לישראל, שנאמר\u0004 בו: \u0003\"ואת כלי הזהב אשר השבתם לו אשם תשימו בארגז מצדו ושלחתם אתו והלך\"\u0004 (שמואל א ו, ח),","\u0003ומי גנזו\u0004 את הארון? \u0003יאשיהו מלך יהודה גנזו,\u0004 כיון \u0003שראה\u0004 מה \u0003שכתוב בתורה\u0004 בפרשת התוכחה: \u0003\"יולך ה' אתך ואת מלכך\u0004 אשר תקים עליך אל גוי אשר לא ידעת\" (דברים כח, לו), \u0003צוה וגנזום, שנאמר: \"ויאמר ללוים המבינים לכל ישראל הקדושים לה' תנו את ארון הקדש בבית אשר בנה שלמה בן דוד מלך ישראל אין לכם משא בכתף עתה עבדו את ה' אלהיכם ואת עמו ישראל\"\u0004 (דברי הימים ב לה, ג),","\u0003ואמר ר' אלעזר: אתיא\u0004 \u0005[באה\u0006 נלמדת\u0005]\u0006 בגזירה שווה המלים \u0003\"שם\" \"שם\",\u0004 כתובה המלה \"שמה\" בארון (שמות כט, מג) וכן נאמר \"שמה\" בצנצנת המן (שמות טז, לג), וכמו כן \u0003אתיא\u0004 \u0005[באה]\u0006 \u0003\"משמרת\" \"משמרת\"\u0004 בגזירה שווה, שכתובה בצנצנת המן (שמות טז, לג) וכתובה במקלו של אהרן (במדבר יז כה-כו), וכן \u0003אתיא\u0004 \u0005[באה]\u0006 גזירה שווה של \u0003\"דורות\" \"דורות\"\u0004 שנאמרה בצנצנת המן, וכן נאמרה בשמן המשחה (שמות ל, לא) שכל אותם הדברים שנאמרה בהם גזירה שווה מצויים במקום אחד, ליד הארון, ולכן נגנזו יחד עם הארון! \u0003אמר רב פפא:\u0004 לא בשמן המשחה משחו את יהואחז אלא \u0003באפרסמא דכיא\u0004 \u0005[באפרסמון זך].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד מושחין את המלכים?\u0004 המשיחה היא \u0003כמין נזר\u0004 (כתר) סביב הראש, \u0003ו\u0004כיצד מושחים \u0003את הכהנים? כמין כי.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כמין כי\"? אמר רב מנשיא בר גדא: כמין\u0004 האות \u0003כף יוני.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003בתחלה מוצקין שמן על ראשו\u0004 של הכהן, \u0003ואחר כך נותנין לו שמן בין ריסי עיניו, ותניא אחריתי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בתחלה נותנין לו שמן בין ריסי עיניו, ואחר כך מוצקים לו שמן על ראשו!\u0004 ומעירים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003משיחה\u0004 בין עיניו \u0003עדיפא\u0004 \u0005[עדיפה]\u0006 מיציקה וקודמת לה, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003יציקה עדיפא\u0004 \u0005[עדיפה].\u0006 ממשיחה וקודמת לה.","\u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 \u0003יציקה עדיפא\u0004 \u0005[עדיפה]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצק משמן המשחה על ראש אהרן וימשח אתו לקדשו\"\u0004 (ויקרא ח, יב), משמע שהיציקה היא תחילה ואחריה משיחה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003משיחה עדיפא\u0004 \u0005[עדיפה]\u0006 מיציקה וקודמת לה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003שכן אתה מוצא\u0004 אף \u0003אצל כלי שרת.\u0004 שנמשחו ולא יצקו עליהם שמן משמן המשחה. ומקשים על דעה זו: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויצק\", ובסוף \"וימשח\"!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 זו היא כוונת הכתוב: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003טעם \"ויצק\"? משום\u0004 ש\u0003\"וימשח\"\u0004 כלומר, שהיציקה היתה לאחר המשיחה, שהיא העיקר.","ועוד בענין משיחה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"כשמן הטוב\u0004 על הראש \u0003ירד על הזקן זקן אהרן\u0004 שיורד על פי מדותיו\" (תהלים קלג, ב) — \u0003כמין שני טפי מרגליות היו תלויות לאהרן בזקנו\u0004 משמן המשחה. \u0003אמר רב פפא, תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשהוא מספר\u0004 (מדבר), ואגב כך היה זקנו נע והיו טיפות אלה \u0003עולות\u0004 בדרך נס \u0003ויושבות לו בעיקר זקנו\u0004 כדי שלא תפולנה, \u0003ועל דבר זה היה משה דואג, אמר: שמא חס ושלום מעלתי בשמן המשחה\u0004 שיצקתי יותר מדי, שהרי יש שתי טיפות נוספות? \u0003יצתה\u0004 (יצאה) \u0003בת קול ואמרה: \"כשמן הטוב וגו' כטל חרמון\"\u0004 (תהלים קלג, ג), והשוואה זו באה ללמד: \u0003מה טל חרמון אין בו מעילה\u0004 שהרי אין הוא קדוש, \u0003אף שמן המשחה שבזקן אהרן אין בו מעילה.\u0004","\u0003ועדיין היה אהרן\u0004 עצמו \u0003דואג, אמר: שמא משה לא מעל\u0004 שהוא עשה כדין \u0003אבל אני מעלתי\u0004 שהשמן הנוסף נמצא עלי ואני נהנה ממנו? \u0003יצתה בת קול ואמרה לו: \"הנה מה טוב ומה נעים שבת אחים גם יחד\"\u0004 (תהלים קלג, א), \u0003מה משה\u0004 אחיך \u0003לא מעל, אף אתה לא מעלת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מושחים את המלכים אלא על המעיין,\u0004 לסימן טוב \u0003כדי שתמשך מלכותם\u0004 כמעין, \u0003שנאמר\u0004 בהמלכת שלמה בימי דוד: \u0003\"ויאמר המלך להם קחו עמכם את עבדי אדניכם\u0004 והרכבתם את שלמה בני על הפרדה אשר לי \u0003והורדתם אתו אל גחון\u0004 ומשח אותו שם צדוק הכהן ונתן הנביא למלך על ישראל ותקעתם בשופר ואמרתם יחי המלך שלמה\" (מלכים א א, לג—לד).","אגב הזכרת ענין זה של עשיית דבר לסימן טוב מביאים מה ש\u0003אמר ר' אמי: האי מאן דבעי לידע אי מסיק שתיה אי לא\u0004 \u0005[מי שרוצה לדעת אם תעלה שנתו\u0006 ולא ימות בה, \u0005או לא],\u0006 \u0003ניתלי שרגא\u0004 \u0005[שידליק נר]\u0006 \u0003בעשרה יומי\u0004 \u0005[ימים]\u0006 ש\u0003בין ראש השנה ליום הכפורים בביתא דלא נשיב זיקא\u0004 \u0005[בבית שאין נושבת\u0006 בו \u0005רוח],\u0006 ויתבונן בו: \u0003אי משיך נהוריה נידע דמסיק שתיה\u0004 \u0005[אם נמשך אורו ידע שתעלה שנתו]\u0006 ויחיה.","\u0003ומאן דבעי למיעבד בעיסקא\u0004 \u0005[ומי שרוצה לעשות עסק],\u0006 \u0003ובעי למידע אי מצלח אי לא מצלח\u0004 \u0005[ורוצה לדעת אם יצליח או לא יצליח\u0006 בו\u0005],\u0006 \u0003לירבי תרנגולא\u0004 \u0005[שיגדל תרנגול],\u0006 \u0003אי שמין ושפר, מצלח\u0004 \u0005[אם משמין ומתייפה מצליח\u0006 העסק\u0005].\u0006","ועוד, \u0003האי מאן דבעי למיפק לאורחא\u0004 \u0005[מי שרוצה לצאת לדרך],\u0006 \u0003ובעי למידע אי חזר ואתי לביתא אי לא\u0004 \u0005[ורוצה לדעת אם יחזור ויבוא לביתו אם לא],\u0006 \u0003ניקום בביתא דחברא\u0004 \u0005[שילך בבית אפל],\u0006 \u0003אי חזי\u0004 \u0005[אם\u0006 הוא \u0005רואה]\u0006 \u0003בבואה\u0004 (צל) של \u0003בבואה לידע דהדר ואתי לביתא\u0004 \u0005[שידע ש\u0006הוא \u0005חוזר ובא לביתו].\u0006 ועל כל זה אומרים: \u0003ולאו מלתא\u0004 \u0005[ולא דבר\u0006 הנהגה ראויה] \u0003היא\u0004 ואין לעשות כך, \u0003דלמא חלשא דעתיה\u0004 \u0005[שמא תחלש דעתו]\u0006 אם יראה שלא עלה הסימן יפה, \u0003ומיתרע מזליה\u0004 \u0005[וירע מזלו]\u0006 וזה עצמו יגרום לו לאסון. \u0003אמר אביי: השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 \u0003סימנא, מילתא היא\u0004 \u0005[סימן, דבר הוא]\u0006 ויש בו ממש, \u0003לעולם יהא\u0004 אדם \u0003רגיל למיחזי בריש שתא\u0004 \u0005[לראות בראש השנה\u0006 בסעודתו\u0005]\u0006 \u0003קרא ורוביא, כרתי וסילקא ותמרי\u0004 \u0005[דלעת ורוביא כרישין ותרדים ותמרים]\u0006 שכל אלה גדלים ומתרבים במהירות, כסימן טוב למעשי השנה הבאה.","ועוד בענין עשיית סימן טוב \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב משרשיא לבריה\u0004 \u0005[לבניו]:\u0006 \u0003כי בעיתו מיעל ומיגמרי קמי רבייכו\u0004 \u0005[כאשר אתם רוצים להכנס וללמוד אצל רבכם],\u0006 \u0003גרסו מתניתא ועלו לקמי רבייכו\u0004 \u0005[לימדו\u0006 קודם את \u0005המשניות והכנסו לפני רבכם].\u0006 \u0003וכי יתביתו קמיה, חזו לפומיה\u0004 \u0005[וכאשר אתם יושבים לפניו, הסתכלו בפיו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיו עיניך ראות את מוריך\"\u0004 (ישעיהו ל, כ). \u0003וכי גרסיתו, גרסו על נהרא דמיא\u0004 \u0005[וכאשר אתם לומדים, לימדו על נהר מים],\u0006 \u0003דכי היכי דמשכן מיא משכן שמעתתייכו\u0004 \u0005[שכמו שנמשכים המים יימשך\u0006 גם \u0005למודכם]\u0006 ולא ייפסקו. ועוד עצה כללית אמר להם: \u0003ותיבו אקילקלי\u0004 \u0005[ו\u0006מוטב לכם \u0005לשבת על האשפות]\u0006 של העיר \u0003מתא מחסיא ולא תיבו אפדני\u0004 \u0005[ואל תשבו בארמונות]\u0006 של העיר \u0003פומבדיתא, טב גלדנא סריא\u0004 \u0005[טוב דג מסריח]\u0006 של \u0003מתא מחסיא למיכל\u0004 \u0005[לאכול],\u0006 \u0003מכותחא דרמי כיפי\u0004 \u0005[מכותח ש\u0006עוקר \u0005ומשליך סלעים\u0006 ממקומם\u0005],\u0006 כלומר, תבלין חריף וחזק מאד.","ועוד לענין סימן טוב במשיחה, נאמר בתפילת חנה אם שמואל \u0003\"רמה קרני באלהי\"\u0004 (שמואל א ב, א), ומדייקים: \u0003\"רמה קרני\" ולא רמה פכי, דוד ושלמה שנמשחו בקרן\u0004 — סימן טוב היה להם ו\u0003נמשכה מלכותן, שאול ויהוא שנמשחו בפך\u0004 — \u0003לא נמשכה מלכותן.\u0004","בענין ששנינו במשנה \u0003המשוח בשמן המשחה\u0004 ולא המרובה בבגדים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"משיח\"\u0004 — \u0003יכול\u0004 שהכוונה היא ל\u0003מלך? תלמוד לומר: \"כהן\". אי\u0004 \u0005[אם]\u0006 \u0003כהן, יכול\u0004 שהוא \u0003מרובה בגדים? תלמוד לומר: \"משיח\". אי\u0004 \u0005[אם]\u0006 \u0003משיח, יכול\u0004 ש\u0003משוח מלחמה\u0004 בכלל זה? \u0003תלמוד לומר: \"והכהן המשיח\",\u0004 לומר \u0003שאינו\u0004 (שאין) \u0003משיח על גביו\u0004 אלא הוא הגדול שבכהנים.","ושואלים: \u0003מאי משמע\u0004 \u0005[מה\u0006 כיצד נובעת מכאן \u0005משמעות\u0006 זו\u0005]?\u0006 ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רבא\u0004 על המלה \u0003\"הירך\"\u0004 הנאמרת באיסור גיד הנשה (בראשית לב, לב) — שהכוונה היא \u0003המיומנת\u0004 (החשובה) \u0003שבירך, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003\"המשיח\"\u0004 — \u0003המיומן שבמשוחים\u0004 והחשוב שבהם שהוא הכהן הגדול.","ודנים בנאמר בברייתא, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"משיח\"\u0004 — \u0003יכול מלך.\u0004 ותוהים: \u0003מלך פר הוא דמייתי\u0004 \u0005[שמביא]?\u0006 הלוא \u0003שעיר הוא דמייתי\u0004 \u0005[שמביא]\u0006 כמו שמפורש הלאה! ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך\u0006 הדבר להיאמר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003על שגגת מעשה\u0004 כמו של שאר אדם \u0003יביא שעיר,\u0004 אבל \u0003על העלם דבר\u0004 של שגגת הוראה \u0003יביא פר, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינו מביא פר אלא רק הכהן הגדול.","שנינו במשנה: \u0003אין בין משוח בשמן המשחה\u0004 לכהן גדול מרובה בבגדים אלא הבאת פר של העלם דבר. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' מאיר, דאי\u0004 \u0005[שאם]\u0006 \u0003ר' מאיר, הא תניא\u0004 \u0005[הרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מרובה בגדים מביא פר הבא על כל המצו‍ת,\u0004 אלו \u0003דברי ר' מאיר, ולא הודו לו חכמים.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"משיח\" —\u0004 \u0003אין לי אלא משוח בשמן המשחה, מרובה בגדים מנין? תלמוד לומר: \"הכהן המשיח\"\u0004 שממנו למדים ריבוי לכל מי שהוא כהן גדול בפועל, אף שאינו משוח.","ושואלים: \u0003במאי אוקימתיה\u0004 \u0005[במה העמדת\u0006 את משנתנו\u0005]?\u0006 \u0003כרבנן\u0004 \u0005[\u0006ו\u0005כ\u0006שיטת \u0005חכמים],\u0006"],["\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]:\u0006 \u0003אין בין כהן משמש\u0004 \u0003לכהן שעבר\u0004 שנתמנה לשעתו ועבר מכהונתו \u0003אלא פר יום הכפורים ועשירית האיפה,\u0004 אבל בשאר דברים שניהם שוים, ואם כן בדברים אלה \u0003אתאן\u0004 \u0005[הגענו]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אירע בו פסול בכהן גדול ועבר\u0004 מכהונתו \u0003ומינו כהן אחר תחתיו\u0004 — \u0003הראשון חוזר לעבודתו, והשני כל מצו‍ת\u0004 ואיסורי \u0003כהונה\u0004 חלים \u0003עליו, דברי ר' מאיר. ר' יוסי אומר: ראשון חוזר לעבודתו, ושני אינו ראוי לא לכהן גדול ולא לכהן הדיוט\u0004 ואינו עובד כלל.","\u0003אמר ר' יוסי: מעשה ב\u0004כהן ושמו \u0003יוסף בן אילים מצפורי שאירע בו פסול בכהן גדול, ועבר, ומינו אחר\u0004 את יוסף בן אילים הזה \u0003תחתיו, ו\u0004אחר כך, כשחזר הכהן הקבוע לשמש, \u0003לא הניחוהו\u0004 ליוסף זה \u0003אחיו הכהנים להיות לא כהן גדול ולא כהן הדיוט,\u0004 וטעם הדבר: \u0003כהן גדול\u0004 אינו יכול להיות \u0003משום איבה,\u0004 כדי שלא יהיו יחד שני כהנים גדולים ותהא איבה ביניהם, ואילו \u0003כהן הדיוט\u0004 אינו יכול להיות \u0003משום\u0004 הכלל של \u0003מעלין בקדש ואין מורידין,\u0004 שכיון שהיה כבר כהן גדול שוב אין מורידים אותו מגדולתו.","ואם כן נמצא שמשנתנו \u0003רישא רבנן\u0004 \u0005[ראשה\u0006 כדברי \u0005חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' מאיר? אמר רב חסדא: אין\u0004 \u0005[כן],\u0006 \u0003רישא רבנן\u0004 \u0005[ראשה\u0006 כדעת \u0005חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כדעת \u0003ר' מאיר. רב יוסף אמר:\u0004 אין זו משנה חלוקה, אלא כולה כשיטת \u0003רבי היא, ונסיב לה אליבא דתנאי\u0004 \u0005[ולוקח אותה כשיטת\u0006 שני \u0005תנאים].\u0006 שמקבל דעת חכמים בענין אחד, ודעת ר' מאיר באחר.","\u0003רבא אמר:\u0004 כל המשנה כולה, שיטת \u0003ר' שמעון היא וסבר לה\u0004 \u0005[וסבור הוא]\u0006 \u0003כר' מאיר בחדא\u0004 \u0005[\u0006ו\u0005ב\u0006דבר \u0005אחד]\u0006 \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחד].\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003דברים שבין כהן גדול לכהן הדיוט אלו הם:\u0004 שכהן גדול מביא \u0003פר הבא על כל המצו‍ת\u0004 (פר העלם דבר), \u0003ופר יום הכפורים, ועשירית האיפה\u0004 בכל יום, \u0003ולא פורע ולא פורם\u0004 באבילותו, \u0003אבל הוא\u0004 הכהן הגדול \u0003פורם\u0004 בגדיו \u0003מלמטה וההדיוט\u0004 פורם \u0003מלמעלה, ואין מטמא לקרובים\u0004 שלו שמתו, \u0003ומוזהר על\u0004 (מחוייב) בנישואי \u0003הבתולה\u0004 בלבד, \u0003ואסור ב\u0004נשיאת \u0003אלמנה, ומחזיר את הרוצח\u0004 מעיר המקלט כאשר הוא מת,","\u0003ומקריב אונן\u0004 אפילו ביום אבילותו, \u0003ואינו אוכל\u0004 מן הקדשים בהיותו אונן, \u0003ואינו חולק\u0004 בקדשים שהוקרבו באותו יום שמת לו אחד מקרוביו. \u0003מקריב חלק בראש\u0004 כלומר, מתי שירצה, \u0003ונוטל\u0004 מן הקרבנות כל \u0003חלק\u0004 שירצה \u0003בראש, ומשמש\u0004 עושה את עבודתו \u0003בשמונה כלים\u0004 (בגדי כהונה), \u0003וכל עבודת יום הכפורים אינה כשרה אלא בו, ופטור על טומאת מקדש וקדשיו,\u0004","\u0003וכולן נוהגין במרובה בגדים חוץ מפר המביא על כל המצו‍ת\u0004 שהוא אינו מביא, \u0003וכולן נוהגין במשיח שעבר חוץ מפר יום הכיפורים ועשירית האיפה, וכולן אין נוהגין במשוח מלחמה חוץ מחמשה דברים האמורים בפרשה\u0004 של דיני הכהן הגדול (ויקרא כ״א:י׳): \u0003לא פורע ולא פורם, ואין מטמא לקרובים, ומוזהר על הבתולה, ואסור באלמנה, ומחזיר את הרוצח,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים: אינו מחזיר.\u0004","ושואלים: \u0003והאי ממאי\u0004 \u0005[ו\u0006ברייתא \u0005זו מנין]\u0006 ששיטת \u0003ר' שמעון היא? אמר רב פפא: מאן שמעת ליה\u0004 \u0005[מי שמעת אותו]\u0006 ש\u0003אמר\u0004 שהכהן הגדול \u0003פטור על טומאת מקדש וקדשיו?\u0004 הרי זה \u0003ר' שמעון.\u0004 וסובר כר' מאיר בכהן שעבר וכרבנן בכהן מרובה בגדים, שאינו מביא פר העלם דבר.","נאמר בברייתא שמשוח מלחמה אין בו דין כהן גדול \u0003חוץ מחמשה דברים האמורים בפרשה.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"והכהן הגדול מאחיו\"\u0004 (ויקרא כא, י) — \u0003זה כהן גדול, \"אשר יוצק על ראשו שמן המשחה\"\u0004 — \u0003זה משוח מלחמה, \"ומלא את ידו ללבש את הבגדים\"\u0004 — \u0003זה מרובה בגדים, על כולן הוא אומר\u0004 מה שכתוב בהמשך: \u0003\"ראשו לא יפרע ובגדיו לא יפרם ועל כל נפשת מת לא יבא\"\u0004 (ויקרא כא, י).","\u0003יכול יהו כולן מקריבין אוננים? תלמוד לומר: \"כי נזר שמן משחת אלהיו עליו\"\u0004 (ויקרא כא יב), להדגיש \u0003\"עליו\" ולא על חבירו\u0004 כלומר, רק על הכהן הגדול. \u0003ואחר שחלקו הכתוב, יכול לא יהא\u0004 משוח מלחמה \u0003מצווה על הבתולה? תלמוד לומר:\u0004 בתוספת ו' \u0003\"והוא\u0004 אשה בבתוליה יקח\"","(ויקרא כא יג) ובא לרבות משוח מלחמה. ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בענין זה. נאמר: \u0003\"והוא אשה בבתוליה יקח\"\u0004 (ויקרא כא יג), \u0003אחר שחלק הכתוב\u0004 בין כהן משוח מלחמה לכהן גדול לענין שאינו מקריב כשהוא אונן, \u0003ריבה\u0004 אחר כך, את משוח המלחמה בדינים אלה. אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר: אין לי אלא\u0004 כהן גדול \u0003שעבר מחמת קריו,\u0004 שאינו יכול לשמש במשך זמן קצר, עבר \u0003מחמת מומין\u0004 שאינו חוזר להכשרו \u0003מנין\u0004 שאף הוא עדיין מצווה על הבתולה? \u0003תלמוד לומר: \"והוא\"\u0004 לרבות כשעבר מחמת מום, אבל לענין משוח מלחמה אין ריבוי.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 כהן \u0003משיח שנצטרע מהו באלמנה?\u0004 האם נאמר כי \u0003מידחא דחי\u0004 \u0005[דחוי\u0006 הוא\u0005]\u0006 לפי שעה אבל עדיין כהן גדול הוא, \u0003או מיפטר פטר\u0004 \u0005[פטור\u0006 לגמרי\u0005]\u0006 שיצא מגדר כהן גדול לחלוטין? \u0003לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005].\u0006","\u0003זימנין הוי יתיב\u0004 \u0005[פעם\u0006 אחרת \u0005ישב]\u0006 \u0003רב פפא וקמבעיא ליה\u0004 \u0005[ונשאלה לו\u0006 אותה שאלה\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן לרב פפא, תנינא\u0004 \u0005[שנינו\u0006 ברייתא\u0005]:\u0006 \u0003אין לי אלא שעבר מחמת קריו, עבר מחמת מומין מנין? תלמוד לומר: \"והוא\".\u0004 ומצורע נחשב גם כבעל מום, ואסור באלמנה. כיון ששמע רב פפא ראיה זו, התפעל \u0003קם נשקיה ברישיה\u0004 \u0005[נשקו בראשו]\u0006 \u0003ויהיב ליה ברתיה\u0004 \u0005[ונתן לו\u0006 את \u0005בתו\u0006 לאשה\u0005]\u0006 מחמת ההערכה על גדולתו בתורה.","\u0003כהן גדול פורם\u0004 באבילותו את בגדו \u0003מלמטה, וה\u0004כהן ה\u0003הדיוט\u0004 פורם \u0003מלמעלה\u0004 כשאר אדם. \u0003כהן גדול מקריב אונן\u0004 (ביום שמת אחד מקרוביו) \u0003ולא אוכל\u0004 באותו יום ממה שהוא מקריב, \u0003וההדיוט לא מקריב ולא אוכל.\u0004","\u0003אמר רב: למטה\u0004 — האמור במשנה שכהן גדול פורם מלמטה, כוונתו \u0003למטה ממש\u0004 בתחתית הבגד, \u0003למעלה —\u0004 \u0003למעלה ממש. ושמואל אמר: למטה\u0004 — פירושו \u0003למטה מקמי\u0004 \u0005[מפני]\u0006 \u0003שפה,\u0004 לא בשפת הבגד למעלה אלא למטה ממנו, בלא לקרוע את השפה. \u0003למעלה\u0004 — כוונתו \u0003למעלה מקמי\u0004 \u0005[מפני]\u0006 \u0003שפה,\u0004 כלומר בשפת הבגד עצמו. \u0003וזה וזה\u0004 פורמים \u0003בצואר\u0004 הבגד.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 על שיטת שמואל \u0003על כל המתים כולן\u0004 כשקורע עליהם — \u0003רצה מבדיל\u0004 (מחלק לשניים) \u0003קמי\u0004 \u0005[מפני]\u0006 \u0003שפה שלו, רצה אינו מבדיל קמי\u0004 \u0005[מפני]\u0006 \u0003שפה שלו,\u0004 אם קורע \u0003על אביו ועל אמו\u0004 — \u0003מבדיל. כיון דבעלמא הוי\u0004 \u0005[שבכלל\u0006 הרי \u0005זה\u0006 נחשב\u0005]\u0006 \u0003קרע\u0004 גם אם לא מבדיל, אם כן \u0003קרי\u0004 \u0005[קרא\u0006 בו\u0005]\u0006 \u0003כאן\u0004 אצל כהן גדול \u0003\"בגדיו לא יפרם\"!\u0004 וראיה לשיטת רב שכהן גדול אינו פורם למעלה רק למטה.","ומשיבים: \u0003שמואל כ\u0004דעת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר: כל קרע שאינו מבדיל שפה שלו, אינו אלא קרע של תפלות\u0004 (שטות) ואינו נחשב כקרע ממש. ויכול הכהן גדול לפרום למעלה ולא להבדיל. ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לר' יהודה\u0004 בכלל סברה זו שיש \u0003קריעה בכהן גדול?\u0004","\u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אילו נאמר \"ראש לא יפרע ובגד לא יפרם\", הייתי אומר: בראש ובגד של סוטה הכתוב מדבר\u0004 שאין הכהן הגדול פורע את ראש האשה ופורם בגדה, כדרך שעושה כהן הדיוט לסוטה, \u0003תלמוד לומר: \"את ראשו לא יפרע ובגדיו לא יפרם\"\u0004 (ויקרא כא, י), ללמד \u0003שאינו בפריעה ופרימה כל עיקר,\u0004 אלו \u0003דברי ר' יהודה. ר' ישמעאל אומר: אינו פורם כדרך שבני אדם\u0004 אחרים \u0003פורמין, אלא הוא מלמטה וההדיוט מלמעלה.\u0004 אם כן לדברי ר' יהודה הכהן הגדול אינו פורם כלל!","ומשיבים: \u0003שמואל סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יהודה בחדא\u0004 \u0005[\u0006ו\u0005ב\u0006דבר \u0005אחד]\u0006 בדיני קריעה בכלל, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו ב\u0006דבר \u0005אחד]\u0006 שסבור שכהן גדול צריך לקרוע.","\u0003כל\u0004 \u0003התדיר מחבירו\u0004 כל דבר מצוה שהוא מצוי יותר להיעשות \u0003קודם את חבירו\u0004 אם שניהם באים יחד, \u0003וכל המקודש מחבירו קודם את חבירו.\u0004 אם היו \u0003פר המשיח ופר העדה\u0004 שמביאים על שגגת העלם דבר \u0003עומדים\u0004 ושניהם צריכים הקרבה — \u0003פר המשיח קודם לפר העדה בכל מעשיו.\u0004","על האמור במשנה שהתדיר קודם, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006? \u0003אמר אביי,\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"מלבד עולת הבקר אשר לעולת התמיד\"\u0004 (במדבר כח, כג), \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"עולת הבקר\",\u0004 אם כן \u0003\"עולת התמיד\" למה לי?\u0004 הרי יודעים שהיא עולת תמיד של בוקר! \u0003הכי קאמר רחמנא\u0004 \u0005[כך אמרה התורה]:\u0006 \u0003כל\u0004 ש\u0003תדירה\u0004 יותר \u0003קדמה\u0004 \u0005[קודמת],\u0006 וכיון שהיא עולת התמיד ותדירה לכן היא קודמת לקרבנות אחרים.","ועוד שנינו במשנה \u0003וכל המקודש מחבירו הוא קודם את חבירו.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"וקדשתו\u0004 כי את לחם אלהיו הוא מקריב והיה קודש\" (ויקרא כא, ח) — לומר שיש לתת לו חשיבות וקדימה \u0003לכל דבר שבקדושה, לפתוח ראשון\u0004 בקריאת התורה, \u0003ולברך ראשון\u0004 בזימון, \u0003וליטול מנה יפה ראשון,\u0004 ומכאן שהמקודש קודם לאחרים."],["שנינו במשנה: \u0003פר כהן משוח ופר עדה\u0004 עומדים, פר הכהן המשוח קודם. ועל כך שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"ושרף אותו כאשר שרף את הפר הראשון\"\u0004 (ויקרא ד, כא), \u0003מה תלמוד לומר \"הראשון\"?\u0004 לאחר שנאמר כבר שפר זה נעשה כפר כהן משיח? למדנו \u0003שיהא ראשון\u0004 כלומר, \u0003קודם לפר העדה בכל מעשיו.\u0004","עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פר כהן משיח ופר העדה עומדים\u0004 — \u0003פר כהן משיח קודם לפר העדה בכל מעשיו,\u0004 וטעמו של דבר: \u0003הואיל ומשיח מכפר\u0004 על ישראל בכלל, \u0003ועדה\u0004 היא ה\u0003מתכפרת, דין הוא שיקדים המכפר למתכפר, וכן הוא אומר: \"וכפר בעדו ובעד ביתו ובעד כל קהל ישראל\"\u0004 (ויקרא טז, יז).","\u0003פר העלם דבר של צבור קודם לפר של עבודה זרה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003האי\u0004 \u0005[זה]\u0006 פר העלם דבר הוא פר \u0003חטאת והאי\u0004 \u0005[וזה]\u0006 פר עבודה זרה \u0003עולה, ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"והקריב את אשר לחטאת ראשונה\"\u0004 (ויקרא ה, ח), \u0003מה תלמוד לומר? אם ללמד\u0004 באותו ענין \u0003שתהא חטאת ראשונה, הרי כבר נאמר: \"ואת השני יעשה עולה כמשפט\"\u0004 (ויקרא ה, י)! \u0003אלא זה בנה אב\u0004 שממנו למדים בכל מקום \u0003שיהו כל חטאות קודמות לעולות הבאים עמהם, וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 ש\u0003אפילו חטאת העוף קודמת לעולת בהמה.\u0004","\u0003פר עבודה זרה קודם לשעיר עבודה זרה\u0004 שמביאים כל העדה. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003האי\u0004 \u0005[זה]\u0006 השעיר \u0003חטאת\u0004 \u0003והאי\u0004 \u0005[וזה]\u0006 הפר \u0003עולה!\u0004 \u0003אמרי במערבא משמיה\u0004 \u0005[אומרים בארץ ישראל משמו]\u0006 של \u0003רבא בר מרי: חטאת עבודה זרה חסירא אל\"ף, \"לחטת\" כתיב\u0004 \u0005[נאמר]\u0006 (במדבר טו, כד), ללמד שאין בה כל דיני חטאת. \u0003רבא אמר: \"כמשפט\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 (ויקרא ה, י), שיש לעשותו כסדר הכתובים, ושם קודם הפר לשעיר.","\u0003שעיר עבודה זרה\u0004 של העדה \u0003קודם לשעיר נשיא. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003צבור והאי\u0004 \u0005[וזה]\u0006 \u0003יחיד,\u0004 וציבור קודם ליחיד אפילו הוא מלך. \u0003שעיר נשיא קודם לשעירת יחיד. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003מלך והאי\u0004 \u0005[וזה]\u0006 \u0003הדיוט\u0004 (אדם פשוט).","\u0003שעירת יחיד קודמת לכבשת יחיד.\u0004 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כבשת יחיד קודמת לשעירת יחיד! אמר אביי: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003שעירה עדיפא\u0004 \u0005[עדיפה]\u0006\u0003, שכן נתרבתה\u0004 כלומר, יש בה ריבוי ויחוד, שמביאים אותה \u0003אצל עבודה זרה ביחיד,\u0004 ששם מקריבים דווקא שעירה ולא כבשה. \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003כבשה עדיפא\u0004 \u0005[עדיפה],\u0006 \u0003שכן נתרבתה באליה\u0004 שמביאים ממנה גם את האליה למזבח, ולכן היא קרבן עדיף.","קרבן ה\u0003עומר קודם לכבש הבא עמו,\u0004 וכן \u0003שתי הלחם קודמים לכבשים הבאים עמהם. זה הכלל: דבר הבא בגין ליום\u0004 בשביל היום, משום מצוות היום, \u0003קודם לדבר הבא בגין לחם,\u0004 והכבשים הללו הם רק כתוספת לקרבן העיקרי, והקרבן העיקרי הוא העומר ושתי הלחם.","\u0003האיש קודם לאשה\u0004 בזמן שיש ספק במי מהם לבחור \u0003להחיות\u0004 או \u0003להשב אבדה\u0004 של אחד מהם, \u0003והאשה קודמת לאיש\u0004 בזמן שצריך לדאוג \u0003לכסות\u0004 לפי שבושתה מרובה, או \u0003להוציא מבית השבי,\u0004 שמלבד היסורים והסכנה יש חשש שיאנסוה. \u0003בזמן ששניהם עומדים בקלקלה\u0004 כאשר גם האיש שבוי לצורך משכב זכר — \u0003האיש קודם לאשה\u0004 לפדותו.","ועוד בענין קדימויות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היה הוא ואביו ורבו בשבי\u0004 — \u0003הוא קודם לרבו\u0004 מפני שחייו קודמים, \u0003ורבו קודם לאביו, אמו\u0004 במקרה זה \u0003קודמת לכולם.\u0004","\u0003חכם קודם למלך ישראל,\u0004 וטעמו של דבר: \u0003חכם שמת\u0004 — \u0003אין לנו כיוצא בו, מלך ישראל שמת\u0004 — \u0003כל ישראל ראוים למלכות.\u0004","\u0003מלך קודם לכהן גדול, שנאמר: \"ויאמר המלך להם קחו עמכם את עבדי אדניכם\" וגו'\u0004 (מלכים א א, לג), שקרא דוד המלך לעצמו אדון כלפי צדוק הכהן.","\u0003כהן גדול קודם לנביא, שנאמר: \"ומשח אתו שם צדוק הכהן ונתן הנביא\"\u0004 (שם לד), \u0003הקדים צדוק לנתן. ואומר: \"שמע נא יהושע הכהן הגדול אתה ורעיך\" וגו'\u0004 (זכריה ג, ח), \u0003יכול\u0004 אותם הרעים \u0003הדיוטות היו? תלמוד לומר: \"כי אנשי מופת המה\"\u0004 (זכריה ג, ח), \u0003ואין \"מופת\" אלא נביא, שנאמר: \"ונתן אליך אות או מופת\"\u0004 (דברים יג, ב), הרי שהנביאים הם כנספחים כלפי הכהן הגדול.","כהן גדול \u0003משוח בשמן המשחה קודם למרובה בגדים; מרובה בגדים קודם למשיח שעבר\u0004 מכהונתו אפילו עבר \u0003מחמת קריו; משיח שעבר מחמת קריו קודם לעבר מחמת מומו;\u0004 מי ש\u0003עבר מחמת מומו\u0004 עדיין \u0003קודם למשוח מלחמה; משוח מלחמה קודם לסגן\u0004 הכהן הגדול, שכאשר אין הכהן הגדול יכול לשמש במקדש, הסגן ממלא את מקומו.","\u0003סגן קודם לאמרכל,\u0004 אחד משבעה הממונים על המקדש. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אמרכל? אמר רב חסדא:\u0004 אמרכל פירושו \u0003אמר כולא.\u0004 כלומר, ממונה כללי על המקדש. \u0003אמרכל קודם לגזבר\u0004 הממונה על אוצרות המקדש\u0003; גזבר קודם לראש משמר\u0004 מעשרים וארבעה משמרות שנחלקו בהם הכהנים\u0003; ראש משמר קודם לראש בית אב\u0004 שהוא יחידה בתוך המשמר, ובדרך כלל עובדים אלה יום אחד בשבוע של המשמר; \u0003ראש בית אב קודם לכהן הדיוט.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: \u0003לענין טומאה, סגן\u0004 כהן גדול \u0003ומשוח מלחמה איזה מהם קודם\u0004 אם היה לפניהם מת מצוה שיש לטפל בקבורתו, והכל (אף כהן ונזיר) מצווים על כך, מי מהם יטמא?","\u0003אמר מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003סגן ומשוח מלחמה שהיו מהלכים בדרך ופגע בהם מת מצוה\u0004 וצריך אחד מהם להיטמא לו, \u0003מוטב שיטמא משוח מלחמה ואל יטמא סגן, שאם יארע בו פסול בכהן גדול, נכנס הסגן ומשמש תחתיו,\u0004 ולכן יש לדאוג ככל האפשר שישאר הסגן בטהרתו. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003משוח מלחמה קודם לסגן! אמר רבינא: כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 לא לענין טומאה, אלא \u0003להחיותו,\u0004 שמבחינת דרגתו משוח מלחמה נחשב בדרגה גבוהה יותר.","\u0003כהן קודם ללוי, לוי לישראל, ישראל לממזר, וממזר לנתין\u0004 (מצאצאי הגבעונים), \u0003ונתין לגר, וגר לעבד משוחרר. אימתי\u0004 דיני קדימות אלה? \u0003בזמן שכולם שוים\u0004 בחכמה. \u0003אבל אם היה ממזר תלמיד חכם וכהן גדול עם הארץ\u0004 — \u0003ממזר תלמיד חכם קודם לכהן גדול עם הארץ,\u0004 שגדולת התורה עולה על כולם.","ומסבירים את האמור במשנה: \u0003כהן קודם ללוי\u0004 — \u0003שנאמר: \"בני עמרם אהרן ומשה ויבדל אהרן להקדישו קדש קדשים\"\u0004 (דברי הימים א כג, יג). \u0003לוי קודם לישראל\u0004 — \u0003שנאמר: \"בעת ההיא הבדיל ה' את שבט הלוי\" וגו'\u0004 (דברים י, ח).","\u0003ישראל קודם לממזר\u0004 — לפי \u0003שזה\u0004 הישראל \u0003מיוחס, וזה\u0004 הממזר \u0003אינו מיוחס\u0004 ופסול לבוא בקהל. \u0003ממזר קודם לנתין\u0004 — כי \u0003זה\u0004 הממזר על כל פנים \u0003בא מטפה כשרה\u0004 של אדם מישראל, \u0003וזה\u0004 הנתין \u0003בא מטפה פסולה\u0004 של גבעוני. \u0003נתין קודם לגר\u0004 — כי \u0003זה\u0004 הנתין \u0003גדל עמנו בקדושה\u0004 שכל ימיו נהג כישראל, \u0003וזה\u0004 הגר \u0003לא גדל עמנו בקדושה. גר קודם לעבד משוחרר\u0004 — כי \u0003זה\u0004 העבד המשוחרר \u0003היה\u0004 בהיותו עבד \u0003בכלל ארור, וזה\u0004 הגר \u0003לא היה בכלל ארור.\u0004","שנינו במשנה: \u0003אימתי? בזמן שכולן שוין כו'.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר רב אחא בר' חנינא,\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"יקרה היא מפנינים\"\u0004 (משלי ג, טו), לומר יקרה התורה אפילו \u0003מכהן גדול שנכנס לפני ולפנים\u0004 ולקדש הקדשים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בר יוחאי אומר: בדין הוא שיקדים עבד משוחרר לגר,\u0004 משום \u0003שזה\u0004 העבד המשוחרר \u0003גדל עמנו בקדושה, וזה\u0004 הגר \u0003לא גדל עמנו בקדושה, אלא זה\u0004 העבד \u0003היה בכלל ארור, וזה לא היה בכלל ארור,\u0004 לפיכך הגר קודם.","\u0003שאלו תלמידיו את ר' אלעזר בר' צדוק: מפני מה הכל רצין לישא גיורת\u0004 כלומר, יש רבים יותר שרוצים לישא גיורת, \u0003ואין הכל רצין לישא משוחררת? אמר להם: זו\u0004 השפחה \u0003היתה בכלל ארור, וזו\u0004 הגיורת \u0003לא היתה בכלל ארור. דבר אחר: זו\u0004 הגיורת \u0003היתה בחזקת שמור\u0004 כלומר, שמן הסתם שמרה את עצמה בצניעות, \u0003וזו\u0004 השפחה \u0003לא היתה בחזקת שמור.\u0004","\u0003שאלו תלמידיו את ר' אלעזר: מפני מה הכלב מכיר את קונו\u0004 (אדוניו), \u0003וחתול אינו מכיר את קונו? אמר להם:\u0004 לא פלא, \u0003ומה\u0004 כמו שמקובל בידינו ש\u0003האוכל ממה שעכבר אוכל\u0004 — \u0003משכח\u0004 דברים, החתול \u0003האוכל\u0004 את ה\u0003עכבר עצמו, על אחת כמה וכמה.\u0004","\u0003שאלו תלמידיו את ר' אליעזר: מפני מה הכל מושלים בעכברים,\u0004 שכל הטורפים אוכלים אותם? אמר להם: \u0003מפני שסורן\u0004 (שיצרם) \u0003רע\u0004 כלומר, יש להם מנהגים רעים. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מה הם אותם מנהגים רעים? \u0003רבא אמר: אפילו גלימי גייצי\u0004 \u0005[גלימות\u0006 הם \u0005מכרסמים]\u0006 אף על פי שאינם מזון להם."],["\u0003רב פפא אמר: אפילו שופתא מרא גייצי\u0004 \u0005[קת של מעדר\u0006 הם \u0005מכרסמים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים].\u0006 \u0003חמשה דברים משכחים את התלמוד: האוכל ממה שאוכל עכבר וממה שאוכל חתול, והאוכל לב של בהמה, והרגיל בזיתים, והשותה מים של שיורי רחיצה, והרוחץ רגליו זו על גבי זו. ויש אומרים: אף המניח כליו\u0004 (בגדיו) \u0003תחת מראשותיו.\u0004 ולעומת זאת \u0003חמשה דברים משיבים\u0004 מחזירים \u0003את התלמוד\u0004 שנשכח: \u0003פת\u0004 שנאפתה על \u0003פחמין וכל שכן\u0004 המתחמם ב\u0003פחמין עצמן, והאוכל ביצה מגולגלת\u0004 (קשה) \u0003בלא מלח, והרגיל בשמן זית, והרגיל ביין ובשמים, והשותה מים של שיורי עיסה\u0004 שנשארו מים בכלי לאחר שנילוש הבצק כל צרכו. \u0003ויש אומרים: אף הטובל אצבעו במלח ואוכל.\u0004 ודנים בברייתא זו.","נאמר בה \u0003\"הרגיל בשמן זית\".\u0004 ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003ל\u0004דברי \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: כשם שהזית\u0004 באכילתו \u0003משכח תלמוד של שבעים שנה, כך שמן זית משיב תלמוד של שבעים שנה.\u0004","\u0003\"והרגיל ביין ובשמים\". מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרבא,\u0004 ש\u0003אמר רבא: חמרא וריחני פקחין\u0004 \u0005[היין והבשמים עשו אותי פיקח].\u0006","\u0003\"והטובל אצבעו במלח\". אומר ריש לקיש: וב\u0004אצבע \u0003אחת.\u0004 ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שחלקו בענין זה, \u0003ר' יהודה אומר: אחת ולא שתים, ר' יוסי אומר: שתים ולא שלש. וסימניך\u0004 שהמחלוקת באחת ושתים: \u0003קמיצה,\u0004 שמקפלים שתי אצבעות על היד ואצבע אחת זקופה.","\u0003עשרה דברים קשים לתלמוד: העובר תחת אפסר הגמל וכל שכן תחת גמל עצמו, והעובר בין שני גמלים, והעובר בין שתי נשים, והאשה העוברת בין שני אנשים, והעובר מתחת\u0004 מקום שיש בו \u0003ריח רע של נבילה, והעובר תחת הגשר שלא עברו תחתיו מים ארבעים יום, והאוכל פת שלא בשל\u0004 (נאפה) \u0003כל צרכו, והאוכל בשר מזוהמא ליסטרון\u0004 מין כף גדולה של טבחים, \u0003והשותה מאמת\u0004 (תעלת) \u0003המים העוברת בבית הקברות, והמסתכל בפני המת. ויש אומרים: אף הקורא כתב שעל גבי הקבר.\u0004","ושוב לענין דרגות של חשיבות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשהנשיא\u0004 של הסנהדרין \u0003נכנס כל העם עומדים, ואין יושבים עד שאומר להם: שבו. כשאב בית דין נכנס, עושים לו\u0004 בדרכו \u0003שורה אחת מכאן ושורה אחת מכאן\u0004 של אנשים העומדים לכבודו \u0003עד שישב במקומו\u0004 ואז הם יושבים בעצמם. \u0003כשחכם\u0004 (השלישי בדרגה בסנהדרין) \u0003נכנס, אחד עומד ואחד יושב\u0004 שמי שהחכם בתוך ארבע אמותיו עומד, וכשיוצא משם \u0003—\u0004 חוזר ויושב. \u0003עד שישב\u0004 החכם \u0003במקומו. בני חכמים ותלמידי חכמים, בזמן שרבים צריכים להם\u0004 — \u0003מפסיעין על ראשי העם\u0004 כלומר, כשהעם יושבים על הארץ מותר להם ללכת למקומם למרות שהם נראים כפוסעים מעל ראשיהם של היושבים. \u0003יצא\u0004 אחד מהחכמים \u0003לצורך\u0004 (לעשות את צרכיו) — \u0003יכנס\u0004 ויחזור \u0003וישב במקומו\u0004 ואינו חושש לטירחת הציבור.","\u0003בני תלמידי חכמים שממונים אביהם פרנס על הצבור, בזמן שיש להם דעת לשמוע\u0004 כלומר, שהם מבינים ויכולים ללמוד — \u0003נכנסים ויושבים לפני אביהם ו\u0004יושבים כש\u0003אחוריהם כלפי העם, בזמן שאין להם דעת לשמוע\u0004 — \u0003נכנסים ויושבים לפני אביהם\u0004 אבל \u0003פניהם כלפי העם,\u0004 שרואים שהם יושבים שם מפני הכבוד אבל לא כלומדים. \u0003ר' אלעזר בר\u0004 (בנו של) \u0003ר' צדוק אומר: אף בבית המשתה\u0004 (החתונה) \u0003עושים אותם סניפין\u0004 כלומר, מושיבים אותם סמוך לאבותיהם.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יצא לצורך\u0004 — \u0003נכנס ויושב במקומו. אמר רב פפא: לא אמרו אלא ל\u0004צורך של צרכים \u0003קטנים, אבל לגדולים\u0004 — \u0003לא,\u0004 מדוע? משום ש\u0003הוה ליה למבדק נפשיה מעיקרא\u0004 \u0005[היה לו לבדוק\u0006 את \u0005עצמו מתחילה]\u0006 שלא יזדקק לצאת, ואם יצא הרי זו רשלנות ואינו צריך להטריח אנשים כשהוא חוזר. ש\u0003אמר רב יהודה אמר רב: לעולם ילמד אדם עצמו להשכים ולהעריב\u0004 לבית הכסא, \u0003כדי שלא יתרחק\u0004 בשעות אחרות למצוא לו מקום מוצנע \u0003אמר רבא: האידנא דחלשא עלמא\u0004 \u0005[בימינו שחלוש העולם],\u0006 \u0003אפילו לגדולים נמי\u0004 \u0005[גם כן]\u0006 יכול לחזור, מפני שאין אנשים בריאים כל כך.","שנינו, \u0003ר' אלעזר בר\u0004 \u0005[בנו\u0006 של\u0005]\u0006 \u0003ר' צדוק אומר: אף בבית המשתה עושים אותם סניפים\u0004 ומושיבים אותם סמוך לאבותיהם. \u0003אמר רבא:\u0004 כוונתו \u0003בחיי אביהם\u0004 ו\u0003בפני אביהם.\u0004","\u0003אמר ר' יוחנן: בימי רבן שמעון בן גמליאל נישנית משנה זו\u0004 ששנינו קודם, כי \u0003רבן שמעון בן גמליאל\u0004 היה \u0003נשיא, ר' מאיר\u0004 היה \u0003חכם, ר' נתן\u0004 היה \u0003אב בית דין, כי הוה\u0004 \u0005[כאשר היה\u0006 בא\u0005]\u0006 \u0003רבן שמעון בן גמליאל התם\u0004 \u0005[שם],\u0006 \u0003הוו קיימי כולי עלמא מקמיה\u0004 \u0005[היו עומדים הכל לפניו],\u0006 \u0003כי הוו עיילי\u0004 \u0005[כאשר היו נכנסים]\u0006 \u0003ר' מאיר ור' נתן, הוו קיימי כולי עלמא מקמייהו\u0004 \u0005[היו קמים הכל מפניהם],\u0006 \u0003אמר רבן שמעון בן גמליאל: לא בעו למיהוי היכרא בין דילי לדידהו\u0004 \u0005[האם לא צריך להיות היכר ביני ובינם]\u0006 בדרכי הכבוד? \u0003תקין הא מתניתא\u0004 \u0005[תיקן\u0006 את \u0005הברייתא הזו]\u0006 את הכלל הזה שיש הבדל בין הנשיא לשאר החכמים בענין חיוב הקימה.","\u0003ההוא יומא\u0004 \u0005[אותו יום]\u0006 שתיקנו זאת \u0003לא הוו\u0004 \u0005[היו]\u0006 \u0003ר' מאיר ור' נתן התם\u0004 \u0005[שם],\u0006 \u0003למחר כי אתו\u0004 \u0005[כאשר באו]\u0006 \u0003חזו\u0004 \u0005[ראו]\u0006 ש\u0003לא קמו מקמייהו כדרגילא מילתא\u0004 \u0005[עומדים לפניהם כמו ש\u0006היה \u0005הדבר רגיל],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמרו להו\u0004 \u0005[להם]:\u0006 \u0003הכי תקין\u0004 \u0005[כך תיקן]\u0006 \u0003רבן שמעון בן גמליאל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' מאיר לר' נתן: אנא\u0004 \u0005[אני]\u0006 \u0003חכם ואת\u0004 \u0005[ואתה]\u0006 \u0003אב בית דין, נתקין מילתא כי לדידן\u0004 \u0005[נעשה דבר\u0006 שיהיה \u0005עבורנו].\u0006 \u0003מאי נעביד ליה\u0004 \u0005[מה נעשה לו]?\u0006 \u0003נימא ליה\u0004 \u0005[נאמר לו]:\u0006 \u0003גלי\u0004 \u0005[שיגלה]\u0006 כלומר, שידרוש במסכת \u0003עוקצים, דלית ליה\u0004 \u0005[שאין לו],\u0006 שאינו יודע אותה. \u0003וכיון\u0004 ש\u0003לא גמר\u0004 \u0005[למד]\u0006 ולא יוכל לומר דבר ואז \u0003נימא ליה\u0004 \u0005[נאמר לו]:\u0006 נאמר \u0003\"מי ימלל גבורות ה' ישמיע כל תהלתו\"\u0004 (תהלים קו, ב), \u0003למי נאה למלל גבורות ה'?\u0004 ל\u0003מי שיכול להשמיע כל תהלותיו,\u0004 ולא זה שאינו יודע הכל, \u0003נעבריה\u0004 \u0005[נעביר אותו]\u0006 מנשיאותו, \u0003והוי אנא\u0004 \u0005[ואהיה אני]\u0006 \u0003אב בית דין ואת\u0004 \u0005[ואתה]\u0006 \u0003נשיא.\u0004","\u0003שמעינהו\u0004 \u0005[שמע אותם]\u0006 \u0003ר' יעקב בן קרשי\u0004 שהם משוחחים, \u0003אמר: דלמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום אתיא מלתא\u0004 \u0005[יבוא הדבר]\u0006 \u0003לידי כיסופא\u0004 \u0005[בושה]\u0006 אם כך יקרה, אבל לא רצה לדבר לשון הרע, ומשום כך \u0003אזל יתיב\u0004 \u0005[הלך ישב]\u0006 \u0003אחורי עיליתיה\u0004 \u0005[עלייתו]\u0006 של \u0003רבן שמעון בן גמליאל, פשט\u0004 \u0005[פירש]\u0006 את מסכת עוקצים, \u0003גרס ותנא\u0004 \u0005[ושנה],\u0006 \u0003גרס ותנא\u0004 \u0005[ושנה].\u0006","\u0003אמר\u0004 רבן שמעון בן גמליאל בליבו: \u0003מאי דקמא\u0004 \u0005[מהו\u0006 זה \u0005שלפנינו]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום איכא בי מדרשא מידי\u0004 \u0005[יש בבית המדרש משהו]\u0006 כלומר, שרוצים לעשות דבר כעין זה שחשבו ר' מאיר ור' נתן לעשות, \u0003יהב דעתיה וגרסה\u0004 \u0005[נתן דעתו וגרס אותה]\u0006 את מסכת עוקצים. \u0003למחר אמרו ליה\u0004 \u0005[לו]\u0006 ר' מאיר ור' נתן: \u0003ניתי מר וניתני\u0004 \u0005[יבוא אדוני וישנה]\u0006 \u0003ב\u0004מסכת \u0003עוקצין, פתח ואמר\u0004 משום שכבר התכונן יפה. \u0003בתר דאוקים\u0004 \u0005[אחרי שסיים]\u0006 להסביר, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי לא גמירנא, כסיפיתנן\u0004 \u0005[אם לא הייתי לומד, הייתם מביישים אותי],\u0006","\u0003פקיד ואפקינהו מבי מדרשא\u0004 \u0005[ציוה והוציאו אותם מבית המדרש]\u0006 כעונש. \u0003הוו כתבי קושייתא בפתקא ושדו התם\u0004 \u0005[היו כותבים קושיות בפתק והיו משליכים לשם,\u0006 לבית המדרש], \u0003דהוה מיפריק מיפריק\u0004 \u0005[\u0006בעיה זו \u0005שהיתה נפתרת היתה נפתרת],\u0006 \u0003דלא הוו מיפריק כתבי פירוקי ושדו\u0004 \u0005[זה שלא\u0006 יכלו \u0005לפתור היו\u0006 הם \u0005כותבים פתרונות וזורקים].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוסי\u0004 לחכמים: \u0003תורה\u0004 נמצאת \u0003מבחוץ ואנו מבפנים?\u0004 הלוא הם גדולי התורה!","\u0003אמר להן רבן שמעון בן גמליאל: ניעיילינהו\u0004 \u0005[נכניס אותם],\u0006 \u0003מיהו ניקנסינהו דלא נימרו שמעתא משמייהו\u0004 \u0005[אולם נקנוס אותם שלא יאמרו דבר הלכה משמם].\u0006 \u0003אסיקו\u0004 \u0005[העלו]\u0006 \u0003לר' מאיר\u0004 את הכינוי \u0003\"אחרים\", ולר' נתן\u0004 כינו \u0003\"יש אומרים\". אחוו להו בחלמייהו: זילו פייסוהו\u0004 \u0005[\u0006קראו \u0005להם בחלומם: לכו פייסוהו]\u0006 את \u0003רבן שמעון בן גמליאל, ר' נתן אזל\u0004 \u0005[הלך],\u0006 \u0003ר' מאיר לא אזל\u0004 \u0005[הלך],\u0006 כי \u0003אמר\u0004 בליבו: \u0003דברי חלומות לא מעלין ולא מורידין. כי אזל\u0004 \u0005[כאשר הלך]\u0006 \u0003ר' נתן, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבן שמעון בן גמליאל: נהי דאהני לך קמרא דאבוך\u0004 \u0005[אם אמנם הועיל לך חגורת הפאר של אביך]\u0006 שהיה ראש הגולה בבבל \u0003למהוי\u0004 \u0005[להיות]\u0006 \u0003אב בית דין, שויניך נמי\u0004 \u0005[יעשה אותך גם כן]\u0006 \u0003נשיא?!\u0004","לאחר זמן \u0003מתני ליה\u0004 \u0005[היה שונה לו]\u0006 \u0003רבי לרבן שמעון בריה\u0004 \u0005[בנו],\u0006 \u0003אחרים אומרים: אילו\u0004 (אילו לא) \u0003היה תמורה\u0004"]]};
